/* ======================================================================== */
/* library interface                                                        */
/* ======================================================================== */
/*
 * To embed postami in another program, #define POSTAMI_NO_MAIN before
 * including (or pasting) this file, then:
 *
 *     postami::Mail m;
 *     m.server = "mail.example.org";          // or m.config_file("postami.conf")
 *     m.user = "backup@example.org";
 *     m.password = "secret";
 *     m.from = "backup@example.org";
 *     m.to.push_back("admin@example.org");    // "a, b" lists are accepted too
 *     m.subject = "backup OK";
 *     m.body = "report...";
 *     m.attach("backup.log.zpaq");            // file sent as it is
 *     m.attachzip("backup.log");              // sent as backup.log.zip
 *     m.attach_data("summary.txt", text);     // or data already in memory
 *     int rc = m.send();                      // 0 = sent, see exit codes above
 *     if (rc) printf("%s: %s\n", postami::Mail::result_name(rc), m.error().c_str());
 *
 * send() never throws, never exits and prints nothing unless 'verbosity'
 * is set (0 errors, 1 warnings, 2 info, 3 SMTP dialogue, on stderr);
 * log() returns the complete log of the last send(), set_log_callback()
 * receives every line as it is produced. Not thread-safe: one send() at
 * a time.
 */
#include <string>
#include <vector>

namespace postami {

struct Attachment {                 /* a file to attach, already in memory */
    std::string path, name, data;
};

class Mail {
public:
    /* connection */
    std::string server;             /* required */
    int port;                       /* 0: 587, or 465 with ssl */
    bool ssl;                       /* implicit TLS (SMTPS) instead of STARTTLS */
    std::string user, password;     /* empty user: no authentication */
    std::string cafile;             /* empty: system CA store */
    std::string tls_name;           /* verify the certificate against this name */
    bool insecure;                  /* do not verify the certificate (tests only) */
    int timeout;                    /* seconds, default 30 */
    std::string helo;               /* default: local host name */
    /* message */
    std::string from;
    std::vector<std::string> to, cc, bcc;
    std::string reply_to;
    std::string subject;
    std::string body;               /* UTF-8 text */
    std::string body_file;          /* if set, the body is read from this file */
    /* logging */
    int verbosity;                  /* stderr: -1 nothing (default) .. 3 dialogue */
    std::string logfile;            /* append the full log to this file */

    Mail();
    void attach(const std::string &path);
    void attachzip(const std::string &path);        /* attached as path.zip */
    void attach_data(const std::string &name, const std::string &data);
    bool config_file(const std::string &path);      /* 'key = value' as for the CLI */
    bool config_text(const std::string &text, const std::string &source = "config");
    void set_log_callback(void (*cb)(void *ctx, int level, const char *line), void *ctx);
    int send();                                     /* 0 = sent */
    const std::string &error() const { return error_; }
    const std::string &log() const { return log_; }
    static const char *result_name(int code);

private:
    std::vector<std::string> files_, zipfiles_;
    std::vector<Attachment> data_;
    void (*callback_)(void *, int, const char *);
    void *callback_ctx_;
    std::string error_, log_;
};

} /* namespace postami */

