#define PSA_HASH_MAX_SIZE 20u

#define PSA_MAC_MAX_SIZE PSA_HASH_MAX_SIZE

#define PSA_VENDOR_RSA_GENERATE_MIN_KEY_BITS MBEDTLS_RSA_GEN_KEY_MIN_BITS

