/// here, then a giant READ ERROR at the end and the exit code 2 (see imagebanner)
int64_t				 g_imgerrori	 = 0;	  /// unreadable sectors
int64_t				 g_imgerroribytes= 0;	  /// their bytes (zeros in the image)
int64_t				 g_imgtratti	 = 0;	  /// the stretches of them (one after the other: one stretch)
int64_t				 g_imgfine		 = -1;	  /// where the last stretch ends
std::vector<int64_t> g_imgerroridove;		  /// the first 16 stretches: start (bytes from the start of the source), bytes
bool				 g_imgmorto		 = false; /// the source is gone: no more reads, zeros to the end
int64_t				 g_imgbuio		 = 0;	  /// pieces in a row that gave nothing: a dead zone, no more sector by sector
static void img_errore(int64_t i_dove, int64_t i_bytes, uint32_t i_settore)
{
	if (i_settore == 0)
		i_settore= 512;
	g_imgerrori+= (i_bytes + i_settore - 1) / i_settore;
	g_imgerroribytes+= i_bytes;
	if (i_dove == g_imgfine) /// the same stretch, longer (when it is one of the first 16)
	{
		if (g_imgtratti * 2 == (int64_t)g_imgerroridove.size())
			g_imgerroridove.back()+= i_bytes;
	}
	else
	{
		g_imgtratti++;
		if (g_imgerroridove.size() < 32)
		{
			g_imgerroridove.push_back(i_dove);
			g_imgerroridove.push_back(i_bytes);
		}
	}
	g_imgfine= i_dove + i_bytes;
}
