	char **c()
	{
		char **character= getCharGrid();
		for (int i= 0; i < 7; i++)
		{
			for (int j= 0; j < 7; j++)
			{
				// first aur last line
				if (i == 0 || i == 6)
				{
					if ((j % 7) % 3 != 0)
					{
						character[i][j]= '%';
					}
					else
					{
						character[i][j]= ' ';
					}
				}

				// second nd second last line

				if (i == 1 || i == 5)
				{
					if (((j) % 7) < 2 || ((j) % 7) > 4)
					{
						character[i][j]= '%';
					}
					else
					{
						character[i][j]= ' ';
					}
				}

				// rest

				if (i == 2 || i == 4 || i == 3)
				{
					if (((j) % 7) < 2)
					{
						character[i][j]= '%';
					}
					else
					{
						character[i][j]= ' ';
					}
				}
			}
		}
		return character;
	}
