char *mymigliaia(int64_t i_bytes, char *i_buffer, int i_buffersize)
{
	if (i_buffer == NULL)
	{
		printf("02096: guru i_buffer null\n");
		exit(0);
	}
	if (i_buffersize < 10)
	{
		printf("02106: guru buffer too small\n");
		exit(0);
	}
	if (i_bytes < 0)
	{
		snprintf(i_buffer, 10, "negative");
		return i_buffer;
	}

	char		*p= &i_buffer[i_buffersize - 1];
	unsigned int i= 0;
	*p			  = '\0';
	do
	{
		if ((i % 3 == 0) && (i != 0))
			*--p= '.';
		*--p= '0' + i_bytes % 10;
		i_bytes/= 10;
		i++;
	} while (i_bytes != 0);
	return p;
}

