/// the end, at once: the output files closed, the colors back. The exit code: 2 (the default) a fatal
/// error, the command did not do its job (it was 0: a script took it for a success); 0 a normal end
/// (the help, dir, q in the pager, the Goodbye of the interactive ones)
void seppuku(int i_codice= 2)
{
	if (g_output_handle)
		fclose(g_output_handle);
	if (g_error_handle)
		fclose(g_error_handle);

	color_restore();
	exit(i_codice);
}


bool ihavehw()
{
#ifndef HWSHA2
	return false;
#endif // corresponds to #ifndef (#ifndef HWSHA2)
	uint32_t a= 0, b= 0, c= 0, d= 0;
	getcpuid(0, 0, a, b, c, d);
	if (a < 7)
	{
		myprintf("10001! WARN: No hw SHA2 in CPU. Drop -DHWSHA2 to remove this warning\n");
		return false;
	}

	bool supported_ssse3= false;
	bool supported_sse41= false;
	bool supported_sha	= false;

	getcpuid(1, 0, a, b, c, d);
	supported_ssse3= (c & (1UL << 9));
	supported_sse41= (c & (1UL << 19));
	if (flagdebug3)
		myprintf("00002: new ecx %d\n", (int)c);

	getcpuid(7, 0, a, b, c, d);
	supported_sha= (b & (1UL << 29));
	if (flagdebug3)
		myprintf("00003: new ebx %d\n", (int)b);

	if (flagdebug)
	{
		myprintf("00004: SSSE3 :");
		if (supported_ssse3)
			myprintf("OK\n");
		else
			myprintf("NO\n");

		myprintf("00005: SSE41 :");
		if (supported_sse41)
			myprintf("OK\n");
		else
			myprintf("NO\n");

		myprintf("00006: SHA   :");
		if (supported_sha)
			myprintf("OK\n");
		else
			myprintf("NO\n");
	}
	return supported_ssse3 && supported_sse41 && supported_sha;
}

string print_datetime(bool i_flagout)
{
	int	   hours, minutes, seconds, day, month, year;
	time_t nowz;
	time(&nowz);
	const struct tm *local= localtime(&nowz);
	if (local == NULL)
	{
		myprintf("00007! guru on tm\n");
		exit(0);
	}
	hours  = local->tm_hour;
	minutes= local->tm_min;
	seconds= local->tm_sec;
	day	   = local->tm_mday;
	month  = local->tm_mon + 1;
	year   = local->tm_year + 1900;
	char buffer[40];
	snprintf(buffer, sizeof(buffer), "%02d/%02d/%d %02d:%02d:%02d ", day, month, year, hours, minutes, seconds);
	if (i_flagout)
		myprintf("%s", buffer);
	return buffer;
}

