using libzpaq::error;
// Portable thread types and functions for Windows and Linux. Use like this:
//
// // Create mutex for locking thread-unsafe code
// Mutex mutex;            // shared by all threads
// init_mutex(mutex);      // initialize in unlocked state
// Semaphore sem(n);       // n >= 0 is initial state
//
// // Declare a thread function
// ThreadReturn thread(void *arg) {  // arg points to in/out parameters
//   lock(mutex);          // wait if another thread has it first
//   release(mutex);       // allow another waiting thread to continue
//   sem.wait();           // wait until n>0, then --n
//   sem.signal();         // ++n to allow waiting threads to continue
//   return 0;             // must return 0 to exit thread
// }
//
// // Start a thread
// ThreadID tid;
// run(tid, thread, &arg); // runs in parallel
// join(tid);              // wait for thread to return
// destroy_mutex(mutex);   // deallocate resources used by mutex
// sem.destroy();          // deallocate resources used by semaphore



/*
	The stack of a thread. glibc gives every thread 8 MB (RLIMIT_STACK), musl
	only 128 KB, macOS 512 KB, FreeBSD 1 or 2 MB. The compressors of the old
	-m6/-m7 (LZ4, LZAV, gone in 65.5d) kept their hash tables on the stack,
	and libzpaq is not shy either: the static musl builds for NAS died with a
	segfault at the very first -m6/-m7 block. So these threads get at least
	8 MB. It is virtual
	memory: only the pages really touched cost RAM. Where the default is
	already that big (glibc) nothing changes
*/
int zpaq_thread_create(pthread_t *o_tid, void *(*i_f)(void *), void *i_arg)
{
	const size_t   minimo= (size_t)8 << 20;
	pthread_attr_t attributi;
	if (pthread_attr_init(&attributi) != 0)
		return pthread_create(o_tid, NULL, i_f, i_arg);
	size_t attuale= 0;
	if ((pthread_attr_getstacksize(&attributi, &attuale) == 0) && (attuale < minimo))
		pthread_attr_setstacksize(&attributi, minimo);
	const int risultato= pthread_create(o_tid, &attributi, i_f, i_arg);
	pthread_attr_destroy(&attributi);
	return risultato;
}
