class Semaphore
{
  public:
	enum
	{
		MAXCOUNT= 2000000000
	};
	Semaphore() : h(NULL)
	{
	}
	void init(int n)
	{
		assert(!h);
		h= CreateSemaphore(NULL, n, MAXCOUNT, NULL);
	}
	void destroy()
	{
		assert(h);
		CloseHandle(h);
	}
	int wait()
	{
		assert(h);
		return WaitForSingleObject(h, INFINITE);
	}
	void signal()
	{
		assert(h);
		ReleaseSemaphore(h, 1, NULL);
	}

  private:
	HANDLE h; // Windows semaphore
};
