string my_realpath(std::string const &i_path)
{
	if (i_path == "")
		return "";
	char   linkbuffer[66000]= {0};
	size_t linksize			= 66000;
	HANDLE h				= CreateFileW(utow(i_path.c_str()).c_str(), 0, 0, NULL, OPEN_EXISTING, FILE_FLAG_OPEN_REPARSE_POINT, NULL);
	char   buffer[MAXIMUM_REPARSE_DATA_BUFFER_SIZE];
	DWORD  dwBytesReturned= 0;
	DeviceIoControl(h, FSCTL_GET_REPARSE_POINT, NULL, 0, buffer, sizeof(buffer), &dwBytesReturned, 0);
	
	typedef struct
	{
		ULONG  ReparseTag;
		USHORT ReparseDataLength;
		USHORT Reserved;
		union  // Dai un nome all'unione
		{
			struct
			{
				USHORT SubstituteNameOffset;
				USHORT SubstituteNameLength;
				USHORT PrintNameOffset;
				USHORT PrintNameLength;
				ULONG  Flags;
				WCHAR  PathBuffer[1];
			} SymbolicLinkReparseBuffer;
			struct
			{
				USHORT SubstituteNameOffset;
				USHORT SubstituteNameLength;
				USHORT PrintNameOffset;
				USHORT PrintNameLength;
				WCHAR  PathBuffer[1];
			} MountPointReparseBuffer;
			struct
			{
				UCHAR DataBuffer[1];
			} GenericReparseBuffer;
		} u;  // Union name
	} REPARSE_DATA_BUFFER;
	
	REPARSE_DATA_BUFFER *pRDB= reinterpret_cast<REPARSE_DATA_BUFFER *>(buffer);
	if (pRDB->ReparseTag == IO_REPARSE_TAG_SYMLINK)
	{
		int		 nameLength= pRDB->u.SymbolicLinkReparseBuffer.SubstituteNameLength / sizeof(wchar_t);
		wchar_t *pName	   = (wchar_t *)((char *)pRDB->u.SymbolicLinkReparseBuffer.PathBuffer + pRDB->u.SymbolicLinkReparseBuffer.SubstituteNameOffset);
		WideCharToMultiByte(CP_UTF8, 0, pName, nameLength, linkbuffer, linksize, NULL, NULL);
		return linkbuffer;
	}
	CloseHandle(h);
	return "";
}
uint32_t convert_unicode_to_ansi_string(std::string &ansi, const wchar_t *unicode, const size_t unicode_size)
{
	uint32_t error= 0;
	do
	{
		if ((nullptr == unicode) || (0 == unicode_size))
		{
			error= ERROR_INVALID_PARAMETER;
			break;
		}
		ansi.clear();
		int required_cch= ::WideCharToMultiByte(
			CP_ACP,
			0,
			unicode, static_cast<int>(unicode_size),
			nullptr, 0,
			nullptr, nullptr);
		if (required_cch == 0)
		{
			error= ::GetLastError();
			break;
		}
		ansi.resize(required_cch);
		if (0 == ::WideCharToMultiByte(
					 CP_ACP,
					 0,
					 unicode, static_cast<int>(unicode_size),
					 const_cast<char *>(ansi.c_str()), static_cast<int>(ansi.size()),
					 nullptr, nullptr))
		{
			error= ::GetLastError();
			break;
		}
	} while (false);
	return error;
}
uint32_t convert_utf8_to_unicode_string(std::wstring &unicode, const char *utf8, const size_t utf8_size)
{
	uint32_t error= 0;
	do
	{
		if ((nullptr == utf8) || (0 == utf8_size))
		{
			error= ERROR_INVALID_PARAMETER;
			break;
		}
		unicode.clear();
		int required_cch= ::MultiByteToWideChar(
			CP_UTF8,
			MB_ERR_INVALID_CHARS,
			utf8, static_cast<int>(utf8_size),
			nullptr, 0);
		if (required_cch == 0)
		{
			error= ::GetLastError();
			break;
		}
		unicode.resize(required_cch);
		if (0 == ::MultiByteToWideChar(
					 CP_UTF8,
					 MB_ERR_INVALID_CHARS,
					 utf8, static_cast<int>(utf8_size),
					 const_cast<wchar_t *>(unicode.c_str()), static_cast<int>(unicode.size())))
		{
			error= ::GetLastError();
			break;
		}
	} while (false);
	return error;
}
// Windows: double converison
std::string utf8toansi(const std::string &utf8)
{
	if (utf8 == "")
		return "";
	std::wstring unicode= L"";
	std::string	 ansi	= "";
	if ((convert_utf8_to_unicode_string(unicode, utf8.c_str(), utf8.size()) == 0) &&
		(convert_unicode_to_ansi_string(ansi, unicode.c_str(), unicode.size()) == 0))
		return ansi;
	/// not valid UTF-8 (a Latin-1 name from an old *nix box, the two halves of a surrogate pair
	/// written by older versions): an empty result would make an EMPTY file name (utf -kill
	/// tried to rename into the folder). Every non-ASCII byte becomes '_', as on *nix
	ansi= utf8;
	for (size_t i= 0; i < ansi.size(); i++)
		if ((unsigned char)ansi[i] >= 128)
			ansi[i]= '_';
	return ansi;
}
string decodewinerror(DWORD i_error, const char *i_filename, bool i_padded= true); /// defined later
/*
	One object could not be erased. Count it, remember the first one and KEEP GOING:
	stopping at the very first error leaves the folder half-deleted and (without
	-debug) does not even say which object is the culprit
*/
void erredbarrasfallito(const std::wstring &wi_path, const char *i_cosa)
{
	const DWORD	 errore= GetLastError();
	const string nome  = wtou(wi_path.c_str());
	g_rd_errors++;
	if (g_rd_lasterror == 0)
	{
		g_rd_lasterror= (uint32_t)errore;
		g_rd_errorpath= nome;
	}
	if (flagdebug || flagverbose)
		myprintf("71342! rd cannot %s (%08d %s) <<%Z>>\n", i_cosa, (int)errore, decodewinerror(errore, NULL, false).c_str(), nome.c_str());
}
int erredbarras(const std::wstring &wi_path)
{
	const std::wstring wpattern= wi_path + L"\\*.*";
	const std::string  s_wipath= wtou(wi_path.c_str());
	if (flagdebug)
		myprintf("00014: get handle FOR %Z\n", (s_wipath + "/*.*").c_str());
	int secondi= (mtime() - g_startrd) / 1000;
	if (secondi != g_rd_ultimotempo)
	{
		g_rd_ultimotempo= secondi;
		if (g_rd_expected)
			myprintf("00015: Deleted objects %12s of (~) %12s @ %s/s\r", migliaia(g_rd), migliaia2(g_rd_expected), migliaia3(g_rd / secondi));
		else
			myprintf("00016: Deleted objects %12s\r", migliaia(g_rd));
	}
	WIN32_FIND_DATAW findfiledata;
	HANDLE			 myhandle= FindFirstFileW(wpattern.c_str(), &findfiledata);
	if (myhandle != INVALID_HANDLE_VALUE)
	{
		do
		{
			const std::string t= wtou(findfiledata.cFileName);
			if ((t != ".") && (t != ".."))
			{
				const std::wstring wfilepath  = wi_path + L"\\" + findfiledata.cFileName;
				const std::string  s_wfilepath= wtou(wfilepath.c_str());
				const DWORD		   attributi  = findfiledata.dwFileAttributes;
				const bool		   edir		  = (attributi & FILE_ATTRIBUTE_DIRECTORY) != 0;
				const bool		   ereparse	  = (attributi & FILE_ATTRIBUTE_REPARSE_POINT) != 0;
				if (flagdebug3)
					myprintf("00018: Working on %Z\n", s_wfilepath.c_str());
				/*
					NEVER walk into a junction (or a directory symlink): we would erase
					the files it points to, somewhere else on the disk. RemoveDirectory
					kills the link and leaves the target alone
				*/
				if (edir && (!ereparse))
				{
					if (flagdebug3)
					{
						myprintf("\n");
						myprintf("00019: recurse on %Z\n", s_wfilepath.c_str());
					}
					erredbarras(wfilepath);
					continue;
				}
				/// READONLY (and HIDDEN/SYSTEM) stops the delete: clear it, but only if set
				if (attributi & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM))
				{
					if (flagdebug3)
						myprintf("00020: set attribute on %Z\n", s_wfilepath.c_str());
					if (SetFileAttributesW(wfilepath.c_str(), FILE_ATTRIBUTE_NORMAL) == FALSE)
						if (flagdebug)
							myprintf("00021! ERROR cannot change attr of %Z\n", s_wfilepath.c_str());
				}
				if (flagdebug3)
					myprintf("00022: try to delete %Z\n", s_wfilepath.c_str());
				const bool fatto= edir ? (RemoveDirectoryW(wfilepath.c_str()) != FALSE)
									   : (DeleteFileW(wfilepath.c_str()) != FALSE);
				if (fatto)
					g_rd++;
				else
					erredbarrasfallito(wfilepath, edir ? "remove the junction" : "delete the file");
			}
		} while (FindNextFileW(myhandle, &findfiledata) == TRUE);
		FindClose(myhandle);
	}
	else if (flagdebug)
		myprintf("00017: Invalid handle %Z\n", s_wipath.c_str());
	/// and now the folder itself, even if something inside could not be deleted
	const DWORD attributi= GetFileAttributesW(wi_path.c_str());
	if (attributi == INVALID_FILE_ATTRIBUTES)
	{
		if (flagdebug)
			myprintf("71349: rd folder already gone (or unreachable) <<%Z>>\n", s_wipath.c_str());
		return (int)g_rd_lasterror;
	}
	if (attributi & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM))
	{
		if (flagdebug3)
			myprintf("00024: Change folder attr  %Z\n", s_wipath.c_str());
		if (SetFileAttributesW(wi_path.c_str(), FILE_ATTRIBUTE_NORMAL) == FALSE)
			if (flagdebug)
				myprintf("00025! ERROR cannot change folder attr %Z\n", s_wipath.c_str());
	}
	if (flagdebug3)
		myprintf("00026: RemoveDirectory  %Z\n", s_wipath.c_str());
	if (RemoveDirectoryW(wi_path.c_str()) == FALSE)
		erredbarrasfallito(wi_path, "remove the folder");
	else
		g_rd++;
	return (int)g_rd_lasterror;
}

int64_t getwinattributes(string i_filename)
{
	WIN32_FIND_DATA ffd;
	if ((i_filename.size() > 0) && (isdirectory(i_filename)))
		i_filename+= "*";
	HANDLE h= FindFirstFile(utow(i_filename.c_str()).c_str(), &ffd);
	if (h != INVALID_HANDLE_VALUE)
	{
		FindClose(h);
		return ffd.dwFileAttributes;
	}
	return 0;
}
/// reworked https://github.com/JFLarvoire/SysToolsLib/blob/master/C/MsvcLibX/src/readlink.c
typedef struct _REPARSE_READ_BUFFER
{
	DWORD ReparseTag;
	WORD  ReparseDataLength;
	WORD  Reserved;
	UCHAR DataBuffer[1];
} REPARSE_READ_BUFFER, *PREPARSE_READ_BUFFER;
bool getreparsepointW(bool i_flagdebug, const string i_path, char *i_buf, size_t i_bufsize, size_t &o_byteletti, DWORD &o_tag, string &o_type)
{
	o_byteletti= 0;
	o_tag	   = 0;
	o_type	   = "";
	myprintf("00028: REPPAAA\n");
	return true;
	wstring				 wi_path= utow(i_path.c_str());
	PREPARSE_READ_BUFFER pIoctlBuf;
	DWORD				 attributi= GetFileAttributesW(wi_path.c_str());
	if (attributi == INVALID_FILE_ATTRIBUTES)
	{
		myprintf("00029! failed GetFileAttributesW\n");
		return false;
	}
	if (!(attributi & FILE_ATTRIBUTE_REPARSE_POINT))
	{
		myprintf("00030! fake file is not a reparse point\n");
		return false;
	}
	DWORD flag= FILE_FLAG_OPEN_REPARSE_POINT;
	if (attributi & FILE_ATTRIBUTE_DIRECTORY)
		flag|= FILE_FLAG_BACKUP_SEMANTICS;
	HANDLE h= CreateFileW(wi_path.c_str(), 0, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, flag, NULL);
	if (h == INVALID_HANDLE_VALUE)
	{
		myprintf("00031! cannot createfile on reparse point\n");
		return false;
	}
	DWORD byteletti;
	BOOL  fattoio= DeviceIoControl(h, FSCTL_GET_REPARSE_POINT, NULL, 0, i_buf, (DWORD)i_bufsize, &byteletti, NULL);
	CloseHandle(h);
	if (!fattoio)
	{
		myprintf("00032! DeviceIoControl kaputt\n");
		return false;
	}
	if (byteletti < 8)
	{
		myprintf("00033! something wrong\n");
		return false;
	}
	pIoctlBuf  = (PREPARSE_READ_BUFFER)i_buf;
	o_tag	   = pIoctlBuf->ReparseTag;
	o_byteletti= pIoctlBuf->ReparseDataLength;
	switch (o_tag)
	{
	case 0x00000000:
		o_type= "Reserved0";
		break;
	case 0x00000001:
		o_type= "Reserved1";
		break;
	case 0x00000002:
		o_type= "Reserved2";
		break;
	case 0xA0000003:
		o_type= "Mount point or junction";
		break;
	case 0xC0000004:
		o_type= "Hierarchical Storage Manager";
		break;
	case 0x80000005:
		o_type= "Home server drive extender";
		break;
	case 0x80000006:
		o_type= "Hierarchical Storage Manager Product #2";
		break;
	case 0x80000007:
		o_type= "Single-instance storage filter driver";
		break;
	case 0x80000008:
		o_type= "Windows boot Image File";
		break;
	case 0x80000009:
		o_type= "Cluster Shared Volume";
		break;
	case 0x8000000A:
		o_type= "Distributed File System";
		break;
	case 0x8000000B:
		o_type= "Filter manager test harness";
		break;
	case 0xA000000C:
		o_type= "Symbolic link";
		break;
	case 0xA0000010:
		o_type= "Internet Information Services cache";
		break;
	case 0x80000012:
		o_type= "Distributed File System R filter";
		break;
	case 0x80000013:
		o_type= "Deduplicated file";
		break;
	case 0x80000014:
		o_type= "NFS symbolic link";
		break;
	case 0xC0000014:
		o_type= "APPXSTREAM (Not used?)";
		break;
	case 0x80000015:
		o_type= "Placeholder for a OneDrive file";
		break;
	case 0x80000016:
		o_type= "Dynamic File filter";
		break;
	case 0x80000017:
		o_type= "Windows Overlay Filesystem compressed file";
		break;
	case 0x80000018:
		o_type= "Windows Container Isolation filter";
		break;
	case 0xA0000019:
		o_type= "NPFS server silo named pipe symbolic link into the host silo";
		break;
	case 0x9000001A:
		o_type= "Cloud Files filter";
		break;
	case 0x8000001B:
		o_type= "Application Execution link";
		break;
	case 0x9000001C:
		o_type= "Projected File System VFS filter, ex for git";
		break;
	case 0xA000001D:
		o_type= "Linux Sub-System Symbolic Link";
		break;
	case 0x8000001E:
		o_type= "Azure File Sync (AFS) filter";
		break;
	case 0xA000001F:
		o_type= "Windows Container Isolation filter tombstone";
		break;
	case 0xA0000020:
		o_type= "Unhandled Windows Container Isolation filter";
		break;
	case 0xA0000021:
		o_type= "One Drive (Not used?)";
		break;
	case 0xA0000022:
		o_type= "Projected File System VFS filter tombstone, ex for git";
		break;
	case 0xA0000023:
		o_type= "Linux Sub-System Socket";
		break;
	case 0xA0000024:
		o_type= "Linux Sub-System FIFO";
		break;
	case 0xA0000025:
		o_type= "Linux Sub-System Character Device";
		break;
	case 0xA0000026:
		o_type= "Linux Sub-System Block Device";
		break;
	case 0xA0000027:
		o_type= "Windows Container Isolation filter Link";
		break;
	default:
		o_type= "35701: Microsoft strikes back!";
		break;
	}
	if (!i_flagdebug)
		return true;
	unsigned int ul;
	unsigned int u;
	unsigned int uMax;
	for (ul= 0; ul < (unsigned)(pIoctlBuf->ReparseDataLength); ul+= 16)
	{
		myprintf("%08X ", ul);
		uMax= (unsigned)(pIoctlBuf->ReparseDataLength) - ul;
		if (uMax > 16)
			uMax= 16;
		/* Display the hex dump */
		for (u= 0; u < 16; u++)
		{
			if (!(u & 3))
				myprintf(" ");
			if (u < uMax)
				myprintf("%2.2X ", ((unsigned char *)pIoctlBuf->DataBuffer)[ul + u]);
			else
				myprintf("   ");
		}
		/* Display the ASCII characters dump */
		for (u= 0; u < 16; u++)
		{
			char c= ((char *)pIoctlBuf->DataBuffer)[ul + u];
			if (!(u & 7))
				myprintf(" ");
			if (c < ' ')
				c= ' ';
			if ((unsigned char)c > '\x7F')
				c= ' ';
			myprintf("%c", c);
		}
		myprintf("\n");
	}
	return true;
}
