int terminalwidth()
{
#if defined(_WIN32)
	/// no console (redirected): see terminalheight(), same 80 of *nix
	CONSOLE_SCREEN_BUFFER_INFO csbi;
	if (!GetConsoleScreenBufferInfo(GetStdHandle(STD_OUTPUT_HANDLE), &csbi))
		return 80;
	int colonna= (int)csbi.srWindow.Right - csbi.srWindow.Left + 1;
	if ((colonna < 1) || (colonna > 200))
		colonna= 80;
	return colonna;
#else
	struct winsize w;
	int			   colonna= 80;
	if (ioctl(fileno(stdout), TIOCGWINSZ, &w) == 0)
		colonna= (w.ws_col);
	if (colonna > 200)
		colonna= 200;
	return colonna;
#endif // corresponds to #if (#if defined(_WIN32))
}
int terminalheight()
{
#if defined(_WIN32)
	/// stdout redirected (a .bat with > log, -out): no console, the call
	/// fails and csbi is whatever was on the stack. It was: c -checksum from
	/// the autotest printed thousands of garbage rows and crashed. Same 30
	/// of the *nix branch, when there is nothing to ask
	CONSOLE_SCREEN_BUFFER_INFO csbi;
	if (!GetConsoleScreenBufferInfo(GetStdHandle(STD_OUTPUT_HANDLE), &csbi))
		return 30;
	int riga= (int)csbi.srWindow.Bottom - csbi.srWindow.Top + 1;
	if ((riga < 1) || (riga > 200))
		riga= 30;
	return riga;
#else
	struct winsize w;
	int			   riga= 30;
	if (ioctl(fileno(stdout), TIOCGWINSZ, &w) == 0)
		riga= (w.ws_row);
	if (riga > 200)
		riga= 30;
	return riga;
#endif // corresponds to #if (#if defined(_WIN32))
}
bool iskeypressed(int i_thekey)
{
#ifdef _WIN32
	if (kbhit())
	{
		int keypressed= ::getch();
		if (flagdebug)
			printf("21029: WIN32 getch %d %c\n", keypressed, keypressed);
		if (i_thekey == 0)
			return true;
		else
			return (i_thekey == keypressed);
	}
	return false;
#else
	struct termios old_t;
	struct termios new_t;
	tcgetattr(0, &old_t);
	new_t= old_t;
	new_t.c_lflag&= ~(ICANON | ECHO);
	new_t.c_cc[VMIN] = 0;
	new_t.c_cc[VTIME]= 0;
	tcsetattr(0, TCSANOW, &new_t);
	char ch;
	int	 letti= read(0, &ch, 1);
	tcsetattr(0, TCSANOW, &old_t);
	if (i_thekey == 0)
		return (letti != 0);
	else
		return ((letti != 0) && (i_thekey == ch));
#endif // corresponds to #ifdef (#ifdef _WIN32)
}
int mygetch(bool i_flagmore)
{
	int mychar= 0;
#if defined(_WIN32)
	mychar= ::getch();
#endif // corresponds to #if (#if defined(_WIN32))
#ifdef unix
	/// BSD Unix
	struct termios oldt, newt;
	tcgetattr(STDIN_FILENO, &oldt);
	newt= oldt;
	newt.c_lflag&= ~(ICANON | ECHO);
	tcsetattr(STDIN_FILENO, TCSANOW, &newt);
	mychar= getchar();
	tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
#endif // corresponds to #ifdef (#ifdef unix)
	if (!i_flagmore)
		return mychar;
	if ((mychar == 113) || (mychar == 81) || (mychar == 3)) /// q, Q, control-C
	{
#ifdef unix
		myprintf("\n\n");
#endif // corresponds to #ifdef (#ifdef unix)
		seppuku(0);
	}
	return mychar;
}

