string purgeansi(const string& i_string, bool i_keeppath= false)
{
	if (i_string == "")
		return ("");
	string purged;
	for (unsigned int i= 0; i < i_string.length(); i++)
	{
		if (i_keeppath)
		{
			if ((i_string[i] == ':') || (i_string[i] == '/') || (i_string[i] == '\\'))
			{
				purged+= i_string[i];
				continue;
			}
		}
		if (isalnum(i_string[i]))
			purged+= i_string[i];
		else
		{
			switch (i_string[i])
			{
				/*
				very forbiden
				< (less than)
				> (greater than)
				: (colon)
				" (double quote)
				/ (forward slash)
				\ (backslash)
				| (vertical bar or pipe)
				? (question mark)
				* (asterisk)
				*/
			case ' ':
			case '-':
			case '#':
			case '~':
			case '%':
			case '^':
			case '_':
			case '.':
			case '+':
			case '=':
				purged+= i_string[i];
				break;
			case '&':
				purged+= "_and_";
				break;
			case ',':
			case '`':
			case '@':
			case '$':
			case '*':
			case '|':
			case ':':
			case ';':
			case '"':
			case '\'':
			case '<':
			case '>':
			case '\n':
			case '\r':
			case '\t':
				purged+= '_';
				break;
			case '(':
			case '{':
				purged+= '(';
				break;
			case ')':
			case '}':
				purged+= ')';
				break;
			default:
				purged+= '_';
			}
		}
	}
	return purged;
}
