// fix for Mac PowerPC (yes, no strlen here)
size_t mystrnlen(const char *i_string, size_t maxlen)
{
	if (i_string == NULL)
	{
		if (flagdebug)
			myprintf("00039! GURU null string\n");
		seppuku(); // safer to die
		exit(0);
		return 0;
	}
	if (maxlen == 0)
	{
		if (flagdebug)
			myprintf("00040! GURU maxlen 0\n");
		seppuku(); // safer to die
		exit(0);
		return 0;
	}
	size_t len;
	for (len= 0; len < maxlen; len++, i_string++)
		if (!*i_string)
			break;
	return len;
}

int64_t myatoll(const char *i_str)
{
	if (i_str == NULL)
		return 0;

	if (mystrnlen(i_str, 20) == 20) /// this should be 21, 9999999...TB
	{
		myprintf("00041! GURU on very long number (longer than 20 chars)\n");
		seppuku();
		exit(0);
	}
	string stringa= i_str;
	string thedigit;
	string thestring;
	for (unsigned int i= 0; i < stringa.length(); i++)
		if (isdigit(stringa[i]))
			thedigit+= stringa[i];
		else
		{
			if (isalpha(stringa[i]))
				thestring+= stringa[i];
		}
	int64_t risultato= atoll(thedigit.c_str());
	if (flagdebug3)
	{
		myprintf("00042: integer (string) |%s| %s\n", thedigit.c_str(), migliaia(thedigit.size()));
		myprintf("00043: integer          |%lld|\n", risultato);
		myprintf("00044: text part        |%s|\n", thestring.c_str());
	}
	thestring= stringtoupper(thestring);

	if (thestring.size() == 1)
	{
		if (toupper(thestring[0]) == 'K')
			risultato*= 1000;
		else if (toupper(thestring[0]) == 'M')
			risultato*= 1000000;
		else if (toupper(thestring[0]) == 'G')
			risultato*= 1000000000;
		else if (toupper(thestring[0]) == 'T')
			risultato*= 1000000000000LL;
	}
	else if (thestring.size() == 2)
	{
		if (thestring == "KB")
			risultato*= 1024;
		else if (thestring == "MB")
			risultato*= 1048576;
		else if (thestring == "GB")
			risultato*= 1073741824;
		else if (thestring == "TB")
			risultato*= 1099511627776LL;
	}
	else
	{
		///		if (flagdebug)
		///		myprintf("00045! ERROR string size not 1 or 2, ignoring [%s]\n",migliaia(thestring.size()));
	}

	if (flagdebug)
		myprintf("00046: final from %s to %s (%s)\n", i_str, migliaia(risultato), tohuman(risultato));

	if (risultato < 0)
	{
		myprintf("00047! GURU NEGATIVE! final from %s to %s (%s)\n", i_str, migliaia(risultato), tohuman(risultato));
		seppuku();
		exit(0);
		return 0;
	}
	return risultato;
}
/// no stoi() on old compiler
int mystoi(const string& i_string)
{
	if (i_string == "")
		return 0;
	int risultato= 0;
	for (unsigned int i= 0; i < i_string.size(); i++)
		if (isdigit(i_string[i]))
			risultato= risultato * 10 + i_string[i] - '0';
	return risultato;
}
int64_t encodestringdate(string i_date, bool i_flagfrom)
{
	i_date= format_datetime(i_date);
	string purged;
	for (unsigned int i= 0; i < i_date.length(); i++)
		if (isdigit(i_date[i]))
			purged+= i_date[i];
	int lunghezza= purged.length();
	if ((lunghezza > 14))
	{
		myprintf("00048! datelength >14 (%d) |%s|\n", lunghezza, purged.c_str());
		return -1;
	}
	if (lunghezza % 2 != 0)
	{
		myprintf("00049! datelength must be even (use leading zeros) (%d) |%s|\n", lunghezza, purged.c_str());
		return -1;
	}

	int year  = 0;
	int month = 0;
	int day	  = 0;
	int hour  = 0;
	int minute= 0;
	int second= 0;
	if (lunghezza >= 4)
		year= mystoi(purged.substr(0, 4));
	if (lunghezza >= 6)
		month= mystoi(purged.substr(4, 2));
	if (lunghezza >= 8)
		day= mystoi(purged.substr(6, 2));
	if (lunghezza >= 10)
		hour= mystoi(purged.substr(8, 2));
	if (lunghezza >= 12)
		minute= mystoi(purged.substr(10, 2));
	if (lunghezza >= 14)
		second= mystoi(purged.substr(12, 2));

	if (i_flagfrom)
	{
		if (lunghezza == 4) /// 2022
		{
			month= 1;
			day	 = 1;
		}
		if (lunghezza == 6) /// 202209
			day= 1;
	}
	else
	{
		if (lunghezza == 4) /// 2022
		{
			month= 12;
			day	 = 31;
		}
		if (lunghezza == 6) /// 202209
		{
			if (month == 2)
				day= 28;
			else if ((month == 4) || (month == 6) || (month == 9) || (month == 11))
				day= 30;
			else
				day= 31;
		}
	}
	if (flagdebug2)
		myprintf("00050: date   %04d-%02d-%02d %02d:%02d:%02d\n", year, month, day, hour, minute, second);
	if ((year < 1970) || (year > 2070))
	{
		myprintf("00051! year not from 1970 to 2070\n");
		return -1;
	}
	if ((month < 1) || (month > 12))
	{
		myprintf("00052! month not in [01..12]. Use leading zero (not 3 but 03)\n");
		return -1;
	}
	if ((day < 1) || (day > 31))
	{
		myprintf("00053! day not in [01..31]. Use leading zero (not 4 but 04)\n");
		return -1;
	}
	if (hour > 24)
	{
		myprintf("00054! hour >24\n");
		return -1;
	}
	if (minute > 60)
	{
		myprintf("00055! minute >60\n");
		return -1;
	}
	if (second > 60)
	{
		myprintf("00056! second >60\n");
		return -1;
	}
	bool isleap= (((year % 4 == 0) &&
				   (year % 100 != 0)) ||
				  (year % 400 == 0));

	if (month == 2)
	{
		if (isleap)
		{
			if (!(day <= 29))
			{
				myprintf("00057! leap year, feb must be <=29\n");
				return -1;
			}
		}
		else if (!(day <= 28))
		{
			myprintf("00058! NO leap year, feb must be <=28\n");
			return -1;
		}
	}
	if ((month == 4) || (month == 6) || (month == 9) || (month == 11))
		if (!(day <= 30))
		{
			myprintf("00059! this month (%d) cannot have more than 30 days\n", month);
			return -1;
		}

	return year * 10000000000LL + month * 100000000LL + day * 1000000 + hour * 10000 + minute * 100 + second;
}

// Convert non-negative decimal number x to string of at least n digits
string itos(int64_t x, int n= 1)
{
	assert(x >= 0);
	assert(n >= 0);
	string r;
	for (; x || n > 0; x/= 10, --n)
		r= string(1, '0' + x % 10) + r;
	return r;
}
// Replace * and ? in fn with part or digits of part
string subpart(string fn, int part)
{
	for (int j= fn.size() - 1; j >= 0; --j)
	{
		if (fn[j] == '?')
			fn[j]= '0' + part % 10, part/= 10;
		else if (fn[j] == '*')
			fn= fn.substr(0, j) + itos(part) + fn.substr(j + 1), part= 0;
	}
	return fn;
}
// Return relative time in milliseconds
/// Slow, working on string instead of char *. But who cares?
#define NO_WARNING_PLEASE 36

string internalutctolocal(const string &i_date)
{
	if (flagdebug3)
	{
		myprintf("\n");
		myprintf("00060: converting to localtime %s\n", i_date.c_str());
	}

	if (i_date.length() != 19)
	{
		myprintf("25854$ i_date is not 19 chars long |%s|\n", i_date.c_str());
		return i_date;
	}

	struct tm t;
	memset(&t, 0, sizeof(t));
	t.tm_year= atoi(i_date.c_str()) - 1900;
	t.tm_mon = atoi(i_date.c_str() + 5) - 1;
	t.tm_mday= atoi(i_date.c_str() + 8);
	t.tm_hour= atoi(i_date.c_str() + 11);
	t.tm_min = atoi(i_date.c_str() + 14);
	t.tm_sec = atoi(i_date.c_str() + 17);

#ifdef _WIN32
//
#ifdef _WIN64
	time_t tt= _mkgmtime64(&t);
#else

	time_t tt= -1;
///	time_t tt = _mkgmtime32(&t);
#endif // corresponds to #ifdef (#ifdef _WIN64)
	if (tt == -1)
		return i_date;
	struct tm *t2= NULL;
	t2			 = &t;
	*t2			 = *localtime(&tt);
#else
	/// not Windows
	time_t			 utcTime= timegm(&t); // convert to UTC
	const struct tm *t2		= localtime(&utcTime);
	if (t2 == NULL)
	{
		myprintf("25871$ ERROR in localtime!\n");
		return i_date;
	}
#endif // corresponds to #ifdef (#ifdef _WIN32)
	char ds[NO_WARNING_PLEASE];
	memset(ds, 0, NO_WARNING_PLEASE);

	snprintf(ds, NO_WARNING_PLEASE, "%04d-%02d-%02d %02d:%02d:%02d",
			 t2->tm_year + 1900,
			 t2->tm_mon + 1,
			 t2->tm_mday,
			 t2->tm_hour,
			 t2->tm_min,
			 t2->tm_sec);

	/// snprintf(ds,sizeof(ds),"%.4d-%.2d-%.2d %.2d:%.2d:%.2d", t2->tm_year + 1900,t2->tm_mon + 1, t2->tm_mday, t2->tm_hour, t2->tm_min, t2->tm_sec);
	if (flagdebug)
		myprintf("00061: localtime is %s\n", ds);
	return ds;
}

string ConvertUtcToLocalTime(const string &i_date)
{
	if (iswindowsxp()) /// Windows XP, Windows Server 2003
	{
		if (flagdebug3)
		{
			color_cyan();
			printbar('+');
			myprintf("29643: WARNING: XP or 2003, do not convert to local time!\n");
			color_restore();
		}
		return i_date;
	}
	return internalutctolocal(i_date);
}

// Convert 64 bit decimal YYYYMMDDHHMMSS to "YYYY-MM-DD HH:MM:SS"
// where -1 = unknown date, 0 = deleted.
/// l prints a date on every line, and localtime() is slow (glibc even stats
/// /etc/localtime every time). The UTC=>local offset is taken once for every
/// hour, and kept only if it is the same at both ends of that hour (the clock
/// moves at most once in an hour); else, or when in doubt, the slow way
static int64_t utc_daysfromcivil(int64_t i_y, unsigned i_m, unsigned i_d)
{
	i_y-= (i_m <= 2);
	const int64_t  era= (i_y >= 0 ? i_y : i_y - 399) / 400;
	const unsigned yoe= (unsigned)(i_y - era * 400);
	const unsigned doy= (153 * (i_m > 2 ? i_m - 3 : i_m + 9) + 2) / 5 + i_d - 1;
	const unsigned doe= yoe * 365 + yoe / 4 - yoe / 100 + doy;
	return era * 146097 + (int64_t)doe - 719468;
}
static void utc_civilfromdays(int64_t i_z, int64_t &o_y, unsigned &o_m, unsigned &o_d)
{
	i_z+= 719468;
	const int64_t  era= (i_z >= 0 ? i_z : i_z - 146096) / 146097;
	const unsigned doe= (unsigned)(i_z - era * 146097);
	const unsigned yoe= (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
	const unsigned doy= doe - (365 * yoe + yoe / 4 - yoe / 100);
	const unsigned mp = (5 * doy + 2) / 153;
	o_d				  = doy - (153 * mp + 2) / 5 + 1;
	o_m				  = mp < 10 ? mp + 3 : mp - 9;
	o_y				  = (int64_t)yoe + era * 400 + (o_m <= 2);
}
/// local minus UTC, in seconds, at the instant i_t
static bool utc_offsetat(int64_t i_t, int64_t &o_offset)
{
	time_t			 tt= (time_t)i_t;
#ifdef _WIN32
	const struct tm *lt= localtime(&tt);
#else
	struct tm		 lbuf;
	const struct tm *lt= localtime_r(&tt, &lbuf);
#endif // corresponds to #ifdef (#ifdef _WIN32)
	if (lt == NULL)
		return false;
	o_offset= utc_daysfromcivil(lt->tm_year + 1900, lt->tm_mon + 1, lt->tm_mday) * 86400 + lt->tm_hour * 3600 + lt->tm_min * 60 + lt->tm_sec - i_t;
	return true;
}
/// every slot is (hour << 24) | (offset + 2^23), in one word (0x0FFFFFF: the clock moves in that hour)
static uint64_t g_utchours[1024];
static void utc_put2(char *o_p, unsigned i_v)
{
	o_p[0]= char('0' + i_v / 10);
	o_p[1]= char('0' + i_v % 10);
}
/// i_date YYYYMMDDHHMMSS (UTC) => o_s "YYYY-MM-DD HH:MM:SS" local, as internalutctolocal(); false = do it the slow way
bool fastutctolocal(int64_t i_date, char *o_s)
{
	if (sizeof(void *) < 8) /// a slot is read and written in one go
		return false;
	if (flagdebug || flagdebug3)
		return false;
	static int xp= -1;
	if (xp < 0)
		xp= iswindowsxp() ? 1 : 0;
	if (xp)
		return false;
	const unsigned sec	= unsigned(i_date % 100);
	const unsigned mins = unsigned(i_date / 100 % 100);
	const unsigned hour = unsigned(i_date / 10000 % 100);
	const unsigned day	= unsigned(i_date / 1000000 % 100);
	const unsigned month= unsigned(i_date / 100000000 % 100);
	const int64_t  year = i_date / 10000000000LL;
	if ((year < 1971) || (year > 2999) || (month < 1) || (month > 12) || (day < 1) || (day > 31) || (hour > 23) || (mins > 59) || (sec > 59))
		return false;
	const int64_t t	  = utc_daysfromcivil(year, month, day) * 86400 + hour * 3600 + mins * 60 + sec;
	const int64_t ora = t / 3600;
	uint64_t	  slot= g_utchours[ora & 1023];
	if ((slot == 0) || ((int64_t)(slot >> 24) != ora))
	{
		int64_t inizio= 0;
		int64_t fine  = 0;
		if ((!utc_offsetat(ora * 3600, inizio)) || (!utc_offsetat(ora * 3600 + 3599, fine)))
			return false;
		if ((inizio != fine) || (inizio <= -(1 << 23)) || (inizio >= (1 << 23) - 1))
			slot= ((uint64_t)ora << 24) | 0x0FFFFFF;
		else
			slot= ((uint64_t)ora << 24) | (uint64_t)(inizio + (1 << 23));
		g_utchours[ora & 1023]= slot;
	}
	if ((slot & 0x0FFFFFF) == 0x0FFFFFF)
		return false;
	const int64_t locale  = t + (int64_t)(slot & 0x0FFFFFF) - (1 << 23);
	const int64_t giorni  = locale / 86400;
	const unsigned secondi= unsigned(locale % 86400);
	int64_t		  y		  = 0;
	unsigned	  m		  = 0;
	unsigned	  d		  = 0;
	utc_civilfromdays(giorni, y, m, d);
	if ((y < 1000) || (y > 9999))
		return false;
	utc_put2(o_s, unsigned(y / 100));
	utc_put2(o_s + 2, unsigned(y % 100));
	o_s[4]= '-';
	utc_put2(o_s + 5, m);
	o_s[7]= '-';
	utc_put2(o_s + 8, d);
	o_s[10]= ' ';
	utc_put2(o_s + 11, secondi / 3600);
	o_s[13]= ':';
	utc_put2(o_s + 14, secondi / 60 % 60);
	o_s[16]= ':';
	utc_put2(o_s + 17, secondi % 60);
	o_s[19]= 0;
	return true;
}

string dateToString(bool i_flagutc, int64_t date, bool i_mylocal= false)
{
	if (date <= 0)
		return "                   ";
	const int64_t	 thedate= date;
	string			 s	= "0000-00-00 00:00:00";
	static const int t[]= {18, 17, 15, 14, 12, 11, 9, 8, 6, 5, 3, 2, 1, 0};
	for (int i= 0; i < 14; ++i)
		s[t[i]]+= int(date % 10), date/= 10;
	if (!i_flagutc)
	{
		char veloce[20];
		if (fastutctolocal(thedate, veloce))
			s= veloce;
		else
			s= ConvertUtcToLocalTime(s);
	}
	if (i_mylocal)
	{
		/// string "0000-00-00 00:00:00";
		///	0123 56 89 12345
		char mylocal[30];
		mylocal[0] = s.at(8);
		mylocal[1] = s.at(9);
		mylocal[2] = '/';
		mylocal[3] = s.at(5);
		mylocal[4] = s.at(6);
		mylocal[5] = '/';
		mylocal[6] = s.at(0);
		mylocal[7] = s.at(1);
		mylocal[8] = s.at(2);
		mylocal[9] = s.at(3);
		mylocal[10]= ' ';
		mylocal[11]= ' ';
		mylocal[12]= s.at(11);
		mylocal[13]= s.at(12);
		mylocal[14]= s.at(13);
		mylocal[15]= s.at(14);
		mylocal[16]= s.at(15);
		mylocal[17]= 0;
		s		   = mylocal;
	}
	return s;
}

string dateToString_forcedlocal(bool i_flagutc, int64_t date)
{
	if (date <= 0)
		return "                   ";
	string			 s	= "0000-00-00 00:00:00";
	static const int t[]= {18, 17, 15, 14, 12, 11, 9, 8, 6, 5, 3, 2, 1, 0};
	for (int i= 0; i < 14; ++i)
		s[t[i]]+= int(date % 10), date/= 10;
	if (!i_flagutc)
	{
		s= internalutctolocal(s);
		/// myprintf("Converted to local %s\n",s.c_str());
	}
	return s;
}

int64_t nowutc()
{
	time_t	  mynow= time(NULL);
	const tm *t	   = gmtime(&mynow); // <-- gmtime instead of localtime
	if (t == NULL)
		return 0;
	return (t->tm_year + 1900) * 10000000000LL + (t->tm_mon + 1) * 100000000LL + t->tm_mday * 1000000 + t->tm_hour * 10000 + t->tm_min * 100 + t->tm_sec;
}

int64_t now()
{
	time_t	  mynow= time(NULL);
	const tm *t	   = localtime(&mynow);
	if (t == NULL)
		return 0;
	return (t->tm_year + 1900) * 10000000000LL + (t->tm_mon + 1) * 100000000LL + t->tm_mday * 1000000 + t->tm_hour * 10000 + t->tm_min * 100 + t->tm_sec;
}

string attrToString(int64_t attrib)
{
	string r= "     ";
	if ((attrib & 255) == 'u')
	{
		r[0]= "0pc3d5b7 9lBsDEF"[(attrib >> 20) & 15];
		for (int i= 0; i < 4; ++i)
			r[4 - i]= (attrib >> (8 + 3 * i)) % 8 + '0';
	}
	else if ((attrib & 255) == 'w')
	{
		for (int i= 0, j= 0; i < 32; ++i)
		{
			if ((attrib >> (i + 8)) & 1)
			{
				char c= "RHS DAdFTprCoIEivs89012345678901"[i];
				if (j < 5)
					r[j]= c;
				else
					r+= c;
				++j;
			}
		}
	}
	return r;
}
// Convert seconds since 0000 1/1/1970 to 64 bit decimal YYYYMMDDHHMMSS
// Valid from 1970 to 2099.
int64_t decimal_time(time_t tt)
{
	if (tt == -1)
		tt= 0;
	int64_t	  t		= (sizeof(tt) == 4) ? unsigned(tt) : tt;
	const int second= t % 60;
	const int minute= t / 60 % 60;
	const int hour	= t / 3600 % 24;
	t/= 86400;				  // days since Jan 1 1970
	const int term= t / 1461; // 4 year terms since 1970
	t%= 1461;
	t+= (t >= 59); // insert Feb 29 on non leap years
	t+= (t >= 425);
	t+= (t >= 1157);
	const int year= term * 4 + t / 366 + 1970; // actual year
	t%= 366;
	t+= (t >= 60) * 2; // make Feb. 31 days
	t+= (t >= 123);	   // insert Apr 31
	t+= (t >= 185);	   // insert June 31
	t+= (t >= 278);	   // insert Sept 31
	t+= (t >= 340);	   // insert Nov 31
	const int month= t / 31 + 1;
	const int day  = t % 31 + 1;
	return year * 10000000000LL + month * 100000000 + day * 1000000 + hour * 10000 + minute * 100 + second;
}
// Convert decimal date to time_t - inverse of decimal_time()
time_t unix_time(int64_t date)
{
	if (date <= 0)
		return -1;
	static const int days[12]= {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
	const int		 year	 = date / 10000000000LL % 10000;
	const int		 month	 = (date / 100000000 % 100 - 1) % 12;
	const int		 day	 = date / 1000000 % 100;
	const int		 hour	 = date / 10000 % 100;
	const int		 min	 = date / 100 % 100;
	const int		 sec	 = date % 100;
	if (month < 0)
		return 0;
	return (day - 1 + days[month] + (year % 4 == 0 && month > 1) + ((year - 1970) * 1461 + 1) / 4) * 86400 + hour * 3600 + min * 60 + sec;
}
