{
#ifndef _WIN32
	struct termios term;
	tcgetattr(STDIN_FILENO, &term);
	term.c_lflag|= ECHO | ICANON;
	tcsetattr(STDIN_FILENO, TCSANOW, &term);
#endif // corresponds to #ifndef (#ifndef _WIN32)
}

