typedef struct
{
	char buffer[MAX_PWD_LEN];
	int	 cursor_pos;
	int	 length;
} sinputstate;

#ifdef _WIN32
void enable_raw_mode()
{
	HANDLE hStdin= GetStdHandle(STD_INPUT_HANDLE);
	SetConsoleMode(hStdin, ENABLE_PROCESSED_INPUT);
}

void disable_raw_mode()
{
	HANDLE hStdin= GetStdHandle(STD_INPUT_HANDLE);
	SetConsoleMode(hStdin, ENABLE_ECHO_INPUT | ENABLE_LINE_INPUT | ENABLE_PROCESSED_INPUT);
}

int read_key()
{
	int ch= _getch();
	if (iscontrolsomething(ch)) /// ESC, control-C
	{
		restore_terminal_echo();
		myprintf("\n");
		myprintf("42262: Win: exiting due to strange key pressed |%d|\n", ch & 255);
		seppuku();
	}

	if ((ch == 224) || (ch == 0))
	{
		ch= _getch();
		switch (ch)
		{
		case 75:
			return 1000; // left
		case 77:
			return 1001; // right
		case 72:
			return 1002; // up
		case 80:
			return 1003; // down
		case 83:
			return 1004; // Del
		case 82:
			return 1005; // Ins
		default:
			return ch;
		}
	}
	return ch;
}

#else
struct termios orig_termios;

void enable_raw_mode()
{
	struct termios raw;
	tcgetattr(STDIN_FILENO, &orig_termios);
	raw= orig_termios;
	raw.c_lflag&= ~(ECHO | ICANON);
	raw.c_cc[VMIN] = 1;
	raw.c_cc[VTIME]= 0;
	tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw);
}

void disable_raw_mode()
{
	tcsetattr(STDIN_FILENO, TCSAFLUSH, &orig_termios);
}

int read_key()
{
	int ch= getchar();
	if (iscontrolsomething(ch)) /// ESC, control-C
	{
		restore_terminal_echo();
		myprintf("\n");
		myprintf("42099: *nix exiting due to strange key pressed |%d|\n", ch & 255);
		seppuku();
	}

	if (ch == 27)
		if (getchar() == '[')
			switch (getchar())
			{
			case 'D':
				return 1000; // left
			case 'C':
				return 1001; // right
			case 'A':
				return 1002; // up
			case 'B':
				return 1003; // down
			case '3':		 // Del (longer escape)
				getchar();	 // final ~
				return 1004;
			case '2':	   //  Ins
				getchar(); // final ~
				return 1005;
			}
	return ch;
}
#endif // corresponds to #ifdef (#ifdef _WIN32)

// Generic input handling functions
void insert_char(sinputstate *state, char ch)
{
	if (state->length < MAX_PWD_LEN - 1)
	{
		// move to right
		memmove(state->buffer + state->cursor_pos + 1,
				state->buffer + state->cursor_pos,
				state->length - state->cursor_pos);
		state->buffer[state->cursor_pos]= ch;
		state->cursor_pos++;
		state->length++;
		state->buffer[state->length]= '\0';
	}
}

void delete_char(sinputstate *state)
{
	// backspace
	if (state->cursor_pos > 0)
	{
		// move to left
		memmove(state->buffer + state->cursor_pos - 1,
				state->buffer + state->cursor_pos,
				state->length - state->cursor_pos + 1); // +1 per includere il terminatore
		state->cursor_pos--;
		state->length--;
	}
}

void delete_char_forward(sinputstate *state)
{
	// Del
	if (state->cursor_pos < state->length)
	{
		// move to left from current pos
		memmove(state->buffer + state->cursor_pos,
				state->buffer + state->cursor_pos + 1,
				state->length - state->cursor_pos);

		state->length--;
	}
}

void move_cursor(sinputstate *state, int direction)
{
	switch (direction)
	{
	case 1000: // left
		if (state->cursor_pos > 0)
			state->cursor_pos--;
		break;
	case 1001: // right

		if (state->cursor_pos < state->length)
			state->cursor_pos++;
		break;
	}
}

void redraw_input(sinputstate *state, const string& i_testo)
{
	printf("\r");

	setupConsole();
	printf("\033[K"); // clear up to end
	restoreConsole();

	color_yellow();
	myprintf("%s", i_testo.c_str());
	color_restore();

	// Print the contents of the buffer
	for (int i= 0; i < state->length; i++)
		if (flagdebug)
			printf("%c", state->buffer[i]);
		else
			printf("*");

	printf("\r");
	setupConsole();
	for (int unsigned i= 0; i < i_testo.size() + state->cursor_pos; i++)
		printf("\033[C"); // toright

	restoreConsole();
	fflush(stdout);
}

/// stdin at EOF (script, cron, < /dev/null): nobody can type the password, do not spin forever
void password_eof()
{
	restore_terminal_echo();
	myprintf("\n");
	color_red();
	myprintf("42265! Password required, but stdin is closed (EOF): cannot read it. Use -key\n");
	color_restore();
	exit(2);
}

string internal_password_withcursor(string i_default)
{
	if (flagsilent)
		return "";
	string		myresult= "";
	sinputstate state;
	memset(&state, 0, sizeof(state));
	int ch;

	myprintf("\n");
	if (i_default == "")
		i_default= "Enter password :";
	redraw_input(&state, i_default);
	enable_raw_mode();

	while (1)
	{
		ch= read_key();

		if (ch == EOF)
		{
			disable_raw_mode();
			password_eof();
		}
		if ((ch == '\n') || (ch == '\r'))
			break; // CR

		if ((ch == 127) || (ch == '\b') || (ch == 8)) // Backspace
			delete_char(&state);
		else if ((ch == 1000) || (ch == 1001)) // left/right
			move_cursor(&state, ch);
		else if (ch == 1004) // Del
			delete_char_forward(&state);
		else if (isprint(ch)) // goodchar
			insert_char(&state, ch);
		redraw_input(&state, i_default);
	}

	disable_raw_mode();
	myprintf("\n");
	myresult= state.buffer;
	if (flagdebug)
		myprintf("42074: Password |%s|\n", myresult.c_str());
	return myresult;
}

string internal_password_nocursor(const string& i_default)
{
	if (flagsilent)
		return "";
	string myresult= "";
	myprintf("\n");
	color_yellow();
	if (i_default != "")
		myprintf("42040: %s :", i_default.c_str());
	else
		myprintf("42025: Enter password :");
	color_restore();

	char password[MAX_PWD_LEN];
	memset(password, 0, MAX_PWD_LEN);
	int pos= 0;
	int ch;

	disable_terminal_echo();

	while (1)
	{
		ch= read_char();

		if (ch == EOF)
			password_eof();
		if ((ch == '\n') || (ch == '\r'))
			break; // CR

		///		printf(" |%03d| \n",ch&255);
		// backspace
		if ((ch == 127) || (ch == '\b') || (ch == 8))
		{
			if (pos > 0)
			{
				pos--;
				password[pos]= '\0';
				printf("\b \b"); // Delete the last asterisk
				fflush(stdout);
			}
		}
		// Normal characters
		else if (iscontrolsomething(ch)) /// ESC, control-C
		{
			restore_terminal_echo();
			myprintf("\n");
			myprintf("02053: Exiting due to strange key pressed |%d|\n", ch & 255);
			seppuku();
		}
		else if (isprint(ch))
			if (pos < MAX_PWD_LEN - 1)
			{
				password[pos]= ch;
				pos++;
				printf("*");
				fflush(stdout);
			}
	}

	restore_terminal_echo();
	myprintf("\n");
	myresult= password;
	if (flagdebug)
		myprintf("42074: Password |%s|\n", myresult.c_str());
	return myresult;
}

string mygetpasswordblind(const string& i_default)
{
	string risultato;

	if (flagnocolor)
		risultato= internal_password_nocursor(i_default);
	else
		risultato= internal_password_withcursor(i_default);
	if (g_keyfilehash != "")
		risultato+= g_keyfilehash;
	return risultato;
}
