bool g_franzen_alreadywritten;
	

// Base of InputArchive and OutputArchive
class ArchiveBase
{
  protected:
	libzpaq::AES_CTR *aes; // NULL if not encrypted
	FP				  fp;  // currently open file or FPNULL
	 public:
	ArchiveBase() : aes(0), fp(FPNULL)
	{
	}
	~ArchiveBase()
	{
		if (aes)
			delete aes;
		if (fp != FPNULL)
			myfclose(&fp);
	}
	bool isopen()
	{
		return fp != FPNULL;
	}
	FP getthefp()
	{
		return fp;
	}
};

// Archive type enumeration
enum ArchiveType
{
	ARCHIVE_ZPAQ_PLAIN,      // .zpaq no encryption
	ARCHIVE_ZPAQ_AES,        // .zpaq with AES encryption
	ARCHIVE_ZPAQ_FRANZEN,    // .zpaq.franzen with Franzen only
	ARCHIVE_ZPAQ_AES_FRANZEN // .zpaq.franzen with AES + Franzen
};

// An InputArchive supports encrypted reading
class InputArchive : public ArchiveBase, public libzpaq::Reader
{
	vector<int64_t> sz; // part sizes
	int64_t			total_sz;
	int64_t			off; // current offset
	string			fn;	 // filename, possibly multi-part with wildcards
	
	ArchiveType     archive_type;  // detected archive type
	string          physical_file; // actual file to open (.zpaq or .zpaq.franzen)
	bool            uses_franzen;  // true if Franzen encryption is present
	
  public:
	vector<string> filepartnames;
	string		   lastfilename;

	// franzen-only archives are readable even with fp==FPNULL (decrypted via franzcri)
	bool isopen()
	{
#ifndef NOFRANZEN
#ifdef ZPAQFULL /// NOSFTPSTART
		if (uses_franzen)
			return true;
#endif /// NOSFTPEND
#endif
		return fp != FPNULL;
	}

	// Open filename. If password then decrypt input.
	InputArchive(const char *filename);
	
	// Read and return 1 byte or -1 (EOF)
	int get()
	{
		error("get() not implemented");
		return -1;
	}
	
	int64_t get_totalsize()
	{
		return total_sz;
	}
	
	// Read up to len bytes into obuf at current offset. Return 0..len bytes
	// actually read. 0 indicates EOF.
	int read(char *obuf, int len);
	
	// Like fseeko()
	void seek(int64_t p, int whence);
	
	// Like ftello()
	int64_t tell()
	{
		return off;
	}
	
	int64_t totalsize()
	{
		int64_t temp= 0;
		for (unsigned i= 0; i < sz.size(); ++i)
			temp+= sz[i];
		return temp;
	}
	
  private:
	// Detect archive type and set physical_file
	ArchiveType detect_archive_type(const string& base_file);
	
	// Read first bytes from physical file (handling Franzen if needed)
	bool read_header_bytes(char* buffer, size_t len);
};

// Helper functions to identify file types


bool is_file_franzen(const string& filename) {
    FILE* f = fopen(filename.c_str(), "rb");
    if (f == NULL) return false;
    char magic[8];
    bool result = false;
    if (fread(magic, 1, 8, f) == 8)
        result = (memcmp(magic, "FRANZEN\x1a", 8) == 0) ||
                 (memcmp(magic, "FRENZEN\x1a", 8) == 0);
    fclose(f);
    return result;
}

// True only for AES+Franzen files (FRENZEN magic): they need -key too
bool is_file_frenzen(const string& filename) {
    FILE* f = fopen(filename.c_str(), "rb");
    if (f == NULL) return false;
    char magic[8];
    bool result = false;
    if (fread(magic, 1, 8, f) == 8)
        result = (memcmp(magic, "FRENZEN\x1a", 8) == 0);
    fclose(f);
    return result;
}

// Check if file starts with ZPAQ magic (7kSt) or zPQ

// fopen "unicode-safe": su Windows converte il nome (atteso in UTF-8)
// in UTF-16 e usa _wfopen; altrove e' un fopen normale.
static FILE* xfopen(const string& filename, const char* mode)
{
#ifdef _WIN32
    int wlen = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS,
                                   filename.c_str(), -1, NULL, 0);
    if (wlen > 0)
    {
        wstring wname(wlen, 0);
        MultiByteToWideChar(CP_UTF8, 0, filename.c_str(), -1, &wname[0], wlen);
        wstring wmode(mode, mode + strlen(mode));
        FILE* f = _wfopen(wname.c_str(), wmode.c_str());
        if (f != NULL)
            return f;
    }
    // fallback: stringa non UTF-8 valida (es. gia' in codepage ANSI)
    return fopen(filename.c_str(), mode);
#else
    return fopen(filename.c_str(), mode);
#endif
}

bool is_file_zpaq(const string& filename)
{
    FILE* f = xfopen(filename, "rb");
    if (f == NULL)
        return false;
    unsigned char magic[4] = {0};
    bool result = false;
    if (fread(magic, 1, 4, f) == 4)
    {
        const bool is_7kSt = (memcmp(magic, "7kSt", 4) == 0);
        const bool is_zPQ  = (memcmp(magic, "zPQ",  3) == 0) && (magic[3] >= 1);
        result = is_7kSt || is_zPQ;
    }
    fclose(f);
    return result;
}
