// Helper: Ensure path has long path prefix (>260 char)
static std::wstring fixLongPath(const std::wstring& path)
{
    if (path.empty()) return path;
    if (path.rfind(L"\\\\?\\", 0) == 0) return path; // Già presente
    // UNC (network) vs local path management
    if (path.rfind(L"\\\\", 0) == 0) return L"\\\\?\\UNC" + path.substr(1);
    return L"\\\\?\\" + path;
}

#ifdef DLL
static bool EnablePrivilege(LPCWSTR privilegeName)
{
	return false;
}
#else
// Helper: Enable a privilege in the current process token
static bool EnablePrivilege(LPCWSTR privilegeName)
{
    HANDLE hToken;
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &hToken))
        return false;

    LUID luid;
    if (!LookupPrivilegeValueW(NULL, privilegeName, &luid))
    {
        CloseHandle(hToken);
        return false;
    }

    TOKEN_PRIVILEGES tp;
    tp.PrivilegeCount = 1;
    tp.Privileges[0].Luid = luid;
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;

    BOOL ok = AdjustTokenPrivileges(hToken, FALSE, &tp, sizeof(TOKEN_PRIVILEGES), NULL, NULL);
    DWORD err = GetLastError();
    CloseHandle(hToken);
    
    return ok && (err != ERROR_NOT_ALL_ASSIGNED);
}
#endif

// Contatore file/cartelle schedulati per cancellazione al prossimo riavvio.
// Resettato all'inizio di deleteExcludedFiles, letto alla fine per il riepilogo.
static int64_t s_rebootScheduled = 0;

// Helper: Tenta di forzare Ownership (Admin) e Full Control
#ifdef DLL
static bool forceFilePermissions(const std::wstring& path)
{
	return false;
}
#else
static bool forceFilePermissions(const std::wstring& path)
{
    /// NOTA CRITICA: SetNamedSecurityInfoW NON supporta il prefisso
    // (aggiunto da fixLongPath), quindi falliva silenziosamente su ogni path.
    // Usiamo SetSecurityInfo su handle, che funziona con qualsiasi lunghezza path.
    PSID pSidAdmins = NULL;
    SID_IDENTIFIER_AUTHORITY SIDAuthNT = SECURITY_NT_AUTHORITY;

    if (!AllocateAndInitializeSid(&SIDAuthNT, 2,
            SECURITY_BUILTIN_DOMAIN_RID, DOMAIN_ALIAS_RID_ADMINS,
            0, 0, 0, 0, 0, 0, &pSidAdmins))
        return false;

    bool result = false;

    // Passo 1: prendi ownership (SE_TAKE_OWNERSHIP_NAME bypassa DACL per WRITE_OWNER)
    HANDLE h = CreateFileW(path.c_str(), WRITE_OWNER,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        NULL, OPEN_EXISTING,
        FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT, NULL);

    if (h != INVALID_HANDLE_VALUE)
    {
        SetSecurityInfo(h, SE_FILE_OBJECT, OWNER_SECURITY_INFORMATION,
            pSidAdmins, NULL, NULL, NULL);
        CloseHandle(h);
    }

    // Passo 2: imposta DACL — ora siamo owner, WRITE_DAC è consentito
    h = CreateFileW(path.c_str(), WRITE_DAC | READ_CONTROL,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        NULL, OPEN_EXISTING,
        FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT, NULL);

    if (h != INVALID_HANDLE_VALUE)
    {
        EXPLICIT_ACCESSW ea = {};
        ea.grfAccessPermissions = GENERIC_ALL;
        ea.grfAccessMode = SET_ACCESS;
        ea.grfInheritance = OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE;
        ea.Trustee.TrusteeForm = TRUSTEE_IS_SID;
        ea.Trustee.TrusteeType = TRUSTEE_IS_GROUP;
        ea.Trustee.ptstrName = reinterpret_cast<LPWSTR>(pSidAdmins);

        PACL pNewDacl = NULL;
        if (SetEntriesInAclW(1, &ea, NULL, &pNewDacl) == ERROR_SUCCESS)
        {
            result = (SetSecurityInfo(h, SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION | UNPROTECTED_DACL_SECURITY_INFORMATION,
                NULL, NULL, pNewDacl, NULL) == ERROR_SUCCESS);
            LocalFree(pNewDacl);
        }
        CloseHandle(h);
    }

    FreeSid(pSidAdmins);
    return result;
}
#endif
// Aggressive deletion of a single FILE
static bool deleteFileAggressive(const std::wstring& i_filepath)
{
    std::wstring path = fixLongPath(i_filepath);
    DWORD err;

    // ATTEMPT 1: Direct deletion
    if (DeleteFileW(path.c_str())) return true;
    err = GetLastError();
    if (err == ERROR_FILE_NOT_FOUND || err == ERROR_PATH_NOT_FOUND) return true;
    if (flagdebug3)
        myprintf("47901: deleteFile attempt1 (direct) err=%lu: %ls\n", err, i_filepath.c_str());

    // ATTEMPT 2: Remove Read-Only/Hidden/System attributes
    DWORD attrs = GetFileAttributesW(path.c_str());
    if (attrs != INVALID_FILE_ATTRIBUTES &&
        (attrs & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM)))
    {
        SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_NORMAL);
        if (DeleteFileW(path.c_str())) return true;
        err = GetLastError();
        if (flagdebug3)
            myprintf("47902: deleteFile attempt2 (strip attrs) err=%lu: %ls\n", err, i_filepath.c_str());
    }

    // ATTEMPT 3: Force Permissions (Ownership + ACL via handle) and retry
    if (forceFilePermissions(path))
    {
        SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_NORMAL);
        if (DeleteFileW(path.c_str())) return true;
        err = GetLastError();
        if (flagdebug3)
            myprintf("47903: deleteFile attempt3 (force perms) err=%lu: %ls\n", err, i_filepath.c_str());
    }
    else if (flagdebug3)
    {
        myprintf("47903b: deleteFile forceFilePermissions failed: %ls\n", i_filepath.c_str());
    }

    // ATTEMPT 4: MoveFile trick (rename and delete)
    std::wstring tempName = path + L".~del~";
    DeleteFileW(tempName.c_str());
    if (MoveFileW(path.c_str(), tempName.c_str()))
    {
        if (DeleteFileW(tempName.c_str())) return true;
        path = tempName;
        if (flagdebug3)
        {
            err = GetLastError();
            myprintf("47904: deleteFile attempt4 (rename+del) rinominato ma del fallito err=%lu\n", err);
        }
    }
    else if (flagdebug3)
    {
        err = GetLastError();
        myprintf("47904b: deleteFile attempt4 (rename) fallito err=%lu: %ls\n", err, i_filepath.c_str());
    }

    // ATTEMPT 5: Schedule deletion at Reboot
    if (MoveFileExW(path.c_str(), NULL, MOVEFILE_DELAY_UNTIL_REBOOT))
    {
        s_rebootScheduled++;
        color_magenta();
        myprintf("47905: *** RIAVVIO NECESSARIO *** file schedulato per cancellazione: %ls\n", i_filepath.c_str());
        color_restore();
        return true;
    }

    err = GetLastError();
    if (flagdebug3)
        myprintf("47906: deleteFile TUTTI I TENTATIVI FALLITI err=%lu: %ls\n", err, i_filepath.c_str());

    return false;
}
// Aggressive deletion of a DIRECTORY (recursive)
static bool deleteDirectoryAggressive(const std::wstring& i_dirpath)
{
    std::wstring path = fixLongPath(i_dirpath);
    DWORD err;

    // TENTATIVO 1: Diretto (funziona solo se già vuota e senza problemi ACL)
    if (RemoveDirectoryW(path.c_str())) return true;
    err = GetLastError();
    if (err == ERROR_FILE_NOT_FOUND || err == ERROR_PATH_NOT_FOUND) return true;
    if (flagdebug3)
        myprintf("47910: deleteDir attempt1 (direct) err=%lu: %ls\n", err, i_dirpath.c_str());

    // Forza permessi e azzera attributi sulla root della cartella
    if (!forceFilePermissions(path) && flagdebug3)
        myprintf("47911: deleteDir forcePerms fallito sulla root: %ls\n", i_dirpath.c_str());
    DWORD attrs = GetFileAttributesW(path.c_str());
    if (attrs != INVALID_FILE_ATTRIBUTES &&
        (attrs & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM)))
    {
        SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_NORMAL);
    }

    // Enumera il contenuto
    std::wstring searchPath = path;
    if (searchPath.back() != L'\\') searchPath += L'\\';
    searchPath += L'*';

    WIN32_FIND_DATAW fd;
    HANDLE hFind = FindFirstFileW(searchPath.c_str(), &fd);

    // Se FindFirstFile fallisce (ACL impedisce il listing), ritenta dopo un secondo forcePerms
    if (hFind == INVALID_HANDLE_VALUE)
    {
        err = GetLastError();
        if (flagdebug3)
            myprintf("47912: deleteDir FindFirstFile err=%lu, secondo forcePerms: %ls\n",
                err, i_dirpath.c_str());
        forceFilePermissions(path);
        SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_NORMAL);
        hFind = FindFirstFileW(searchPath.c_str(), &fd);
        if (hFind == INVALID_HANDLE_VALUE && flagdebug3)
            myprintf("47913: deleteDir FindFirstFile ancora fallito err=%lu: %ls\n",
                GetLastError(), i_dirpath.c_str());
    }

    if (hFind != INVALID_HANDLE_VALUE)
    {
        do
        {
            if (wcscmp(fd.cFileName, L".") == 0 || wcscmp(fd.cFileName, L"..") == 0)
                continue;

            std::wstring childPath = path;
            if (childPath.back() != L'\\') childPath += L'\\';
            childPath += fd.cFileName;

            if (fd.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT)
            {
                // Junction/Symlink: NON entrare nel target, rimuovi solo il link
                if (fd.dwFileAttributes & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_SYSTEM | FILE_ATTRIBUTE_HIDDEN))
                    SetFileAttributesW(childPath.c_str(), FILE_ATTRIBUTE_NORMAL);
                if (!RemoveDirectoryW(childPath.c_str()))
                {
                    DWORD rerr = GetLastError();
                    if (flagdebug3)
                        myprintf("47914: deleteDir reparse RemoveDir err=%lu: %ls\n", rerr, childPath.c_str());
                    if (rerr == ERROR_DIRECTORY)
                        deleteFileAggressive(childPath);
                    else
                    {
                        forceFilePermissions(childPath);
                        SetFileAttributesW(childPath.c_str(), FILE_ATTRIBUTE_NORMAL);
                        if (!RemoveDirectoryW(childPath.c_str()) && !deleteFileAggressive(childPath))
                        {
                            if (MoveFileExW(childPath.c_str(), NULL, MOVEFILE_DELAY_UNTIL_REBOOT))
                        {
                            s_rebootScheduled++;
                            color_magenta();
                            myprintf("47914b: *** RIAVVIO NECESSARIO *** reparse schedulato: %ls\n", childPath.c_str());
                            color_restore();
                        }
                        else if (flagdebug3)
                            myprintf("47914c: reparse MoveFileEx fallito err=%lu: %ls\n", GetLastError(), childPath.c_str());
                        }
                    }
                }
            }
            else if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)
            {
                // IMPORTANTE: forza permessi sul figlio PRIMA di ricorrere,
                // altrimenti FindFirstFile sul figlio potrebbe fallire per ACL restrittivi
                forceFilePermissions(childPath);
                DWORD cattrs = GetFileAttributesW(childPath.c_str());
                if (cattrs != INVALID_FILE_ATTRIBUTES &&
                    (cattrs & (FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM)))
                {
                    SetFileAttributesW(childPath.c_str(), FILE_ATTRIBUTE_NORMAL);
                }
                if (!deleteDirectoryAggressive(childPath))
                {
                    if (MoveFileExW(childPath.c_str(), NULL, MOVEFILE_DELAY_UNTIL_REBOOT))
                    {
                        s_rebootScheduled++;
                        color_magenta();
                        myprintf("47915: *** RIAVVIO NECESSARIO *** sottocartella schedulata: %ls\n", childPath.c_str());
                        color_restore();
                    }
                    else if (flagdebug3)
                        myprintf("47915b: figlio MoveFileEx fallito err=%lu: %ls\n", GetLastError(), childPath.c_str());
                }
            }
            else
            {
                if (!deleteFileAggressive(childPath) && flagdebug3)
                    myprintf("47916: deleteDir file figlio non cancellato: %ls\n", childPath.c_str());
            }

        } while (FindNextFileW(hFind, &fd));

        FindClose(hFind);
    }

    // TENTATIVO 2: Riprova ora che dovrebbe essere vuota
    if (RemoveDirectoryW(path.c_str())) return true;
    err = GetLastError();
    if (flagdebug3)
        myprintf("47917: deleteDir attempt2 (dopo svuotamento) err=%lu: %ls\n", err, i_dirpath.c_str());

    // TENTATIVO 3: Forza permessi di nuovo e riprova
    forceFilePermissions(path);
    SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_NORMAL);
    if (RemoveDirectoryW(path.c_str())) return true;
    err = GetLastError();
    if (flagdebug3)
        myprintf("47918: deleteDir attempt3 (force+retry) err=%lu: %ls\n", err, i_dirpath.c_str());

    // TENTATIVO 4: Schedula la cancellazione al prossimo riavvio
    if (MoveFileExW(path.c_str(), NULL, MOVEFILE_DELAY_UNTIL_REBOOT))
    {
        s_rebootScheduled++;
        color_magenta();
        myprintf("47919: *** RIAVVIO NECESSARIO *** cartella schedulata per cancellazione: %ls\n", i_dirpath.c_str());
        color_restore();
        return true;
    }

    if (flagdebug3)
        myprintf("47920: deleteDir TUTTI I TENTATIVI FALLITI err=%lu: %ls\n",
            GetLastError(), i_dirpath.c_str());

    return false;
}

// In deleteExcludedFiles, all'inizio:
bool enableAllPrivileges() {
    const LPCWSTR privileges[] = {
        SE_TAKE_OWNERSHIP_NAME,
        SE_RESTORE_NAME,
        SE_SECURITY_NAME,
        SE_BACKUP_NAME,
        SE_DEBUG_NAME  // New: to enumerate and close handles system-wide
    };
    bool allEnabled = true;
    for (auto priv : privileges) {
        if (!EnablePrivilege(priv)) {
            const DWORD errore= GetLastError(); /// before wtou()
            myprintf("Warning: Failed to enable %s (error %lu)\n", wtou(priv).c_str(), errore);
            allEnabled = false;
        }
    }
    return allEnabled;
}

// RESTORE: delete excluded files
bool franzimager::deleteExcludedFiles(
	const std::vector<std::string>& i_fileDaCancellare,
	char i_targetVolume)
{
	if (flagkill)
	{
		myprintf("47928: Skippo before -kill\n");
		return true;
	}
	if (flagdebug)
		myprintf("47827: >>> deleteExcludedFiles(count=%zu, target=%c)\n", 
			i_fileDaCancellare.size(), i_targetVolume ? i_targetVolume : '?');
	color_cyan();
	myprintf("47924: Enabling privileges\n");
	color_restore();
	enableAllPrivileges();
	
	/*
	EnablePrivilege(SE_TAKE_OWNERSHIP_NAME);
	EnablePrivilege(SE_RESTORE_NAME);
	EnablePrivilege(SE_SECURITY_NAME);
	EnablePrivilege(SE_BACKUP_NAME); // Utile per bypassare alcuni check in lettura/scrittura
*/

	// initialize statistics
	m_excludedExpectedDeleted = (int64_t)i_fileDaCancellare.size();
	m_excludedCannotDelete = 0;
	s_rebootScheduled = 0;
	
	if (i_fileDaCancellare.empty())
	{
		myprintf("44250: No files to delete\n");
		return true;  // nothing to do = successo
	}
	
	int64_t deletedCount = 0;
	int64_t totalCount = m_excludedExpectedDeleted;
	int64_t startTime = mtime();
	int64_t lastProgressTime = startTime;
	
	myprintf("44251: Deleting %s excluded files/directories...\n", migliaia(totalCount));
	
	for (size_t i = 0; i < i_fileDaCancellare.size(); i++)
	{
		std::string path = i_fileDaCancellare[i];
		
		// remap volume if requested
		if (i_targetVolume != 0 && path.length() >= 1)
		{
			path[0] = i_targetVolume;
		}
		
		///path=toLongPath(path);
		if (flagdebug3)
			myprintf("47912: Try to delete |%s|\n",path.c_str());
		
		// convert to wide with long path prefix
		std::wstring wpath = pathToLongWide(path);
		
		// verifica se è file o directory
		DWORD attrs = GetFileAttributesW(wpath.c_str());
		
		bool success = false;
///		bool isdir = false;
		
		if (attrs == INVALID_FILE_ATTRIBUTES)
		{
			// does not exist, consider success
			success = true;
		}
		else if (attrs & FILE_ATTRIBUTE_DIRECTORY)
		{
			///isdir = true;
			success = deleteDirectoryAggressive(wpath);
		}
		else
		{
			success = deleteFileAggressive(wpath);
		}
		
		if (success)
		{
			deletedCount++;
		}
		else
		{
			m_excludedCannotDelete++;
			if (flagverbose)
			{
				myprintf("44252: Failed to delete: %s (error %lu)\n", 
					path.c_str(), GetLastError());
			}
		}
		
		// progress every second with ETA
		int64_t now = mtime();
		if (now - lastProgressTime >= 1000)
		{
			double elapsed = (now - startTime) / 1000.0;
			if (elapsed < 0.001) elapsed = 0.001;
			
			double pct = 100.0 * (i + 1) / totalCount;
			double itemspersec = (i + 1) / elapsed;
			
			int64_t remaining = totalCount - (i + 1);
			int etaseconds = 0;
			if (itemspersec > 0)
				etaseconds = (int)(remaining / itemspersec);
			
			int etahours = etaseconds / 3600;
			int etamins = (etaseconds % 3600) / 60;
			int etasecs = etaseconds % 60;
			if (etahours > 99) etahours = 99;
			
			myprintf("44253: Deleting: ETA %02d:%02d:%02d %10s/%s (%5.1f%%) OK:%10s FAIL:%10s\r",
				etahours, etamins, etasecs,
				migliaia(i + 1),
				migliaia2(totalCount),
				pct,
				migliaia3(deletedCount),
				migliaia4(m_excludedCannotDelete));
			
			lastProgressTime = now;
		}
	}
	
	// newline finale dopo progress
	myprintf("\n");
	
	int64_t elapsed = mtime() - startTime;
	double elapsedsec = elapsed / 1000.0;
	
	myprintf("44254: Deletion complete in %.1f seconds:\n", elapsedsec);
	myprintf("  Total items     : %21s\n", migliaia(totalCount));
	myprintf("  Deleted OK      : %21s\n", migliaia(deletedCount));
	myprintf("  Reboot pending  : %21s\n", migliaia(s_rebootScheduled));
	myprintf("  Failed          : %21s\n", migliaia(m_excludedCannotDelete));

	if (s_rebootScheduled > 0)
	{
		color_magenta();
		myprintf("44257: =====================================================\n");
		myprintf("44257: *** RIAVVIO DI WINDOWS NECESSARIO ***\n");
		myprintf("44257: %s elementi non erano cancellabili e sono stati\n", migliaia(s_rebootScheduled));
		myprintf("         schedulati per la rimozione automatica al prossimo\n");
		myprintf("         avvio di Windows (PendingFileRenameOperations).\n");
		myprintf("         IL RIPRISTINO NON E' COMPLETO FINO AL RIAVVIO!\n");
		myprintf("44257: =====================================================\n");
		color_restore();
	}

	if (m_excludedCannotDelete > 0)
	{
		color_yellow();
		myprintf("44255: Warning: %s items could not be deleted\n", migliaia(m_excludedCannotDelete));
		color_restore();
	}
	else if (s_rebootScheduled == 0)
	{
		color_green();
		myprintf("44256: All excluded files deleted successfully\n");
		color_restore();
	}

	if (flagdebug)
		myprintf("47672: <<< deleteExcludedFiles = %s\n", (m_excludedCannotDelete == 0) ? "true" : "false");

	return (m_excludedCannotDelete == 0);
}

// EXCLUDED CLUSTERS MANAGEMENT - SERIALIZATION AND ZEROING
// Getter: serialize m_excludedclusters to byte array
// Binary format: [uint32_t count][start1:uint64_t][end1:uint64_t][start2:uint64_t][end2:uint64_t]...
std::vector<uint8_t> franzimager::getExcludedClustersAsBytes() const
{
	std::vector<uint8_t> result;
	
	uint32_t count = (uint32_t)m_excludedclusters.size();
	
	// write count
	const uint8_t* countptr = (const uint8_t*)&count;
	result.insert(result.end(), countptr, countptr + sizeof(count));
	
	// write each range (start_cluster, end_cluster)
	for (size_t i = 0; i < m_excludedclusters.size(); i++)
	{
		const clusterrange& range = m_excludedclusters[i];
		
		const uint8_t* startptr = (const uint8_t*)&range.start_cluster;
		result.insert(result.end(), startptr, startptr + sizeof(range.start_cluster));
		
		const uint8_t* endptr = (const uint8_t*)&range.end_cluster;
		result.insert(result.end(), endptr, endptr + sizeof(range.end_cluster));
	}
	
	if (flagdebug)
		myprintf("44842: getExcludedClustersAsBytes: %u ranges -> %zu bytes\n", 
			count, result.size());
	
	return result;
}

// Setter: deserialize byte array to m_excludedclusters
bool franzimager::setExcludedClustersFromBytes(const std::vector<uint8_t>& i_data)
{
	m_excludedclusters.clear();
	
	if (i_data.empty())
	{
		myprintf("44496: setExcludedClustersFromBytes: empty data\n");
		return true; // empty = no excluded clusters
	}
	
	// verify minimum size for count
	if (i_data.size() < sizeof(uint32_t))
	{
		myprintf("44310: setExcludedClustersFromBytes: data too small for count\n");
		return false;
	}
	
	size_t offset = 0;
	
	// read count
	uint32_t count = 0;
	memcpy(&count, i_data.data() + offset, sizeof(count));
	offset += sizeof(count);
	
	// verify size for all ranges
	size_t expectedSize = sizeof(uint32_t) + count * (sizeof(uint64_t) * 2);
	if (i_data.size() < expectedSize)
	{
		myprintf("44311: setExcludedClustersFromBytes: data too small (expected %zu, got %zu)\n",
			expectedSize, i_data.size());
		return false;
	}
	
	// read each range
	for (uint32_t i = 0; i < count; i++)
	{
		clusterrange range;
		
		memcpy(&range.start_cluster, i_data.data() + offset, sizeof(range.start_cluster));
		offset += sizeof(range.start_cluster);
		
		memcpy(&range.end_cluster, i_data.data() + offset, sizeof(range.end_cluster));
		offset += sizeof(range.end_cluster);
		
		m_excludedclusters.push_back(range);
	}
	
	if (flagdebug)
		myprintf("45432: setExcludedClustersFromBytes: %zu bytes -> %u ranges\n", 
			i_data.size(), count);
	
	return true;
}

// Zero (fill with 0x03 for debug) all excluded clusters on target partition
bool franzimager::zeroExcludedClusters(char i_targetVolume)
{
	
	if (flagdebug)
		myprintf("44320: >>> zeroExcludedClusters(target=%c, ranges=%zu)\n", i_targetVolume, m_excludedclusters.size());
	
	if (m_excludedclusters.empty())
	{
		myprintf("44321: No excluded clusters to zero\n");
		return true;
	}
	
	// open volume for writing
	char volumePath[16];
	snprintf(volumePath, sizeof(volumePath), "\\\\.\\%c:", i_targetVolume);
	
	if (flagdebug)
		myprintf("44323: Opening volume path: %s\n", volumePath);
	
	HANDLE hVolume = CreateFileA(volumePath,
		GENERIC_READ | GENERIC_WRITE,
		FILE_SHARE_READ | FILE_SHARE_WRITE,
		NULL,
		OPEN_EXISTING,
		FILE_FLAG_NO_BUFFERING | FILE_FLAG_WRITE_THROUGH,
		NULL);
	
	if (hVolume == INVALID_HANDLE_VALUE)
	{
		myprintf("44322: ERROR: cannot open volume %c: for writing (error %lu)\n",
			i_targetVolume, GetLastError());
		return false;
	}
	
	// Try to lock the volume for exclusive access
	DWORD bytesReturned = 0;
	BOOL lockResult = DeviceIoControl(hVolume, FSCTL_LOCK_VOLUME, NULL, 0, NULL, 0, &bytesReturned, NULL);
	if (!lockResult)
	{
		DWORD lockError = GetLastError();
		if (flagverbose)
		myprintf("44332: WARNING: cannot lock volume %c: (error %lu) - trying to continue anyway\n",i_targetVolume, lockError);
		// Don't fail, try to continue - some operations might still work
	}
	else
	{
		if (flagdebug)
			myprintf("41322: Volume %c: locked successfully\n", i_targetVolume);
	}
	
	// Dismount the volume to allow raw writes
	BOOL dismountResult = DeviceIoControl(hVolume, FSCTL_DISMOUNT_VOLUME, NULL, 0, NULL, 0, &bytesReturned, NULL);
	if (!dismountResult)
	{
		DWORD dismountError = GetLastError();
		if (flagdebug)
			myprintf("43322: WARNING: cannot dismount volume %c: (error %lu)\n",
				i_targetVolume, dismountError);
	}
	else
	{
		if (flagdebug)
			myprintf("44221: Volume %c: dismounted for raw access\n", i_targetVolume);
	}
	
	// get cluster size from boot sector or use cached value
	uint32_t clusterSize = m_clustersize;
	if (clusterSize == 0)
	{
		// try to read from boot sector
		uint8_t bootSector[512];
		DWORD bytesRead = 0;
		
		LARGE_INTEGER pos;
		pos.QuadPart = 0;
		SetFilePointerEx(hVolume, pos, NULL, FILE_BEGIN);
		
		if (ReadFile(hVolume, bootSector, 512, &bytesRead, NULL) && bytesRead == 512)
		{
			// NTFS: sectors per cluster at offset 0x0D, bytes per sector at offset 0x0B
			uint16_t bytesPerSector = *(uint16_t*)(bootSector + 0x0B);
			uint8_t sectorsPerCluster = bootSector[0x0D];
			clusterSize = bytesPerSector * sectorsPerCluster;
			if (flagdebug)
				myprintf("44323: Read from boot sector: bytesPerSector=%u, sectorsPerCluster=%u\n",
					bytesPerSector, sectorsPerCluster);
		}
		else
		{
			if (flagdebug)
				myprintf("44321: Failed to read boot sector (error %lu)\n", GetLastError());
		}
		
		if (clusterSize == 0)
			clusterSize = 4096; // default
	}
	
	if (flagdebug)
		myprintf("44325: Using cluster size: %u bytes\n", clusterSize);
	
	// allocate buffer for one cluster (filled with 0x03 for debug)
	// NOTE: for production change 0x03 to 0x00
	const uint8_t FILL_BYTE = 0x00; // DEBUG: use 0x03, PRODUCTION: use 0x00
	
	uint8_t* zeroBuffer = (uint8_t*)franz_malloc(clusterSize);
	if (!zeroBuffer)
	{
		myprintf("44324: ERROR: cannot allocate buffer for cluster zeroing\n");
		CloseHandle(hVolume);
		return false;
	}
	memset(zeroBuffer, FILL_BYTE, clusterSize);
	
	// statistics
	int64_t totalClusters = 0;
	int64_t zeroedClusters = 0;
	int64_t failedClusters = 0;
	int64_t startTime = mtime();
	int64_t lastProgressTime = startTime;
	
	// calculate total clusters
	for (size_t i = 0; i < m_excludedclusters.size(); i++)
	{
		totalClusters += (m_excludedclusters[i].end_cluster - m_excludedclusters[i].start_cluster + 1);
	}
	
	if (flagverbose)
		myprintf("44325: Zeroing %s clusters in %s ranges (fill byte 0x%02X)...\n", migliaia(totalClusters), migliaia2(m_excludedclusters.size()), FILL_BYTE);
	
	int64_t processedClusters = 0;
	
	// Allocate a larger buffer for batch writes (e.g., 2MB or 512 clusters at 4KB)
	const uint32_t MAX_BATCH_SIZE = 2 * 1024 * 1024; // 2MB batch
	uint32_t maxClustersPerBatch = MAX_BATCH_SIZE / clusterSize;
	if (maxClustersPerBatch < 1) maxClustersPerBatch = 1;
	
	uint8_t* batchBuffer = (uint8_t*)franz_malloc(MAX_BATCH_SIZE);
	if (!batchBuffer)
	{
		myprintf("44324: WARNING: cannot allocate batch buffer, using single cluster mode\n");
		batchBuffer = zeroBuffer; // fallback to single cluster
		maxClustersPerBatch = 1;
	}
	else
	{
		memset(batchBuffer, FILL_BYTE, MAX_BATCH_SIZE);
	}
	
	if (flagdebug)
		myprintf("44325: Batch size: %u clusters (%u bytes)\n", maxClustersPerBatch, maxClustersPerBatch * clusterSize);
	
	// process each range
	for (size_t rangeIdx = 0; rangeIdx < m_excludedclusters.size(); rangeIdx++)
	{
		const clusterrange& range = m_excludedclusters[rangeIdx];
		uint64_t rangeSize = range.end_cluster - range.start_cluster + 1;
		uint64_t clustersDone = 0;
		
		while (clustersDone < rangeSize)
		{
			// Calculate how many clusters to write in this batch
			uint64_t remaining = rangeSize - clustersDone;
			uint32_t batchClusters = (remaining > maxClustersPerBatch) ? maxClustersPerBatch : (uint32_t)remaining;
			uint32_t batchBytes = batchClusters * clusterSize;
			
			uint64_t currentCluster = range.start_cluster + clustersDone;
			uint64_t offset = currentCluster * clusterSize;
			
			LARGE_INTEGER seekPos;
			seekPos.QuadPart = offset;
			
			bool success = true;
			
			if (!SetFilePointerEx(hVolume, seekPos, NULL, FILE_BEGIN))
			{
				success = false;
				if (failedClusters < 3)
					myprintf("44326: ERROR seeking to cluster %llu offset %llu (error %lu)\n",
						(unsigned long long)currentCluster, (unsigned long long)offset, GetLastError());
			}
			else
			{
				DWORD bytesWritten = 0;
				if (!WriteFile(hVolume, batchBuffer, batchBytes, &bytesWritten, NULL) ||
					bytesWritten != batchBytes)
				{
					success = false;
					if (failedClusters < 3)
						myprintf("44327: ERROR writing %u clusters at offset %llu (error %lu, wrote %lu/%u)\n",
							batchClusters, (unsigned long long)offset, 
							GetLastError(), bytesWritten, batchBytes);
				}
			}
			
			if (success)
			{
				zeroedClusters += batchClusters;
			}
			else
			{
				failedClusters += batchClusters;
			}
			
			processedClusters += batchClusters;
			clustersDone += batchClusters;
			
			// progress every second
			int64_t now = mtime();
			if (now - lastProgressTime >= 1000)
			{
				double elapsed = (now - startTime) / 1000.0;
				if (elapsed < 0.001) elapsed = 0.001;
				
				double pct = 100.0 * processedClusters / totalClusters;
				double bytesPerSec = (processedClusters * clusterSize) / elapsed;
				
				int64_t remainingClusters = totalClusters - processedClusters;
				int etaSec = (processedClusters > 0) ? (int)(remainingClusters * elapsed / processedClusters) : 0;
				int etaMin = etaSec / 60;
				if (etaMin>99)
					etaMin=99;
				etaSec = etaSec % 60;
				
				myprintf("44328: Zeroing: ETA %02d:%02d %12s/%s (%5.1f%%) FAIL:%12s @ %s/s\r",
					etaMin, etaSec,
					migliaia(processedClusters),
					migliaia2(totalClusters),
					pct,
				//	migliaia3(zeroedClusters),
					migliaia4(failedClusters),
					tohuman(bytesPerSec));
				
				lastProgressTime = now;
			}
		}
	}
	
	if (batchBuffer != zeroBuffer)
		franz_free(batchBuffer);
	franz_free(zeroBuffer);
	CloseHandle(hVolume);
	
	// final newline
	myprintf("\n");
	
	int64_t elapsed = mtime() - startTime;
	double elapsedSec = elapsed / 1000.0;
	
	myprintf("44329: Cluster zeroing complete in %.1f seconds\n", elapsedSec);
	if (flagverbose)
	{
		myprintf("  Total clusters  : %21s\n", migliaia(totalClusters));
		myprintf("  Zeroed OK       : %21s\n", migliaia(zeroedClusters));
		myprintf("  Failed          : %21s\n", migliaia(failedClusters));
		myprintf("  Fill byte       : 0x%02X %s\n", FILL_BYTE, (FILL_BYTE == 0x00) ? "(zero)" : "(debug marker)");
	}
	if (failedClusters > 0)
	{
		color_yellow();
		myprintf("44330: Warning: %s clusters could not be zeroed\n", migliaia(failedClusters));
		color_restore();
		return false;
	}
	else
	{
		color_green();
		myprintf("44331: All excluded clusters zeroed successfully\n");
		color_restore();
		return true;
	}
}



