class franzraw
{
  private:
	/* handle e stato */
	HANDLE m_hdisk;
	HANDLE m_hvolume_lock;

	/* informazioni sul target */
	DWORD	  m_disk_index;
	ULONGLONG m_start_offset;
	ULONGLONG m_total_size;
	ULONGLONG m_bytes_read;

	/* stato */
	uint32_t m_settore; /* bytes per sector (the reads that fail: sector by sector) */
	bool m_is_open;
	bool m_is_partition; /* true = partizione, false = disco fisico */
	bool m_use_vss;		 /* true = usa VSS snapshot */
	char m_drive_letter; /* valido solo se is_partition */

	/* puntatore a franzVSS (se usato) */
	franzVSS *m_vss;

	
	/* ottiene dimensione disco fisico */
	bool get_disk_size(HANDLE hdisk)
	{
		DWORD bytes_ret;

		/* metodo 1: GET_LENGTH_INFORMATION */
		GET_LENGTH_INFORMATION length_info;
		if (DeviceIoControl(hdisk, IOCTL_DISK_GET_LENGTH_INFO,
							NULL, 0, &length_info, sizeof(length_info),
							&bytes_ret, NULL))
		{
			m_total_size= length_info.Length.QuadPart;
			return true;
		}

		/* metodo 2: DISK_GEOMETRY_EX */
		DISK_GEOMETRY_EX geom;
		if (DeviceIoControl(hdisk, IOCTL_DISK_GET_DRIVE_GEOMETRY_EX,
							NULL, 0, &geom, sizeof(geom), &bytes_ret, NULL))
		{
			m_total_size= geom.DiskSize.QuadPart;
			return true;
		}

		/* metodo 3: seek alla fine */
		LARGE_INTEGER pos, new_pos;
		pos.QuadPart= 0;
		if (SetFilePointerEx(hdisk, pos, &new_pos, FILE_END))
		{
			m_total_size= new_pos.QuadPart;
			pos.QuadPart= 0;
			SetFilePointerEx(hdisk, pos, NULL, FILE_BEGIN);
			return true;
		}

		myprintf("42093! cannot get disk size\n");
		return false;
	}

	/* blocca volume */
	bool lock_volume(char drive_letter)
	{
		DWORD bytes_ret;
		char  volume_path[16];
		snprintf(volume_path, sizeof(volume_path),"\\\\.\\%c:", drive_letter);

		m_hvolume_lock= CreateFileA(volume_path, GENERIC_READ | GENERIC_WRITE,
									FILE_SHARE_READ | FILE_SHARE_WRITE,
									NULL, OPEN_EXISTING, 0, NULL);
		if (m_hvolume_lock == INVALID_HANDLE_VALUE)
		{
			myprintf("32108! cannot open for lock (no administrator? volume in use?)\n");
			return false;
		}

		if (!DeviceIoControl(m_hvolume_lock, FSCTL_LOCK_VOLUME,
							 NULL, 0, NULL, 0, &bytes_ret, NULL))
		{
			myprintf("42114$ cannot lock volume (err: %lu)\n", GetLastError());
		}
		else
		{
			if (flagverbose)
			{
				color_green();
				myprintf("42117: Volume locked (this is good)\n");
				color_restore();
			}
		}

		if (!DeviceIoControl(m_hvolume_lock, FSCTL_DISMOUNT_VOLUME,
							 NULL, 0, NULL, 0, &bytes_ret, NULL))
		{
			myprintf("42133$ dismount impossible! (err: %lu)\n", GetLastError());
		}
		else
		{
			if (flagverbose)
			{
				color_green();
				myprintf("32124: Volume dismounted (this is very good)\n");
				color_restore();
			}
		}

		return true;
	}

	/* unlocks the volume */
	void unlock_volume()
	{
		if (m_hvolume_lock != INVALID_HANDLE_VALUE)
		{
			DWORD bytes_ret;
			DeviceIoControl(m_hvolume_lock, FSCTL_UNLOCK_VOLUME,
							NULL, 0, NULL, 0, &bytes_ret, NULL);
			CloseHandle(m_hvolume_lock);
			m_hvolume_lock= INVALID_HANDLE_VALUE;
			color_green();
			myprintf("42144: volume unlocked\n");
			color_restore();
		}
	}

	/* apre tramite VSS */
	bool open_vss(char drive_letter)
	{
		/* crea oggetto franzVSS */
		m_vss= new franzVSS();
		if (!m_vss)
		{
			myprintf("47778$: franzVSS kaputt\n");
			return false;
		}

		/* crea snapshot */
		if (flagverbose)
		{
			color_cyan();
			myprintf("47783: Creating VSS snapshot for %c:...\n", drive_letter);
			color_restore();
		}
		if (!m_vss->create(drive_letter))
		{
			myprintf("47778! snapshot VSS creation failed\n");
			delete m_vss;
			m_vss= NULL;
			return false;
		}
		if (flagverbose)
			myprintf("47774: snapshot VSS: %s\n", m_vss->getPath());

		/* opens the VSS device */
		m_hdisk= m_vss->openVSSDevice();
		if (m_hdisk == INVALID_HANDLE_VALUE)
		{
			myprintf("47800!: device VSS kaputt\n");
			delete m_vss;
			m_vss= NULL;
			return false;
		}

		/* waits for VSS to be ready */
		if (!m_vss->waitForVSSReadyRobust(m_hdisk, 5, 200))
		{
			myprintf("47809! VSS not ready after challenge\n");
			CloseHandle(m_hdisk);
			m_hdisk= INVALID_HANDLE_VALUE;
			delete m_vss;
			m_vss= NULL;
			return false;
		}

		/* riposiziona all'inizio */
		m_vss->reset_file_pointer_to_zero(m_hdisk);

		return true;
	}

	/* chiude VSS */
	void close_vss()
	{
		if (m_vss)
		{
			/* il distruttore di franzVSS elimina lo snapshot */
			delete m_vss;
			m_vss= NULL;
		}
	}

  public:
	/* constructor */
	franzraw()
	{
		m_hdisk		  = INVALID_HANDLE_VALUE;
		m_hvolume_lock= INVALID_HANDLE_VALUE;
		m_disk_index  = 0;
		m_start_offset= 0;
		m_total_size  = 0;
		m_bytes_read  = 0;
		m_settore	  = 512;
		m_is_open	  = false;
		m_is_partition= false;
		m_use_vss	  = false;
		m_drive_letter= 0;
		m_vss		  = NULL;
	}

	/* destructor */
	~franzraw()
	{
		chiudiraw();
	}

bool get_partition_info(char drive_letter)
	{
		char   volume_path[16];
		HANDLE hvol;
		DWORD  bytes_ret;

		snprintf(volume_path, sizeof(volume_path),"\\\\.\\%c:", drive_letter);

		hvol= CreateFileA(volume_path, 0,
						  FILE_SHARE_READ | FILE_SHARE_WRITE,
						  NULL, OPEN_EXISTING, 0, NULL);
		if (hvol == INVALID_HANDLE_VALUE)
		{
			myprintf("32061!: volume open %s kaputt (err: %lu)\n",volume_path, GetLastError());
			return false;
		}

		/* numero disco fisico */
		STORAGE_DEVICE_NUMBER sdn;
		if (!DeviceIoControl(hvol, IOCTL_STORAGE_GET_DEVICE_NUMBER,
							 NULL, 0, &sdn, sizeof(sdn), &bytes_ret, NULL))
		{
			myprintf("32123: IOCTL_STORAGE_GET_DEVICE_NUMBER failed (err: %lu)\n",GetLastError());
			CloseHandle(hvol);
			return false;
		}
		m_disk_index= sdn.DeviceNumber;

		/* offset e dimensione partizione */
		BYTE				 ext_buffer[sizeof(VOLUME_DISK_EXTENTS) + sizeof(DISK_EXTENT) * 16];
		VOLUME_DISK_EXTENTS *extents= (VOLUME_DISK_EXTENTS *)ext_buffer;

		if (!DeviceIoControl(hvol, IOCTL_VOLUME_GET_VOLUME_DISK_EXTENTS,
							 NULL, 0, extents, sizeof(ext_buffer), &bytes_ret, NULL))
		{
			myprintf("42038: IOCTL_VOLUME_GET_VOLUME_DISK_EXTENTS kaputt (err: %lu)\n",GetLastError());
			CloseHandle(hvol);
			return false;
		}

		if (extents->NumberOfDiskExtents == 0)
		{
			myprintf("42045: no extension founded\n");
			CloseHandle(hvol);
			return false;
		}

		m_start_offset= extents->Extents[0].StartingOffset.QuadPart;
		m_total_size  = extents->Extents[0].ExtentLength.QuadPart;

		/* somma estensioni multiple */
		for (DWORD i= 1; i < extents->NumberOfDiskExtents; i++)
		{
			m_total_size+= extents->Extents[i].ExtentLength.QuadPart;
		}

		CloseHandle(hvol);
		return true;
	}


	/*
	 * apriraw - opens a partition (letter) or physical disk (number)
	 *
	 * i_letter: 'A'..'Z' or 'a'..'z' for partition
	 *            0..255 (come numero, non ascii) per disco fisico
	 * i_usevss:  true = use VSS snapshot (partitions only)
	 *            false = accesso diretto
	 *
	 * returns: true = success, false = error
	 */
	bool apriraw(int i_lettera, bool i_usavss= false)
	{
		char physical_path[64];

		/* chiudi se già aperto */
		if (m_is_open)
		{
			chiudiraw();
		}

		/* reset stato */
		m_bytes_read  = 0;
		m_start_offset= 0;
		m_total_size  = 0;
		m_use_vss	  = false;

		/* determina se è una lettera o un numero */
		if ((i_lettera >= 'A' && i_lettera <= 'Z') ||
			(i_lettera >= 'a' && i_lettera <= 'z'))
		{
			m_is_partition= true;
			m_drive_letter= (char)i_lettera;

			/* normalizza a maiuscolo */
			if (m_drive_letter >= 'a' && m_drive_letter <= 'z')
			{
				m_drive_letter= m_drive_letter - 'a' + 'A';
			}
			if (!get_partition_info(m_drive_letter))
			{
				myprintf("48900: cannot get partition info\n");
				return false;
			}


			/* ottiene info partizione (serve sempre per m_total_size) */

			if (i_usavss)
			myprintf("42195: VSS raw            : %c (on drive %lu)\n", m_drive_letter, m_disk_index);
			else
			myprintf("42195: Raw partition mode : %c (on drive %lu)\n", m_drive_letter, m_disk_index);
			if (flagverbose)
			{
			myprintf("32312: partition offset   : %21s\n", migliaia(m_start_offset));
			myprintf("32323: partition size     : %21s (%s)\n", migliaia(m_total_size), tohuman(m_total_size));
			}

			if (i_usavss)
			{
				if (flagverbose)
					myprintf("47917: VSS mode on\n");
				
				if (!open_vss(m_drive_letter))
				{
					myprintf("47923! VSS failed, back to direct access\n");
					/* fallback ad accesso diretto */
					i_usavss= false;
				}
				else
				{
					m_use_vss= true;
					/* con VSS, l'offset è 0 (leggiamo dal device VSS) */
					m_start_offset= 0;
					m_is_open	  = true;
					color_cyan();
					myprintf("47933: VSS open done\n");
					color_restore();
					return true;
				}
			}

			/* locks the volume */
			lock_volume(m_drive_letter);

			/* costruisce path disco fisico */
			snprintf(physical_path, sizeof(physical_path),"\\\\.\\PhysicalDrive%lu", m_disk_index);
		}
		else
		{
			/*  modalità disco fisico */
			m_is_partition= false;
			m_disk_index  = (DWORD)i_lettera;
			m_start_offset= 0;

			/* VSS non supportato per dischi fisici */
			if (i_usavss)
			{
				myprintf("47955$ No VSS for physical drive, ignored\n");
			}

			myprintf("42193: disk mode          : %lu\n", m_disk_index);


			snprintf(physical_path,sizeof(physical_path),"\\\\.\\PhysicalDrive%lu", m_disk_index);
		}

		/* opens the physical disk */
		m_hdisk= CreateFileA(physical_path, GENERIC_READ,
							 FILE_SHARE_READ | FILE_SHARE_WRITE,
							 NULL, OPEN_EXISTING,
							 FILE_FLAG_NO_BUFFERING | FILE_FLAG_SEQUENTIAL_SCAN,
							 NULL);
		if (m_hdisk == INVALID_HANDLE_VALUE)
		{
			myprintf("42221! open kaputt %s (err: %lu)\n",
					 physical_path, GetLastError());
			unlock_volume();
			return false;
		}

		/* per disco fisico, ottiene la dimensione ora */
		if (!m_is_partition)
		{
			if (!get_disk_size(m_hdisk))
			{
				CloseHandle(m_hdisk);
				m_hdisk= INVALID_HANDLE_VALUE;
				return false;
			}
			if (flagverbose)
				myprintf("42224: disk size  %s (%s)\n", migliaia(m_total_size), tohuman(m_total_size));
		}

		/* posiziona all'offset (0 per disco fisico, offset per partizione) */
		if (m_start_offset > 0)
		{
			LARGE_INTEGER offset;
			offset.QuadPart= (LONGLONG)m_start_offset;
			if (!SetFilePointerEx(m_hdisk, offset, NULL, FILE_BEGIN))
			{
				myprintf("42242! seek to offset %s kaputt (err: %lu)\n",
						 migliaia(m_start_offset), GetLastError());
				CloseHandle(m_hdisk);
				m_hdisk= INVALID_HANDLE_VALUE;
				unlock_volume();
				return false;
			}
		}

		/* the sector: for the reads that fail, sector by sector */
		m_settore= 512;
		DISK_GEOMETRY_EX geometria;
		DWORD			 fatti= 0;
		if (DeviceIoControl(m_hdisk, IOCTL_DISK_GET_DRIVE_GEOMETRY_EX, NULL, 0, &geometria, sizeof(geometria), &fatti, NULL))
			if ((geometria.Geometry.BytesPerSector >= 512) && (geometria.Geometry.BytesPerSector <= 65536))
				m_settore= geometria.Geometry.BytesPerSector;
		m_is_open= true;
		if (flagverbose)
			myprintf("42223: raw opening done\n");
		return true;
	}


	int prendiraw(char *buffer, size_t dimensionebuffer)
	{
		if (!m_is_open || m_hdisk == INVALID_HANDLE_VALUE)
		{
			myprintf("42286! invalid handle or volume not open\n");
			return -2;
		}

		/* controlla se abbiamo finito */
		if (m_bytes_read >= m_total_size)
		{
			return 0;
		}

		/* calcola quanto leggere */
		ULONGLONG remaining= m_total_size - m_bytes_read;
		DWORD	  to_read  = (remaining > dimensionebuffer) ? (DWORD)dimensionebuffer : (DWORD)remaining;

		DWORD aligned_read= to_read;

		/* allinea a 512 byte solo per accesso diretto (non VSS) */
		if (!m_use_vss)
		{
			aligned_read= (to_read + 511) & ~511;
		}

		/* leggi: la posizione ogni volta (dopo un errore l'handle non la sa); quello che non si
		   legge resta zeri, contato (un READ ERROR gigante alla fine, exit code 2) */
		DWORD bytes_read= img_leggi(m_hdisk, m_start_offset + m_bytes_read, buffer, aligned_read, m_settore, (int64_t)m_bytes_read);

		if (bytes_read == 0)
		{
			return 0;
		}

		/* calcola bytes effettivi (non oltre la dimensione) */
		DWORD effective_bytes= bytes_read;
		if (m_bytes_read + effective_bytes > m_total_size)
		{
			effective_bytes= (DWORD)(m_total_size - m_bytes_read);
		}

		m_bytes_read+= effective_bytes;

		return (int)effective_bytes;
	}

	void chiudiraw()
	{
		if (m_hdisk != INVALID_HANDLE_VALUE)
		{
			CloseHandle(m_hdisk);
			m_hdisk= INVALID_HANDLE_VALUE;
		}

		/* chiude VSS se usato */
		if (m_use_vss)
		{
			close_vss();
			m_use_vss= false;
		}

		/* sblocca volume se partizione senza VSS */
		if (m_is_partition && !m_use_vss)
		{
			unlock_volume();
		}

		m_is_open= false;
		if (flagdebug)
			myprintf("42343: raw close done\n");
	}

	
	/* ritorna dimensione totale in bytes */
	ULONGLONG getsize() const
	{
		return m_total_size;
	}

	/* ritorna bytes già letti */
	ULONGLONG getbytesread() const
	{
		return m_bytes_read;
	}

	/* ritorna percentuale completamento */
	double getpercent() const
	{
		if (m_total_size == 0)
			return 0.0;
		return 100.0 * (double)m_bytes_read / (double)m_total_size;
	}

	/* returns true if open */
	bool isopen() const
	{
		return m_is_open;
	}

	/* returns true if using VSS */
	bool isusingvss() const
	{
		return m_use_vss;
	}

	/* ritorna indice disco fisico */
	DWORD getdiskindex() const
	{
		return m_disk_index;
	}

	/* ritorna offset partizione (0 per disco fisico o VSS) */
	ULONGLONG getstartoffset() const
	{
		return m_start_offset;
	}

	/* ritorna path VSS (vuoto se non usa VSS) */
	const char *getvsspath() const
	{
		if (m_vss)
			return m_vss->getPath();
		return "";
	}
};

