struct StringReader : public libzpaq::Reader
{
	const char *data;
	int			size;
	int			offset;
	StringReader(const char *d, int s) : data(d), size(s), offset(0)
	{
	}
	int get()
	{
		return (offset >= size) ? -1 : (unsigned char)data[offset++];
	}
	int read(char *buf, int len)
	{
		if (offset >= size)
			return 0;
		if (len > size - offset)
			len= size - offset;
		memcpy(buf, data + offset, len);
		offset+= len;
		return len;
	}
};

void *worker_routine(void *arg)
{
	ThreadContext *ctx		= (ThreadContext *)arg;
// Cast a (unsigned long) o (uintptr_t) prima di fare il modulo
	int thread_id = (int)((unsigned long)pthread_self() % 100);

	if (flagdebug2)
		myprintf("09121: Worker %d started", thread_id);

	while (true)
	{
		int block_idx= -1;

		pthread_mutex_lock(ctx->queue_mutex);

		while (ctx->job_queue.empty() && !ctx->shutdown)
			pthread_cond_wait(ctx->cond_new_job, ctx->queue_mutex);

		if (ctx->shutdown && ctx->job_queue.empty())
		{
			pthread_mutex_unlock(ctx->queue_mutex);
			if (flagdebug2)
				myprintf("09132: Worker %d: shutting down", thread_id);
			break;
		}
		block_idx= ctx->job_queue.front();
		ctx->job_queue.pop_front();
		pthread_mutex_unlock(ctx->queue_mutex);

		if (flagdebug2)
			myprintf("09140: Worker %d: got block %d", thread_id, block_idx);

		pthread_mutex_lock(ctx->cache_mutex);
		bool already_cached= (ctx->block_cache.find(block_idx) != ctx->block_cache.end());
		pthread_mutex_unlock(ctx->cache_mutex);

		if (already_cached)
		{
			if (flagdebug2)
				myprintf("09147: Worker %d: block %d already cached", thread_id, block_idx);
			continue;
		}

		if (flagdebug2)
			myprintf("09150: Worker %d: reading block %d", thread_id, block_idx);

		libzpaq::Decompresser d;
		StringBuffer		  out_sb;
		bool				  read_success= false;
		vector<char>		  raw_data;

		try
		{
			pthread_mutex_lock(ctx->io_mutex);
			Block &b= (*ctx->blocks)[block_idx];
			ctx->in->seek(b.offset, SEEK_SET);
			raw_data.resize(b.bsize);
			int bytes_read= ctx->in->read(&raw_data[0], b.bsize);
			pthread_mutex_unlock(ctx->io_mutex);

			if (bytes_read != b.bsize)
				throw std::runtime_error("09187: Incomplete read");

			StringReader ram_reader(&raw_data[0], raw_data.size());
			d.setInput(&ram_reader);
			double mem= 0;

			if (d.findBlock(&mem))
			{
				d.setOutput(&out_sb);
				while (d.findFilename())
				{
					d.readComment();
					d.decompress();
					d.readSegmentEnd();
				}
				read_success= true;
			}

			vector<char>().swap(raw_data);
			ctx->blocks_decompressed++;
			if (flagdebug3)
				myprintf("09185: Worker %d: decompressed block %d (%d bytes)", thread_id, block_idx, (int)out_sb.size());
		}
		catch (std::exception &e)
		{
			myprintf("09188! Worker %d: ERROR block %d: %s\n", thread_id, block_idx, e.what());
			read_success= false;
		}

		string *res= read_success ? new string(out_sb.c_str(), out_sb.size()) : new string("");

		pthread_mutex_lock(ctx->cache_mutex);

		bool is_priority= (block_idx == ctx->priority_block);

		int wait_count= 0;
		while (((int64_t(ctx->current_cache_size + res->size()) > g_GLOBAL_RAM_LIMIT) ||
				(ctx->current_cache_size > (g_GLOBAL_RAM_LIMIT * 0.8) && (!is_priority))) &&
			   !ctx->shutdown)
		{
			if (wait_count == 0)
			{
				if (flagdebug)
					myprintf("09212: Worker %d: WAITING for RAM (block %d, cache: %d MB)", thread_id, block_idx, (int)(ctx->current_cache_size / (1024 * 1024)));
				ctx->blocks_waiting_ram++;
			}
			wait_count++;

			if (wait_count > 50)
			{
				if (flagdebug3)
					myprintf("09218: Worker %d: FORCING block %d as priority after %d waits", thread_id, block_idx, wait_count);
				///is_priority= true;
				break;
			}

			pthread_cond_wait(ctx->cond_cache_not_full, ctx->cache_mutex);
			is_priority= (block_idx == ctx->priority_block);
		}
		if (wait_count > 0)
			ctx->blocks_waiting_ram--;

		if (ctx->block_cache.find(block_idx) == ctx->block_cache.end())
		{
			ctx->block_cache[block_idx]		 = res;
			ctx->block_access_time[block_idx]= ctx->access_counter++;
			ctx->current_cache_size+= res->size();
			if (flagdebug3)
				myprintf("09225: Worker %d: cached block %d (total: %d blocks, %d MB)", thread_id, block_idx, (int)ctx->block_cache.size(), (int)(ctx->current_cache_size / (1024 * 1024)));
		}
		else
		{
			delete res;
		}

		pthread_cond_broadcast(ctx->cond_block_ready);
		pthread_mutex_unlock(ctx->cache_mutex);
	}
	return 0;
}

