// Create or update an existing archive or part. If filename is ""
// then keep track of position in off but do not write to disk. Otherwise
// open and encrypt with password if not 0. If the file exists then
// read the salt from the first 32 bytes and off_ must be 0. Otherwise
// encrypt assuming off_ previous bytes, of which the first 32 are salt_.
// If off_ is 0 then write salt_ to the first 32 bytes.
OutputArchive::OutputArchive(string i_thearchive, const char *filename, const char *password,
							 const char *salt_, int64_t off_) :  ptr(0)
{
	assert(filename);
	buf = (char*)franz_malloc(BUFSIZE); 
    
    // Basic allocation error handling
    if (buf == NULL) 
	{
        error("Cannot malloc in outputarchive\n");
		seppuku();
	}
	off		   = off_;
	thefilename= "";
	flagindex  = false;
	nowrite	   = false;
	nowriteeof = 0;
	streamout  = false;
	/// g_p_franzenfile=0;

	if (!*filename)
		return;

	thefilename		  = filename;
	chunknumber		  = 0;
	writtensofar	  = 0;
	writtenonlastchunk= 0;
	firstchunk		  = true;
	previoussize	  = 0;
	if (g_chunk_size > 0)
	{
		firstfilename= i_thearchive;
		easymultipart chunkedoutput(i_thearchive);
		if (chunkedoutput.filenamearray.size() == 0)
			firstchunk= true;
		else
			firstchunk= false;

		if (flagdebug4)
		{
			myprintf("00280: is firstchunk %d\n", (int)firstchunk);
			myprintf("00281: chunkedoutput count %s total size %21s\n", migliaia(chunkedoutput.filenamearray.size()), migliaia2(chunkedoutput.totalchunksize));
			myprintf("00282: last %s next %s\n", chunkedoutput.lastpart.c_str(), chunkedoutput.nextpart.c_str());
		}
		if (chunkedoutput.nextpart_integer > chunkedoutput.maxpart)
		{
			myprintf("00283: proposed next_partinteger %s is > maxpart %s\n", migliaia(chunkedoutput.nextpart_integer), migliaia2(chunkedoutput.maxpart));
			seppuku();
			return;
		}
		chunknumber= chunkedoutput.nextpart_integer;
		thefilename= chunkedoutput.nextpart;
		if (flagdebug)
			myprintf("00284: changed thefilename to %s\n", thefilename.c_str());

		previoussize= chunkedoutput.totalchunksize;
		if (flagdebug4)
			myprintf("00285: previoussize %s\n", migliaia(previoussize));
	}

	/// a -append, first pass: it only counts. Nothing is opened, nothing is created
	if (g_fakewrite)
		return;

	// Open existing file
	char salt[32]= {0};
	/// a -append -stdout: the output is stdout. The archive on the command line is NEVER opened
	/// for writing: an existing one already has its salt (the new data are a delta to be glued
	/// after it, encrypted with the same salt), a new one starts with it, as always
	if (g_appendstdout)
	{
		streamout= true;
#ifdef _WIN32
		fp= GetStdHandle(STD_OUTPUT_HANDLE);
#else
		fp= stdout;
#endif
		firstfp	 = FPNULL;
		chunksize= 0;
		if (password)
		{
			if (!salt_)
				error("38722: salt not specified");
			memcpy(salt, salt_, 32);
			if (!exists(thefilename))
			{
				if (myfwrite(salt, 1, 32, fp) != 32)
					error("cannot write the salt on stdout");
				writtensofar= 32;
				off			= 32;
			}
			char key[32];
			libzpaq::stretchKey(key, password, salt);
			aes= new libzpaq::AES_CTR(key, 32, salt);
			g_allocatedram+= sizeof(libzpaq::AES_CTR);
		}
		return;
	}
	bool franzenistheoutput= false;
#ifndef NOFRANZEN
#ifdef ZPAQFULL /// NOSFTPSTART
	// the archive itself is the .franzen: it must NEVER be opened as a cleartext .zpaq
	franzenistheoutput= (g_franzen != "") && isfranzen(thefilename);
#endif /// NOSFTPEND
#endif
	if (franzenistheoutput)
		fp= FPNULL;
	else
	{
#ifdef BSD
	if (flagappend)
	{
		if (flagdebug2)
			myprintf("00286: try BSD ABPLUS\n");
		fp= myfopen(thefilename.c_str(), ABPLUS);
	}
	else
		fp= myfopen(thefilename.c_str(), RBPLUS);
#else
	fp= myfopen(thefilename.c_str(), RBPLUS);
#endif // corresponds to #ifdef (#ifdef BSD)
	}

	if (flagdebug3)
		myprintf("00287: ***********************************************************\n");
	if (g_chunk_size > 0)
	{
		/// g_addedchunklist_fp.push_back(fp);
		g_addedchunklist.push_back(thefilename);
	}

	if (isopen())
	{
		if (flagdebug3)
		{
			printbar('1');
			myprintf("00288: off inside isopen is %s\n", migliaia(off));
		}
		if (off != 0)
		{
			if (flagdebug)
			{
				myprintf("00289: thefilename is %s  %s\n", thefilename.c_str(), migliaia(off));
				if (fileexists(thefilename))
					myprintf("00290: does exists\n");
				else
					myprintf("00291: does not exists\n");
			}
			error("38583$ file exists and off > 0 (maybe try to add to chunked?)");
		}
		if (password)
		{
			if (flagdebug2)
				myprintf("00292: password, reading salt\n");
			if (fread(salt, 1, 32, fp) != 32)
				error("38679: cannot read salt");
			if (salt_ && memcmp(salt, salt_, 32))
				error("salt mismatch");
			else
			{
				if (flagdebug2)
					myprintf("00293: salt done!\n");
			}
		}

		seek(0, SEEK_END);
#ifndef NOFRANZEN
#ifdef ZPAQFULL /// NOSFTPSTART
		if (g_franzen != "")
		{
			if (g_p_franzenfile)
			{
				myprintf("44386! franzenfile already setted (should not)!\n");
			}
			else
			{
				string franzenfilename= franzenname(thefilename);
				g_p_franzenfile = new franzcri(g_franzen.c_str(), g_franzen.length());
				if (g_p_franzenfile->open(franzenfilename.c_str(), false))
				{
					color_cyan();
					printbar('*');
					if (g_p_franzenfile->get_is_aes_too())
						myprintf("43783: Appending AES+Franzen (FRENZEN) <<%Z>>\n", franzenfilename.c_str());
					else
						myprintf("43787: Appending Franzen (FRANZEN) <<%Z>>\n", franzenfilename.c_str());
					printbar('*');
					color_restore();
				}
				else
				{
					/// stop here: going on would update the .zpaq and leave the .franzen behind (libsodium missing, permissions...)
					myprintf("43791!  cannot open franzen <<%Z>>\n", franzenfilename.c_str());
					error("cannot open franzen archive for append");
				}
			}
		}
#endif /// NOSFTPEND
#endif
	}
	// Create new file
	else
	{
		if (flagdebug3)
			myprintf("00295: not isopen\n");
#ifndef NOFRANZEN
#ifdef ZPAQFULL /// NOSFTPSTART
		nowrite= g_franzen_zpaq_nowrite; // -franzen without -debug (with or without -key): the .zpaq is never opened
#endif /// NOSFTPEND
#endif
		if (nowrite)
		{
			if (flagverbose)
			{
				color_cyan();
				myprintf("43784: Franzen-only: cleartext <<%Z>> will NOT be written\n", thefilename.c_str());
				color_restore();
			}
		}
		else
		{
#ifdef BSD
			if (flagappend)
			{
				if (flagdebug2)
					myprintf("00296: try BSD flagappend\n");
				fp= myfopen(thefilename.c_str(), AB);
			}
			else
				fp= myfopen(thefilename.c_str(), WB);
#else
			fp= myfopen(thefilename.c_str(), WB, DATE_1980);
#endif // corresponds to #ifdef (#ifdef BSD)
			if (!isopen())
				ioerr(thefilename.c_str());
		}

		if (g_chunk_size > 0)
		{
			/// g_addedchunklist_fp.push_back(fp);
			g_addedchunklist.push_back(thefilename);
		}
#ifndef NOFRANZEN
#ifdef ZPAQFULL /// NOSFTPSTART
		if (g_franzen != "")
		{
			if (g_p_franzenfile)
			{
				myprintf("442581 franzenfile already setted!\n");
			}
			else
			{
				string franzenfilename= franzenname(thefilename);
				bool has_aes = (g_password != NULL && g_password[0] != 0);
				if (nowrite && is_file_franzen(franzenfilename))
				{
					// franzen-only incremental append: the archive lives only in the .zpaq.franzen
					nowriteeof= g_header_pos; // logical (decoded) size of the existing archive
					g_p_franzenfile= new franzcri(g_franzen.c_str(), g_franzen.length());
					if (g_p_franzenfile->open(franzenfilename.c_str(), false))
					{
						if (g_p_franzenfile->get_is_aes_too() != has_aes)
						{
							if (has_aes)
								myprintf("43796! <<%Z>> is Franzen-only (no AES): -key cannot be used\n", franzenfilename.c_str());
							else
								myprintf("43793! <<%Z>> is AES+Franzen: -key is needed\n", franzenfilename.c_str());
							error("franzen-only append: AES mismatch between archive and options");
						}
						color_cyan();
						printbar('*');
						if (has_aes)
							myprintf("43792: Appending AES+Franzen (FRENZEN) <<%Z>>\n", franzenfilename.c_str());
						else
							myprintf("43794: Appending Franzen (FRANZEN) <<%Z>>\n", franzenfilename.c_str());
						printbar('*');
						color_restore();
					}
					else
					{
						myprintf("43795! cannot open franzen <<%Z>>\n", franzenfilename.c_str());
						error("cannot open franzen archive for append");
					}
				}
				else
				{
					g_p_franzenfile = new franzcri(g_franzen.c_str(), g_franzen.length(), 0, 0, 0, CRYPTO_PWHASH_ALG_DEFAULT, has_aes);
					if (g_p_franzenfile->open(franzenfilename.c_str(), true))
					{
						color_cyan();
						printbar('*');
						if (has_aes)
							myprintf("43783: Creating AES+Franzen (FRENZEN) <<%Z>>\n", franzenfilename.c_str());
						else
							myprintf("43787: Creating Franzen (FRANZEN) <<%Z>>\n", franzenfilename.c_str());
						printbar('*');
						color_restore();
					}
					else
					{
						/// stop here: with Franzen-only (nowrite) the data would go nowhere, and "all OK" at the end
						myprintf("43791!  cannot create franzen <<%Z>>\n", franzenfilename.c_str());
						error("cannot create franzen archive");
					}
				}
			}
		}
#endif /// NOSFTPEND
#endif
		if (password)
		{
/*
			if (g_p_franzenfile==NULL)
			{

				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				myprintf("******** FRANZENFILE NULL\n");
				seppuku();
				
			}
*/
			if (!salt_)
			{
				error("38722: salt not specified");
				seppuku();
				exit(0);
			}
			memcpy(salt, salt_, 32);
			if (nowrite && (nowriteeof > 0))
			{
				// franzen-only AES append: the salt is already at decoded [0..31], do not rewrite it
				if (flagdebug3)
					myprintf("00298: franzen-only append, salt not rewritten\n");
			}
			else
			{
				if (off == 0 && myfwrite(salt, 1, 32, fp) != 32)
					ioerr(thefilename.c_str());
				if (nowrite)
				{
					off		  = 32; // virtual position just after the salt
					nowriteeof= 32;
				}
				if (flagdebug3)
					myprintf("00297: written SALT (32bytes) on %s\n", thefilename.c_str());
#ifndef _WIN32
				fflush(fp); /// unix fix
#endif					// corresponds to #ifndef (#ifndef _WIN32)
			}
		}
	}
	if (flagdebug)
		myprintf("00299: opened 1 thefilename %s\n", thefilename.c_str());
	firstfp	 = FPNULL;
	chunksize= 0;

	if (g_chunk_size > 0)
	{
		firstfp			 = fp;
		g_archivefp_first= firstfp;
#ifndef ESX
		if (flagdebug3)
			myprintf("00300: ))))))))))))))))))))  Take note: firstfp is %s\n", migliaia(int64_t(firstfp)));
#endif
	}

	if (thefilename != g_indexname)
	{
		g_fp_zpaq= fp;
		flagindex= false;
#ifndef ESX
		if (flagdebug3)
			myprintf("00301: ;;;;;;;;;;;;;;;;;;;;;;;;;; settato index %s %08lld;;;;;;;;;;;;;\n", migliaia(int64_t(g_fp_zpaq)), (long long)int64_t(g_fp_zpaq));
#endif
	}

	if (flagindex)
	{
#ifndef ESX
		if (flagdebug)
			myprintf("00302: OutputArchive ISINDEX %s %s\n", thefilename.c_str(), migliaia(int64_t(fp)));
#endif
	}
	else
	{
#ifndef ESX
		if (flagdebug)
			myprintf("00303: OutputArchive ZPAQ    %s %s\n", thefilename.c_str(), migliaia(int64_t(fp)));
#endif
	}

	// Set up encryption
	if (password)
	{
		char key[32];
		libzpaq::stretchKey(key, password, salt);
		aes= new libzpaq::AES_CTR(key, 32, salt);
		g_allocatedram+= sizeof(libzpaq::AES_CTR);
	}
}

#ifdef unix
std::string exec(const char *cmd)
{
#ifdef ANCIENT
	(void)cmd;
	return "";
#else
	///	"unfolded" for compiler "quiteness"
	char		buffer[128];
	std::string result;
	FILE	   *pipe= popen(cmd, "r");
	if (!pipe)
	{
		myprintf("00322! popen kaputt\n");
		return "";
	}
	while (fgets(buffer, sizeof(buffer), pipe) != NULL)
		result+= buffer;
	if (pclose(pipe) == -1)
	{
		myprintf("00323! pclose failed\n");
		return "";
	}
	return result;
#endif // corresponds to #ifdef (#ifdef ANCIENT)
}
#else
// a debug function
string exec(const char *cmd)
{
	myprintf("00324: Debug function (Windows does not have ZFS!)\n");
	if (cmd == NULL) // compiler be quiet
		return "NULL";
	return "";
}
#endif // corresponds to #ifdef (#ifdef unix)
#ifdef _WIN32
string tail(string const &i_source, size_t const i_length)
{
	if (i_length >= i_source.size())
		return i_source;
	return i_source.substr(i_source.size() - i_length);
}
#endif // corresponds to #ifdef (#ifdef _WIN32)

string x_one_vector(string i_command, string i_text, vector<string> &o_line)
{
	o_line.clear();
	if (i_command == "")
		return "";

	string risultato= exec(i_command.c_str());
	if (i_text != "")
		if (flagverbose)
			myprintf("00325: running        %s\n", i_text.c_str());
	if (risultato == "")
	{
		if (flagverbose)
			myprintf("00326: x_one          %s\n", i_command.c_str());
		return "";
	}
	if (flagdebug2)
		myprintf("00327: x_one          %s => %s\n", i_command.c_str(), risultato.c_str());

	unsigned int i		 = 0;
	string		 lineetta= "";

	while (i < risultato.size())
	{
		if ((risultato[i] == 10) || (risultato[i] == 13))
		{
			myreplaceall(lineetta, std::string(1, 10), "");
			myreplaceall(lineetta, std::string(1, 13), "");

			o_line.push_back(lineetta);
			if (flagdebug2)
				myprintf("00328: Pushato |%s|\n", lineetta.c_str());
			lineetta= "";
		}
		else
		{
			lineetta+= risultato[i];
		}
		i++;
	}

	return risultato;
}

