        scrivi_riga("-t N", "Use N threads (requires -ssd)");
        scrivi_riga(" ", " ");
        scrivi_riga("SUB test", "Verify decryption without writing output");
        scrivi_riga("SUB ispasswordok", "Verify if password is correct");
