bool Jidac::cli_getdate(string& i_opt,string i_string,int argc,const char** argv, int* i_i,int64_t* o_date)
{
	if ((argv==NULL) || (i_i==NULL) || (o_date==NULL))
	{
		myprintf("00530: GURU null data\n");
		seppuku();
		return false;
	}
	if (i_opt==i_string)
		if ((*i_i)+1<argc)
			if (strlen(argv[(*i_i)+1])>=1)
			{
				string mytimestamp=argv[(*i_i)+1];
				/// -touch can be used without a date: then the next argument
				/// is a switch (-touch -summary), do not swallow it
				if (mytimestamp[0]=='-')
					return false;
				(*i_i)++;
				///format_datetime

				int64_t newdate=encodestringdate(mytimestamp,true);
				if (newdate!=-1)
				{
					
					(*o_date)=newdate;
					
					if (!do_not_print_headers())
						if (flagdebug)
						{
							if (flagdebug3)
								myprintf("00531: franz:%s change from %s => %s\n",i_string.c_str(),dateToString(flagutc,*o_date).c_str(),dateToString(flagutc,newdate).c_str());
							myprintf("00532: franz:%-21s   <<%s>>\n",i_string.c_str(),dateToString(true,newdate).c_str());
						}
					i_opt="skipme";
					
				}
			}
	return false;
}

bool Jidac::cli_onlystring(const string& i_opt,string i_string,string i_alias,string& o_thefile,int argc,const char** argv, int* i_i,bool* i_theflag)
{
	if ((argv==NULL) || (i_i==NULL))
	{
		myprintf("00533: GURU null data\n");
		seppuku();
		return false;
	}
	if (i_alias=="")
		i_alias="@N3b12vc$fjvn4ba";

	if ((i_opt==i_string) || (i_opt==i_alias))
	{
		if (o_thefile=="")
		{
			if (++(*i_i)<argc && argv[(*i_i)][0]!='-')
			{
				o_thefile=argv[(*i_i)];
				if (!do_not_print_headers())
					if (flagdebug)
					{
						if ((mypos("password",i_string)!=-1) || (i_string=="-p"))
							myprintf("00538: franz:%-21s %s\n",i_string.c_str(),"(hidden)");
						else
							myprintf("00534: franz:%-21s <<%s>>\n",i_string.c_str(),o_thefile.c_str());
					}
				if (i_theflag!=NULL)
					(*i_theflag)=true;
			}
			else
				(*i_i)--;
		}

		if (i_string=="-keyfile")
		{
			if (o_thefile!="")
			{
				g_keyfilehash=keyfile_to_string(o_thefile);
				if (g_keyfilehash=="")
				{
					myprintf("49268: bad -keyfile!\n");
					seppuku();
				}
				g_keyfile=o_thefile;
			}
///			myprintf("********************************************** %s\n",g_keyfilehash.c_str());
			
		}
		return true;
	}
	return false;
}
#ifdef _WIN32

/*
// Expand Windows environment variables in a string
// Esempio: "%TEMP%\file.txt" -> "C:\Users\utente\AppData\Local\Temp\file.txt"
// Se non ci sono variabili, ritorna la stringa originale
// Supports multiple variables: "%USERPROFILE%\%USERNAME%\file.txt"

static std::string expandenvironmentvariables(const std::string& i_path)
{
    // Verifica veloce: se non contiene % non c'è nulla da espandere
    if (i_path.find('%') == std::string::npos)
        return i_path;
    
    // Convert to wide string for Windows APIs
    std::wstring wpath = utow(i_path.c_str());
    
    // First call to get the required length
    DWORD requiredSize = ExpandEnvironmentStringsW(wpath.c_str(), nullptr, 0);
    
    if (requiredSize == 0)
    {
        // Error: returns original string
        return i_path;
    }
    
    // Allocate buffer and expand
    std::vector<wchar_t> buffer(requiredSize);
    DWORD result = ExpandEnvironmentStringsW(wpath.c_str(), buffer.data(), requiredSize);
    
    if (result == 0 || result > requiredSize)
    {
        // Error: returns original string
        return i_path;
    }
    
    // Convert result to UTF-8
    std::string expanded = wtou(buffer.data());
    
    // Optional: normalize separators to /
    for (char& c : expanded)
    {
        if (c == '\\')
            c = '/';
    }
	
	printf("k1 |%s|\n",expanded.c_str());
	expanded+='/';
	printf("k2 |%s|\n",expanded.c_str());
	
    return expanded;
}

// Versione che ritorna wstring direttamente (evita doppia conversione)
static std::wstring expandenvironmentvariablesw(const std::wstring& i_wpath)
{
    // Verifica veloce: se non contiene % non c'è nulla da espandere
    if (i_wpath.find(L'%') == std::wstring::npos)
        return i_wpath;
    
    // First call to get the required length
    DWORD requiredSize = ExpandEnvironmentStringsW(i_wpath.c_str(), nullptr, 0);
    
    if (requiredSize == 0)
        return i_wpath;
    
    // Allocate buffer and expand
    std::vector<wchar_t> buffer(requiredSize);
    DWORD result = ExpandEnvironmentStringsW(i_wpath.c_str(), buffer.data(), requiredSize);
    
    if (result == 0 || result > requiredSize)
        return i_wpath;
    
    return std::wstring(buffer.data());
}
*/
#endif
bool readfiletoarray(string i_filename, vector<string>& o_lines)
{
    o_lines.clear();
    
    if (!fileexists(i_filename))
    {
        myprintf("00535! cannot find %Z\n", i_filename.c_str());
        return false;
    }

    FILE* myfile = freadopen(i_filename.c_str());
    if (myfile == NULL)
    {
        myprintf("00537: cannot open file %Z\n", i_filename.c_str());
        return false;
    }

#ifdef ESX
    const size_t LINE_BUFSIZE = 16384;
	char line[LINE_BUFSIZE];
#else
#ifdef ANCIENT
    const size_t LINE_BUFSIZE = 16384;
#else
    const size_t LINE_BUFSIZE = 65536;
#endif

    std::vector<char> buffer_mem(LINE_BUFSIZE);
    
    char* line = buffer_mem.data();
#endif

#ifndef ESX /// on ESX line is an array on the stack: it cannot be NULL (-Waddress)
    // Safety check (per placare compilatori molto pedanti)
    if (line == NULL)
	{
        fclose(myfile);
        return false;
    }
#endif // corresponds to #ifndef (#ifndef ESX)

    string linea;
    while (fgets(line, static_cast<int>(LINE_BUFSIZE), myfile))
    {
        linea = line;
        if (flagdebug3)
            myprintf("00539: line %s\n", linea.c_str());
            
        // Remove Line Feed (LF) and Carriage Return (CR)
        myreplaceall(linea, std::string(1, 10), "");
        myreplaceall(linea, std::string(1, 13), "");
        
        o_lines.push_back(linea);
    }

    fclose(myfile);
    return true;
}

bool isbigendian(void)
{
    union
	{
		uint32_t i;
		char c[4];
    } bint = {0x01020304};
    return bint.c[0] == 1;
}


void replacetabs(std::string &str) 
{
    std::string::size_type pos = 0;
    while ((pos=str.find("\\t", pos))!=std::string::npos) 
        str.replace(pos++,2,"\t");
}

