#if defined(ZPAQMOUNT) && defined(ZPAQFULL) ///NOSFTPSTART
/*
	autotest, mount tests: does the mount work HERE, for THIS user? Asking
	whether FUSE or WinFsp are installed is not enough (a Linux without
	/dev/fuse in a container, an OpenBSD where only root can mount, a macOS
	with macFUSE not yet allowed...). So the real thing is tried: this very
	executable, "mount <small archive> <mountpoint> -test", in a process of
	its own, with a time limit. Exit code of the child, -1 if it could not
	be started or did not finish in time
*/
int autotest_spawn(const string& i_exe, const vector<string>& i_args, int i_timeout)
{
#ifdef _WIN32
	std::wstring riga= L"\"" + utow(i_exe.c_str()) + L"\"";
	for (size_t i= 0; i < i_args.size(); i++)
		riga+= L" \"" + utow(i_args[i].c_str()) + L"\"";
	SECURITY_ATTRIBUTES sa;
	ZeroMemory(&sa, sizeof(sa));
	sa.nLength		 = sizeof(sa);
	sa.bInheritHandle= TRUE;
	HANDLE nulla	 = CreateFileW(L"NUL", GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, &sa, OPEN_EXISTING, 0, NULL);
	STARTUPINFOW		si;
	PROCESS_INFORMATION pi;
	ZeroMemory(&si, sizeof(si));
	ZeroMemory(&pi, sizeof(pi));
	si.cb		  = sizeof(si);
	si.dwFlags	  = STARTF_USESTDHANDLES;
	si.hStdInput  = GetStdHandle(STD_INPUT_HANDLE);
	si.hStdOutput = nulla;
	si.hStdError  = nulla;
	std::vector<wchar_t> comando(riga.begin(), riga.end());
	comando.push_back(0);
	const BOOL partito= CreateProcessW(NULL, &comando[0], NULL, NULL, TRUE, 0, NULL, NULL, &si, &pi);
	if (nulla != INVALID_HANDLE_VALUE)
		CloseHandle(nulla);
	if (!partito)
		return -1;
	int risultato= -1;
	if (WaitForSingleObject(pi.hProcess, (DWORD)i_timeout * 1000) == WAIT_OBJECT_0)
	{
		DWORD codice= 1;
		if (GetExitCodeProcess(pi.hProcess, &codice))
			risultato= (int)codice;
	}
	/// too slow: left alone. Killing a process in the middle of a read of
	/// its own WinFsp volume leaves it stuck in the kernel, mount included
	CloseHandle(pi.hProcess);
	CloseHandle(pi.hThread);
	return risultato;
#else
	vector<char*> argomenti;
	argomenti.push_back((char*)i_exe.c_str());
	for (size_t i= 0; i < i_args.size(); i++)
		argomenti.push_back((char*)i_args[i].c_str());
	argomenti.push_back(NULL);
	const pid_t figlio= fork();
	if (figlio < 0)
		return -1;
	if (figlio == 0)
	{
		const int nullo= open("/dev/null", O_WRONLY);
		if (nullo >= 0)
		{
			dup2(nullo, 1);
			dup2(nullo, 2);
			if (nullo > 2)
				close(nullo);
		}
		execv(i_exe.c_str(), &argomenti[0]);
		_exit(127);
	}
	int stato= 0;
	for (int i= 0; i < i_timeout * 10; i++)
	{
		const pid_t fatto= waitpid(figlio, &stato, WNOHANG);
		if (fatto == figlio)
			return WIFEXITED(stato) ? WEXITSTATUS(stato) : -1;
		if (fatto < 0 && errno != EINTR)
			return -1;
		usleep(100 * 1000);
	}
	/// too slow: SIGTERM, the mount unmounts on it (see mount_signals_to_default)
	kill(figlio, SIGTERM);
	for (int i= 0; i < 100; i++)
	{
		if (waitpid(figlio, &stato, WNOHANG) == figlio)
			return -1;
		usleep(100 * 1000);
	}
	kill(figlio, SIGKILL);
	waitpid(figlio, &stato, 0);
	return -1;
#endif // corresponds to #ifdef (#ifdef _WIN32)
}
#endif // corresponds to #if (#if defined(ZPAQMOUNT) && defined(ZPAQFULL)) ///NOSFTPEND

/*
	autotest -all -quick: the QUICK SUITE, exactly these four logical operations and nothing else
	(-quick keeps its general meaning everywhere else: here, and only with -all, it means this):
	1. extraction of sha256.zpaq (the very same way of the full suite: x, then sum -rename, that
	   checks the 256 files)
	2. the extracted data compressed with -m1
	3. the same data compressed with -m8
	4. t (test) of the archives made by 2 and 3
	The script (quicktest.sh/.bat) AND the final check (autotest -all -quick -checktxt) come from
	this table only: after its commands every operation writes its number in quickops.txt, and
	the check wants 1, 2, 3, 4 (in this order), every expected output, and nothing else (another
	number, a quickNN.txt not in the table, an outNN.txt of the full suite => the quick suite fails)
	In the commands %E is the executable, %D the test folder (with the final slash)
*/
struct autotest_quickop
{
	const char *comando[2];	  // up to two commands (NULL = none)
	const char *uscita[2];	  // the -out file of each command to check (NULL = none)
	const char *atteso[2];	  // what that -out file must contain
	const char *descrizione;
};
static const autotest_quickop g_autotestquick[]= {
	{{"\"%E\" x \"%Dsha256.zpaq\" -space -to \"%Dte\"", "\"%E\" sum \"%Dte\" -sha256 -rename -force -out \"%Dquick1.txt\""},
	 {NULL, "quick1.txt"}, {NULL, "NOT renamed files  256"}, "Extracting sha256.zpaq"},
	{{"\"%E\" a \"%Dquick_m1.zpaq\" \"%Dte\" -m1 -noeta -out \"%Dquick2.txt\"", NULL},
	 {"quick2.txt", NULL}, {"(all OK)", NULL}, "-m1 compression of the extracted data"},
	{{"\"%E\" a \"%Dquick_m8.zpaq\" \"%Dte\" -m8 -noeta -out \"%Dquick3.txt\"", NULL},
	 {"quick3.txt", NULL}, {"(all OK)", NULL}, "-m8 compression of the same data"},
	{{"\"%E\" t \"%Dquick_m1.zpaq\" -noeta -out \"%Dquick4.txt\"", "\"%E\" t \"%Dquick_m8.zpaq\" -noeta -out \"%Dquick5.txt\""},
	 {"quick4.txt", "quick5.txt"}, {"(all OK)", "(all OK)"}, "t of the -m1 and -m8 archives"}};
static const unsigned int g_autotestquickn= sizeof(g_autotestquick) / sizeof(g_autotestquick[0]);

