/// funzioni di supporto per add WIN

void print_eta_image(const char *tag,
					 float		 percentuale,
					 int64_t	 total_done,
					 int64_t	 total_size,
					 int64_t	 g_fwritten,
					 int64_t	 startstream,
					 int		*ultimotempo_ref,
					 int64_t	*last_update_time_ptr)
{
	int64_t current_time= mtime();
	if (current_time - *last_update_time_ptr < 1000)
		return;

	int secondi= (current_time - startstream) / 1000;
	if (secondi == (*ultimotempo_ref))
		return;

	float			   speed	  = (secondi > 0) ? (float)total_done / (float)secondi : 0.0f;
	unsigned long long eta_seconds= 0;
	if (speed > 0)
	{
		unsigned long long bytes_remaining= total_size - total_done;
		eta_seconds						  = (unsigned long long)(bytes_remaining / speed);
	}

	int eta_hours= eta_seconds / 3600;
	if (eta_hours > 99)
		eta_hours= 99;
	int eta_minutes= (eta_seconds % 3600) / 60;
	int eta_secs   = eta_seconds % 60;

	int64_t projectedsize= (total_done > 0)
							   ? (int64_t)(((double)g_fwritten / total_done) * total_size)
							   : total_size;

	myprintf("75001: %s %05.2f%% %02d:%02d:%02d  %10s/%s =>+%10s (%10s) @ %10s/s \r",
			 tag,
			 percentuale,
			 eta_hours, eta_minutes, eta_secs,
			 tohuman(total_done),
			 tohuman2(total_size),
			 tohuman3(g_fwritten),
			 tohuman5(projectedsize),
			 tohuman4(int64_t(speed)));

	*ultimotempo_ref= secondi;
	fflush(stdout);
	*last_update_time_ptr= current_time;
}
