void Jidac::list_filesize(const bool i_isdir, const int64_t i_filesize, int i_thesizesize)
{
	/// <0 is "unknown" (a fragment without its size in the index, see read_archive()): ?, not a number
	const char *dimensione= (i_filesize < 0) ? "?" : migliaia(i_filesize);
	if (g_csvstring != "")
	{
		myprintf("%s", dimensione);
		return;
	}
	if (i_thesizesize == 0)
		i_thesizesize= 19;
	char lineatemp[200];
	if (i_isdir)
		snprintf(lineatemp, sizeof(lineatemp), "[%*s", i_thesizesize, dimensione);
	else
		snprintf(lineatemp, sizeof(lineatemp), " %*s", i_thesizesize, dimensione);

	list_out(lineatemp);
}
void Jidac::list_compressedfilesize(const int64_t i_compressedfilesize, const int64_t i_filesize, const bool i_flagnewversion, const bool i_isfolder, const bool i_isdeleted)
{
	if (i_flagnewversion)
	{
		color_blackongreen();
		if (g_csvstring != "")
			list_out("Ver");
		else
			list_out("  Ver");
		return;
	}
	if (i_isdeleted)
	{
		color_yellow();
		if (g_csvstring != "")
			list_out("del");
		else
			list_out("  del");
		color_restore();
		return;
	}
	if (i_isfolder)
	{
		color_green();
		if (g_csvstring != "")
			list_out("dir");
		else
			list_out("  dir");
		color_restore();
		return;
	}
	if ((i_filesize < 0) || (i_compressedfilesize < 0)) /// unknown size: no ratio at all
	{
		color_yellow();
		if (g_csvstring != "")
			list_out("?");
		else
			list_out("    ?");
		color_restore();
		return;
	}

	double ratio= 0;
	if (i_filesize != 0)
		ratio= 100.0 * (double)i_compressedfilesize / (double)i_filesize;
	char percento[64];
	if (ratio > 999)
	{
		color_red();
		list_out(">999%");
	}
	else if (ratio > 100.0)
	{
		color_yellow();
		snprintf(percento, sizeof(percento), (g_csvstring != "") ? "%.0f%%" : "%4.0f%%", (double)ratio);
		list_out(percento);
	}
	else
	{
		color_green();
		snprintf(percento, sizeof(percento), (g_csvstring != "") ? "%.0f%%" : "%4.0f%%", (double)ratio);
		list_out(percento);
	}
	/// myprintf("(%10s) ", tohuman(i_compressedfilesize));
	color_restore();
}


