int64_t Jidac::datacreazione(const string i_file)
{
	if (i_file == "")
		return 0;
#ifndef ANCIENT

#if defined(__APPLE__) && defined(__MACH__)
	struct stat file_stat;
	if (stat(i_file.c_str(), &file_stat) == -1)
	{
		myprintf("03329! stat KAPUTT (Mac)\n");
		return 0;
	}

	struct tm *t;
	if (file_stat.st_birthtimespec.tv_sec != 0)
	{
		t= localtime(&file_stat.st_birthtimespec.tv_sec);
		if (t == NULL)
			return 0;
		return (t->tm_year + 1900) * 10000000000LL + (t->tm_mon + 1) * 100000000LL + t->tm_mday * 1000000 + t->tm_hour * 10000 + t->tm_min * 100 + t->tm_sec;
	}
	else
		myprintf("03330! MAC cannot get creation (birth) time\n");
	return 0;
#endif // corresponds to #if (#if defined(__APPLE__) && defined(__MACH__))

#ifdef BSD		  // BSD
#ifndef __APPLE__ // Mac is different (of course)
#ifndef __OpenBSD__
#ifndef __DragonFly__
	struct stat file_stat;
	if (stat(i_file.c_str(), &file_stat) == -1)
	{
		myprintf("03331! stat KAPUTT (BSD)\n");
		return 0;
	}

	if (file_stat.st_birthtime != 0)
	{
		struct tm *t= gmtime(&file_stat.st_birthtime); // Changed to gmtime for UTC
		if (t == NULL)
			return 0;

		return (t->tm_year + 1900) * 10000000000LL + (t->tm_mon + 1) * 100000000LL + t->tm_mday * 1000000 + t->tm_hour * 10000 + t->tm_min * 100 + t->tm_sec;
	}
	myprintf("03332! BSD cannot get creation (birth) time\n");
	return 0;
#endif // corresponds to #ifndef (#ifndef  __DragonFly__)
#endif // corresponds to #ifndef (#ifndef __OpenBSD__)
#endif // corresponds to #ifndef (#ifndef __APPLE__   	// Mac is different (of course))
#endif // corresponds to #ifdef (#ifdef BSD  // BSD)
#ifdef __linux__
	/// myprintf("03333: Getting birth linux %s\n", i_file.c_str());
	struct statx statx_buf;

	if (statx(AT_FDCWD, i_file.c_str(), AT_STATX_SYNC_AS_STAT, STATX_BTIME, &statx_buf) == -1)
	{
		myprintf("03334! statx KAPUTT (Linux)\n");
		return 0;
	}

	if (statx_buf.stx_mask & STATX_BTIME)
	{
		tzset();
		time_t btime_sec= (time_t)statx_buf.stx_btime.tv_sec;

		/// myprintf("Raw timestamp: %ld\n", btime_sec);
		/// struct tm *t = localtime(&btime_sec);

		struct tm *t= gmtime(&btime_sec);

		if (t == NULL)
		{
			myprintf("03336! localtime failed\n");
			return 0;
		}

		/// myprintf("Local time: year=%d month=%d day=%d hour=%d\n",
		///       t->tm_year+1900, t->tm_mon+1, t->tm_mday, t->tm_hour);
		int64_t risultato= (t->tm_year + 1900) * 10000000000LL + (t->tm_mon + 1) * 100000000LL + t->tm_mday * 1000000 + t->tm_hour * 10000 + t->tm_min * 100 + t->tm_sec;
		/// myprintf("03724: risultato %s\n",migliaia(risultato));
		return risultato;
	}

	myprintf("03335! cannot get birth time (linux)\n");
	return 0;
#endif // corresponds to #ifdef (#ifdef __linux__)

#endif // ANCIENT // corresponds to #ifndef (#ifndef ANCIENT)
	myprintf("03336! for some reason cannot get birth time\n");
	return 0;
}

void Jidac::rename_a_dtmap(DTMap &i_source)
{
	DTMap map_fixed;
	for (DTMap::iterator p= i_source.begin(); p != i_source.end(); ++p)
	{
		string newkey	 = rename(p->first);
		map_fixed[newkey]= p->second;
	}
	i_source= map_fixed;
}

std::string pad_left(const std::string &input, size_t target_length)
{
	if (input.length() >= target_length)
		return input;
	return std::string(target_length - input.length(), ' ') + input;
}

// More compact alternative version using counters
int Jidac::comparefilelists(const std::vector<DTMap::iterator> &externalfilelist,
							const std::vector<DTMap::iterator> &internalfilelist,
							DTMap							   &thedt)
{
	myprintf("VERBOSE: INTERNAL-EXTERNAL SYNC\n");

	size_t	extIndex	 = 0;
	size_t	intIndex	 = 0;
	int64_t tobetested	 = 0;
	int		filedahashare= 0;

	int filelocalinontrovati= 0;

	int internalfilecount  = 0;
	int externalfilecount  = 0;
	int internalfoldercount= 0;
	int externalfoldercount= 0;

	for (unsigned int i= 0; i < internalfilelist.size(); i++)
		if (internalfilelist[i]->first.size() > 255)
		{
			if (isdirectory(internalfilelist[i]->first))
				internalfoldercount++;
			else
				internalfilecount++;
		}

	for (unsigned int i= 0; i < externalfilelist.size(); i++)
		if (externalfilelist[i]->first.size() > 255)
		{
			if (isdirectory(externalfilelist[i]->first))
				externalfoldercount++;
			else
				externalfilecount++;
		}

	std::string onlyonehash;

	std::map<std::string, std::vector<std::string> > hasherini;
	vector<string>									filecorrotti;
	vector<string>									soloesterni;
	vector<string>									solointerni;

	uint64_t internisize = 0;
	uint64_t esternisize = 0;
	uint64_t corrottisize= 0;

	while ((extIndex < externalfilelist.size()) || (intIndex < internalfilelist.size()))
	{
		if (intIndex >= internalfilelist.size())
		{
			// Only in EXTERNAL
			soloesterni.push_back(externalfilelist[extIndex]->first);
			esternisize+= externalfilelist[extIndex]->second.size;
			extIndex++;
		}
		else if (extIndex >= externalfilelist.size())
		{
			// Only in INTERNAL
			solointerni.push_back(internalfilelist[intIndex]->first);
			internisize+= internalfilelist[intIndex]->second.size;
			intIndex++;
		}
		else
		{
			const std::string &extFile= externalfilelist[extIndex]->first;
			const std::string &intFile= internalfilelist[intIndex]->first;

			if (extFile < intFile)
			{
				soloesterni.push_back(externalfilelist[extIndex]->first);
				esternisize+= externalfilelist[extIndex]->second.size;
				extIndex++;
			}
			else if (intFile < extFile)
			{
				solointerni.push_back(internalfilelist[intIndex]->first);
				internisize+= internalfilelist[intIndex]->second.size;
				intIndex++;
			}
			else
			{
				extIndex++;
				intIndex++;

				//	DTMap::iterator p=externalfilelist[extIndex];
				if (!isdirectory(extFile))
				{
					DTMap::iterator a= thedt.find(extFile);
					if (a != thedt.end())
					{
						int64_t dimensionefileesterno= prendidimensionefile(extFile.c_str());

						///	myprintf("FILE TEMP %21s %s\n",migliaia(dimensionefileesterno),extFile.c_str());

						/// myprintf("a secondi size %d %d\n",a->second.size,dimensionefileesterno);
						if (a->second.size != dimensionefileesterno)
						{
							if (flagdebug3)
								myprintf("80790: != size internal %21K external %21K\n", a->second.size, dimensionefileesterno);

							string temp= pad_left(migliaia(myabs(a->second.size, dimensionefileesterno)), 21);

							filecorrotti.push_back("SIZE " + temp + " <<" + a->first + ">>");
							corrottisize+= myabs(a->second.size, dimensionefileesterno);
						}
						else
						{
							if (!flagquick)
							{
								string		 myhashtype	   = "";
								string		 myhash		   = "";
								string		 mycrc32	   = "";
								int64_t		 mycreationtime= 0;
								int64_t		 myaccesstime  = 0;
								bool		 myisordered   = false;
								int			 myversion	   = 0;
								franz_posix *myposix	   = NULL;
								bool		 myisadded	   = false;

								string hashfromfile= "";

								decode_franz_block(false, a->second.franz_block,
												   myhashtype,
												   myhash,
												   mycrc32,
												   mycreationtime,
												   myaccesstime,
												   myisordered,
												   myversion,
												   myposix, myisadded);
								tobetested+= a->second.size;

								if (myhashtype != "")
								{
									hasherini[myhashtype].push_back(a->first);
									filedahashare++;
								}
							}
						}
					}
				}
			}
		}
	}

	myprintf("\n");

	if (flagverbose)
		myprintf("\n");
	std::map<std::string, std::vector<std::string> >::iterator it;
	for (it= hasherini.begin(); it != hasherini.end(); ++it)
	{
		std::string				  chiave= it->first;
		std::vector<std::string> &valori= it->second;

		if (flagverbose)
			myprintf("80875: HashType: %12s Elements %12s\n", chiave.c_str(), migliaia(valori.size()));

		vector<std::pair<string, string> > hash_pair;
		int64_t							  starttriple= mtime();
		franzparallelhashfiles(chiave, tobetested, valori, false, hash_pair);
		if (flagverbose)
			myprintf("01434: Hashing time %14.2fs\n", (mtime() - starttriple) / 1000.0);

		for (unsigned int j= 0; j < hash_pair.size(); j++)
		{
			string			thefilename= hash_pair[j].second;
			DTMap::iterator p		   = thedt.find(thefilename);
			if (p == thedt.end())
			{
				myprintf("01437: GURU cannot find thefilename in hash_pair <<%Z>>\n", thefilename.c_str());
				filelocalinontrovati++;
			}
			else
			{
				string		 myhashtype	   = "";
				string		 myhash		   = "";
				string		 mycrc32	   = "";
				int64_t		 mycreationtime= 0;
				int64_t		 myaccesstime  = 0;
				bool		 myisordered   = false;
				int			 myversion	   = 0;
				franz_posix *myposix	   = NULL;
				bool		 myisadded	   = false;

				string hashfromfile= "";

				decode_franz_block(false, p->second.franz_block,
								   myhashtype,
								   myhash,
								   mycrc32,
								   mycreationtime,
								   myaccesstime,
								   myisordered,
								   myversion,
								   myposix, myisadded);

				///	myprintf("Eurekona thefilename %s   edt %s %d\n",thefilename.c_str(),myhash.c_str(),p->second.size);
				if (myhash != hash_pair[j].first)
				{
					string temp= pad_left(migliaia(p->second.size), 21);

					filecorrotti.push_back("HASH " + temp + " <<" + thefilename + ">>");
					corrottisize+= p->second.size;
				}
			}
		}
	}
	eol();
	if (soloesterni.size() > 0)
	{
		color_yellow();
		myprintf("80829: Only EXT %08d (%K %H) - files on the filesystem but NOT in .zpaq\n", (int)soloesterni.size(), esternisize, esternisize);
	}
	else
	{
		color_green();
		myprintf("80831: There are no external files on the filesystem in excess\n");
	}
	color_restore();
	if (!soloesterni.empty())
	{
		size_t ciclomax= flagverbose ? soloesterni.size() : std::min(soloesterni.size(), static_cast<size_t>(10));
		for (size_t i= 0; i < ciclomax; ++i)
			myprintf("80843:                   <<%Z>>\n", soloesterni[i].c_str());
		if (ciclomax < soloesterni.size())
			myprintf("80963$ ... showed first %d files, use -verbose to get them all\n", (int)ciclomax);
		myprintf("\n");
	}

	if (solointerni.size() > 0)
	{
		color_yellow();
		myprintf("80829: Only INT %08d (%K %H) - files in .zpaq but NOT on filesystem\n", (int)solointerni.size(), internisize, internisize);
	}
	else
	{
		color_green();
		myprintf("80829: There are no files in the .zpaq archive that are not present in the filesystem\n");
	}
	color_restore();
	if (!solointerni.empty())
	{
		size_t ciclomax= flagverbose ? solointerni.size() : std::min(solointerni.size(), static_cast<size_t>(10));
		for (size_t i= 0; i < ciclomax; ++i)
			myprintf("80843:                   <<%Z>>\n", solointerni[i].c_str());
		if (ciclomax < solointerni.size())
			myprintf("80962$ ... showed first %d files, use -verbose to get them all\n", (int)ciclomax);
		myprintf("\n");
	}

	if (filecorrotti.size() > 0)
	{
		color_yellow();
		myprintf("80830: BOTH     %08d (%K %H)\n", filedahashare, tobetested, tobetested);
		color_yellow();
		for (unsigned int i= 0; i < filecorrotti.size(); i++)
			myprintf("80898:              %s\n", filecorrotti[i].c_str());
		myprintf("80935:              Total ABS different size %K (%H)\n", corrottisize, corrottisize);
		color_restore();
	}
	else
	{
		color_green();
		myprintf("80831: No difference internal-external files detected\n");
		color_restore();
	}

	if ((internalfilecount + internalfoldercount + externalfilecount + externalfoldercount) > 0)
	{
		color_yellow();
		myprintf("80987: WARNING: longpath (>255) Internal files %s folders %s | external files %s folders %s\n", migliaia(internalfilecount), migliaia2(internalfoldercount), migliaia3(externalfilecount), migliaia4(externalfoldercount));
	}
	else
	{
		color_green();
		myprintf("VERBOSE: No longpath (file/folder names longer than 255 chars) detected\n");
	}
	color_restore();
	int64_t totaldelta= corrottisize + internisize + esternisize + filelocalinontrovati;
	if (totaldelta > 0)
	{
		myprintf("80931$	 Total delta %K (%H)\n", corrottisize + internisize + esternisize + filelocalinontrovati, corrottisize + internisize + esternisize + filelocalinontrovati);
		return 2;
	}
	else
	{
		color_green();
		myprintf("80942: No delta (this is VERY GOOD)\n");
		color_restore();
	}
	return 0;
}

std::string get_top_level_folder(const std::string &path)
{
	if (flagdebug)
		myprintf("Input path = '%s' (length: %d)\n", path.c_str(), (int)path.length());

	// Empty case
	if (path.empty())
	{
		if (flagdebug)
			myprintf("Path is empty, returning empty string\n");
		return "";
	}

	std::string working_path= path;
	if (flagdebug)
		myprintf("Initial working_path = '%s'\n", working_path.c_str());

	// If the path ends with '/', it's already a folder - return it as is
	if (working_path.length() > 1 && working_path[working_path.length() - 1] == '/')
	{
		if (flagdebug)
			myprintf("Path ends with '/', returning as-is: '%s'\n", working_path.c_str());
		return working_path;
	}

	// Special handling for UNC paths (//server/share)
	if (working_path.length() >= 2 && working_path[0] == '/' && working_path[1] == '/')
	{
		if (flagdebug)
			myprintf("UNC path detected\n");
		int	   slash_count= 0;
		size_t pos		  = 2;

		// Find the second slash after //
		for (size_t i= 2; i < working_path.length(); i++)
			if (working_path[i] == '/')
			{
				slash_count++;
				if (flagdebug)
					myprintf("Found slash at position %d, count = %d\n", (int)i, slash_count);
				if (slash_count == 2)
				{
					pos= i;
					break;
				}
			}

		// If we have found at least the server and the share, return up to the second slash
		if (slash_count >= 2)
		{
			std::string result= working_path.substr(0, pos + 1);
			if (flagdebug)
				myprintf("UNC result = '%s'\n", result.c_str());
			return result;
		}
		else
		{
			// Only server or server/share with nothing else, return everything + /
			std::string result= working_path + "/";
			if (flagdebug)
				myprintf("UNC partial result = '%s'\n", result.c_str());
			return result;
		}
	}

	// For a file, find the last slash and return the folder that contains it
	size_t last_slash= working_path.find_last_of('/');
	if (flagdebug)
		myprintf("Last slash position = %d\n", (int)last_slash);

	// If there is no slash, it's a file/folder in the current directory
	if (last_slash == std::string::npos)
	{
		if (flagdebug)
			myprintf("No slash found, returning empty string\n");
		return "";
	}

	// Return everything up to the last slash (inclusive)
	std::string result= working_path.substr(0, last_slash + 1);
	if (flagdebug)
		myprintf("Final result = '%s'\n", result.c_str());
	return result;
}
int Jidac::testverify()
{
	if (files.size() == 0)
	{
		myprintf("03337! no files[] selected\n");
		return 2;
	}
	if (archive == "")
	{
		myprintf("03338! archive empty\n");
		return 2;
	}
	myprintf("03339: Comparing archive content to folder(s)\n");

	command		  = 'l';
	g_optional	  = "versum"; // force isselected
	int		errors= 0;
	int64_t csize = read_archive(NULL, archive.c_str(), &errors, 1);
	if (flagdebug)
		myprintf("03340: dtsize %d\n", (int)dt.size());
	if (csize == 0)
	{
		myprintf("03341! cannot read_archive\n");
		return 2;
	}
	if ((searchfrom != "") || (replaceto != ""))
	{
		myprintf("03342: due to -search/replace fixing the filenames\n");
		rename_a_dtmap(dt);
	}

	uint64_t howmanyfiles= 0;
	g_bytescanned		 = 0;
	g_filescanned		 = 0;
	g_worked			 = 0;
	files_count.clear();
	edt.clear();
	for (unsigned i= 0; i < files.size(); ++i)
	{
		scandir(true, edt, files[i].c_str());
		files_count.push_back(edt.size() - howmanyfiles);
		howmanyfiles= edt.size();
	}
	eol();
	/// myprintf("\n");
	printbar('-');
	for (unsigned i= 0; i < files.size(); ++i)
		if (direxists(files[i]))
			myprintf("03343: %9s in <<%s>>\n", migliaia((int64_t)files_count[i]), files[i].c_str());
	printbar('-');
	myprintf("03344: Total files found: %s\n", migliaia((int64_t)edt.size()));
	myprintf("\n");

	if (flagdebug3)
	{
		for (DTMap::iterator p= edt.begin(); p != edt.end(); ++p)
			myprintf("03345: EDT  %s\n", p->first.c_str());
		printbar('-');
		for (DTMap::iterator p= dt.begin(); p != dt.end(); ++p)
			myprintf("03346: DT   %s\n", p->first.c_str());
	}

	vector<DTMap::iterator> filelist;
	for (DTMap::iterator p= edt.begin(); p != edt.end(); ++p)
	{
		DTMap::iterator a= dt.find(rename(p->first));
		if (a != dt.end() && (all || a->second.date))
		{
			a->second.data= '-';
			filelist.push_back(a);
		}
		p->second.data= '+';
		filelist.push_back(p);
	}
	for (DTMap::iterator a= dt.begin(); a != dt.end(); ++a)
		if (a->second.data != '-' && (all || a->second.date))
		{
			a->second.data= '-';
			filelist.push_back(a);
		}
	int64_t	 usize	= 0;
	unsigned matches= 0, mismatches= 0, internal= 0, externalfile= 0, hashmatches= 0, folderscount= 0, filescount= 0,
			 externalfolder= 0;
	uint32_t	   crc32fromfile;
	int64_t		   hashchecked= 0;
	int64_t		   tobetested = 0;
	vector<string> risultati;
	vector<bool>   risultati_utf8;
	char		   linebuffer[1000];
	unsigned int   ultimapercentuale= 200;
	unsigned int   percentuale;
	int64_t		   starttime= mtime();
	for (unsigned fi= 0; fi < filelist.size(); ++fi)
	{
		DTMap::iterator p= filelist[fi];

		if (isdirectory(p->first))
			folderscount++;
		else
			filescount++;

		if (menoenne)
			if ((mismatches + externalfile + externalfolder + internal) > menoenne)
				break;
		if (!flagnoeta)
		{
			percentuale= 100 * fi / filelist.size();
			if (ultimapercentuale != percentuale)
			{
				int secondi= (mtime() - starttime) / 1000;
				if (secondi == 0)
					secondi= 1;
				if (percentuale == 0)
					percentuale= 1;
				double eta= (secondi * 100 / percentuale) - secondi;

				myprintf("03347: %03d%% %03d:%02d:%02d %10s/%10s @ %10s/s [+/- %19s]\r",
						 percentuale, int(eta / 3600), int(eta / 60) % 60, int(eta) % 60,
						 tohuman(g_worked), tohuman2(g_bytescanned), tohuman3(g_worked / secondi), migliaia2(usize));
				ultimapercentuale= percentuale;
			}
		}
		// Compare external files
		if (p->second.data == '-' && fi + 1 < filelist.size() && filelist[fi + 1]->second.data == '+')
		{
			DTMap::iterator p1			  = filelist[fi + 1];
			string			myhashtype	  = "";
			string			myhash		  = "";
			string			mycrc32		  = "";
			int64_t			mycreationtime= 0;
			int64_t			myaccesstime  = 0;
			bool			myisordered	  = false;
			int				myversion	  = 0;
			franz_posix	   *myposix		  = NULL;
			bool			myisadded	  = false;

			string hashfromfile= "";
			bool   isfolderp1  = isdirectory(p1->first);

			if (!isdirectory(p1->first))
			{
				decode_franz_block(false, p->second.franz_block,
								   myhashtype,
								   myhash,
								   mycrc32,
								   mycreationtime,
								   myaccesstime,
								   myisordered,
								   myversion,
								   myposix, myisadded);
				tobetested+= p->second.size;
			}
			if (flagdebug2)
				myprintf("03348:  |%s| |%s| %s\n", myhashtype.c_str(), myhash.c_str(), p->first.c_str());

			if (equal(p, p1->first.c_str(), crc32fromfile, myhashtype, myhash, hashfromfile)) // crc32 of second parameters
			{
				if (flagquick)
				{
					p->second.data= '=';
					++fi;
					g_worked+= p->second.size;
				}
				else
				{
					if (!isfolderp1)
					{
						if (hashfromfile != "")
						{
							if (flagdebug2)
								myprintf("03349: Check hash for %s\n", p->first.c_str());
							hashchecked+= p->second.size;
							if (hashfromfile != myhash)
							{
								p->second.data= '#';
								snprintf(linebuffer, sizeof(linebuffer), "\nHASH %s NOT MATCH STORED %s vs FROM FILE %s ", myhashtype.c_str(), myhash.c_str(), hashfromfile.c_str());
								risultati.push_back(linebuffer);
								risultati_utf8.push_back(false);
								snprintf(linebuffer, sizeof(linebuffer), "%s\n", p1->first.c_str());
								risultati.push_back(linebuffer);
								risultati_utf8.push_back(true);
							}
							else
							{
								hashmatches++;
								p->second.data= '=';
								++fi;
							}
						}
						else if (mycrc32 != "")
						{
							if (flagdebug2)
								myprintf("03350: Check CRC-32 for %s\n", p->first.c_str());
							uint32_t crc32stored= crchex2int(mycrc32.c_str());
							if (crc32stored != crc32fromfile)
							{
								p->second.data= '#';
								snprintf(linebuffer, sizeof(linebuffer), "\nCRC-32 NOT MATCH STORED %s vs FROM FILE %08X ", mycrc32.c_str(), crc32fromfile);
								risultati.push_back(linebuffer);
								risultati_utf8.push_back(false);
								snprintf(linebuffer, sizeof(linebuffer), "%s\n", p1->first.c_str());
								risultati.push_back(linebuffer);
								risultati_utf8.push_back(true);
							}
							else
							{
								/// if very, do a full hash verify!
								p->second.data= '=';
								++fi;
							}
						}
						else
						{
							if (flagdebug2)
								myprintf("03351: No zpaqfranz check for %s\n", p->first.c_str());
							/// crc-32 is not stored in the archive, cannot tell anything
							p->second.data= '=';
							++fi;
						}
					}
					else
					{
						/// directory always match
						p->second.data= '=';
						++fi;
					}
				}
			}
			else
			{
				p->second.data = '#';
				p1->second.data= '!';
			}
		}
		if (p->second.data == '=')
		{
			++matches;
		}
		if (p->second.data == '#')
			++mismatches;
		if (p->second.data == '-')
			++internal;
		if (p->second.data == '+')
		{
			if (isdirectory(p->first))
				externalfolder++;
			else
				externalfile++;
		}
		if (p->second.data != '=')
		{
			if (!isdirectory(p->first))
				usize+= p->second.size;
			snprintf(linebuffer, sizeof(linebuffer), "%c %s %19s ", char(p->second.data), dateToString(flagutc, p->second.date).c_str(), migliaia(p->second.size));
			risultati.push_back(linebuffer);
			risultati_utf8.push_back(false);
			snprintf(linebuffer, sizeof(linebuffer), "%s\n", p->first.c_str());
			risultati.push_back(linebuffer);
			risultati_utf8.push_back(true);
			if (p->second.data == '!')
			{
				snprintf(linebuffer, sizeof(linebuffer), "\n");
				risultati.push_back(linebuffer);
				risultati_utf8.push_back(false);
			}
		}
	}
	if (!flagnoeta)
	{
		int secondi= (mtime() - starttime) / 1000;
		if (secondi == 0)
			secondi= 1;
		myprintf("03352: %03d%% %03d:%02d:%02d %10s/%10s @ %10s/s [+/- %19s]\r",
				 100, 0, 0, 0,
				 tohuman(g_worked), tohuman2(g_bytescanned), tohuman3(g_worked / secondi), migliaia2(usize));

		///	myprintf("03353: %03d%% %10s/%10s @ %10s/s [+/- %19s]\r",100,tohuman(g_worked),tohuman2(g_bytescanned),tohuman3(g_worked/secondi),migliaia2(usize));
	}
	myprintf("\n\n");

	if (flagquick)
	{
		color_yellow();
		myprintf("03354$ WARNING -quick only compare file size/date, NOT hash!\n");
		color_restore();
	}
	bool myerror= false;
	if (menoenne)
		if ((mismatches + externalfile + externalfolder + internal) > menoenne)
			myprintf("03355! **** STOPPED BY TOO MANY ERRORS -n %d\n", menoenne);
	if (mismatches || externalfile || externalfolder || internal)
		for (unsigned int i= 0; i < risultati.size(); i++)
		{
			if (risultati_utf8[i])
				printUTF8(risultati[i].c_str());
			else
				myprintf("%s", risultati[i].c_str());
		}
	if (matches)
		myprintf("%08d =  same (files %s and folders %s)\n", matches, migliaia2(filescount), migliaia(folderscount));
	if (hashmatches)
	{
		if ((hashchecked == tobetested) && (hashmatches == filescount))
		{
			color_green();
			myprintf("%08d == very same bytes %s AND same file count (VERY good)\n", hashmatches, migliaia(hashchecked));
		}
		else
		{
			color_yellow();
			myprintf("%08d == very same files %19s\n", hashmatches, migliaia(hashchecked));
			myprintf("            expected        %19s\n", migliaia(tobetested));
			myprintf("03356: ****** WARN something strange (hash checking)  *******\n");
			myprintf("03357: ******      some file(s) stored without hash?  *******\n");
			myprintf("03358: ******      hash does not match? unknown hash? *******\n");
		}
		color_restore();
	}
	if (mismatches)
	{
		myprintf("%08d #different\n", mismatches);
		myerror= true;
	}
	if (externalfile)
	{
		myprintf("%08d +external (file missing in ZPAQ)\n", externalfile);
		myerror= true;
	}
	if (externalfolder)
	{
		myprintf("%08d +external (empty folders missing in ZPAQ?)\n", externalfolder);
		myerror= true;
	}

	if (internal)
	{
		myprintf("%08d -internal (file in ZPAQ but not on disk)\n", internal);
		myerror= true;
	}
	if (myerror)
		color_yellow();
	if (usize > 0)
		color_red();
	myprintf("03359: Total different file size: %s bytes\n", migliaia(usize));
	color_restore();

	if (myerror)
	{
		if (usize == 0)
		{
			color_yellow();
			myprintf("03360: Files seems good, maybe folder mismatch? -verbose for details\n");
			color_restore();
			return 1;
		}
		else
		{
			color_red();
			myprintf("03361: use -verbose to get more details\n");
			color_restore();
			return 2;
		}
	}
	return 0;
}

int Jidac::sync()
{
	if (files.size() == 0)
	{
		myprintf("03337! no files[] selected\n");
		return 2;
	}
	if (archive == "")
	{
		myprintf("03338! archive empty\n");
		return 2;
	}
	myprintf("03339: Comparing archive content to folder(s)\n");

	/*
		command		='l';
		g_optional	="versum"; //force isselected
	*/
	int		errors= 0;
	int64_t csize = read_archive(NULL, archive.c_str(), &errors, 1);
	if (flagdebug)
		myprintf("03340: dtsize %d\n", (int)dt.size());
	if (csize == 0)
	{
		myprintf("03341! cannot read_archive\n");
		return 2;
	}
	if ((searchfrom != "") || (replaceto != ""))
	{
		myprintf("03342: due to -search/replace fixing the filenames\n");
		rename_a_dtmap(dt);
	}

	uint64_t howmanyfiles= 0;
	g_bytescanned		 = 0;
	g_filescanned		 = 0;
	g_worked			 = 0;
	files_count.clear();
	edt.clear();
	for (unsigned i= 0; i < files.size(); ++i)
	{
		scandir(true, edt, files[i].c_str());
		eol();
		files_count.push_back(edt.size() - howmanyfiles);
		howmanyfiles= edt.size();
	}
	eol();
	/// myprintf("\n");
	///	printbar('-');
	for (unsigned i= 0; i < files.size(); ++i)
		if (direxists(files[i]))
			myprintf("03343: %9s in <<%s>>\n", migliaia((int64_t)files_count[i]), files[i].c_str());
	/// printbar('-');
	myprintf("03344: Total external files found: %s\n", migliaia((int64_t)edt.size()));
	myprintf("\n");

	if (flagdebug3)
	{
		int j= 0;
		for (DTMap::iterator a= dt.begin(); a != dt.end(); ++a) // Note: do not increment here
		{
			j++;
			if (j == 10)
				break;
			myprintf("start dt %s\n", a->first.c_str());
		}
	}
	if (flagdebug3)
	{
		for (DTMap::iterator p= edt.begin(); p != edt.end(); ++p)
			myprintf("03345: EDT  %s\n", p->first.c_str());
		printbar('-');
		for (DTMap::iterator p= dt.begin(); p != dt.end(); ++p)
			myprintf("03346: DT   %s\n", p->first.c_str());
	}

	vector<DTMap::iterator> filelist;
	vector<DTMap::iterator> externalfilelist;
	vector<DTMap::iterator> internalfilelist;

	// Pre-allocare spazio conosciuto
	externalfilelist.reserve(edt.size()); // We already know the size
	internalfilelist.reserve(dt.size());  // Avoid reallocations

	for (DTMap::iterator p= edt.begin(); p != edt.end(); ++p)
	{
		externalfilelist.push_back(p);
	}

	if (flagdebug3)
	{
		int i= 0;
		for (DTMap::iterator a= dt.begin(); a != dt.end(); ++a) // Note: do not increment here
		{
			i++;
			if (i == 10)
				break;
			myprintf("pre dt %s\n", a->first.c_str());
		}
	}
	for (DTMap::iterator a= dt.begin(); a != dt.end(); ++a) // Note: do not increment here
	{
		if (flagdebug3)
			myprintf("New dt %s\n", a->first.c_str());
		internalfilelist.push_back(a);
	}
	if (flagdebug3)
	{
		for (unsigned i= 0; i < internalfilelist.size(); ++i)
			myprintf("81508: INTERNAL %08d %s\n", i, internalfilelist[i]->first.c_str());
		for (unsigned i= 0; i < externalfilelist.size(); ++i)
			myprintf("81509: EXTERNAL %08d %s\n", i, externalfilelist[i]->first.c_str());
	}
	if (internalfilelist.size() == 0)
	{
		color_red();
		myprintf("81623! No INTERNAL file in archive (wrong path?)\n");
		color_restore();
	}
	else
		myprintf("81541: Internal count %d\n", (int)internalfilelist.size());
	if (externalfilelist.size() == 0)
	{
		color_red();
		myprintf("81661! NO EXTERNAL files (wrong path?)\n");
		color_restore();
	}
	else
		myprintf("81541: External count %d\n", (int)externalfilelist.size());

	if ((externalfilelist.size() > 0) && (internalfilelist.size() > 0))
	{
		string primaesterna= get_top_level_folder(externalfilelist[0]->first);
		if (flagdebug)
			myprintf("Internalpath   %s\n", internalfilelist[0]->first.c_str());
		string primainterna= get_top_level_folder(internalfilelist[0]->first);
		if (flagdebug)
			myprintf("Thinking       %s\n", primainterna.c_str());

		if (primaesterna != primainterna)
		{
			color_yellow();
			myprintf("81022: External and internal paths does not match. Multiple paths? Fix with -find -replace?\n");
			myprintf("81023: external %Z\n", primaesterna.c_str());
			myprintf("81024: internal %Z\n", primainterna.c_str());
			color_restore();
		}
	}

	return comparefilelists(externalfilelist, internalfilelist, dt);
}

bool Jidac::grep(const string i_filename, const string i_search)
{
	if (i_filename == "")
	{
		myprintf("03362! i_filename empty\n");
		return false;
	}
	if (i_search == "")
	{
		myprintf("03363! i_search empty\n");
		return false;
	}

	FILE *file= freadopen(i_filename.c_str());
	if (file == NULL)
	{
		myprintf("03364! cannot fdreadopen file %s\n", i_filename.c_str());
		return false;
	}

	char line[1024];
	int	 line_number= 1;
	bool found		= false;
	while (fgets(line, sizeof(line), file) != NULL)
	{
		if (strstr(line, i_search.c_str()) != NULL)
		{
			if (flagdebug)
				myprintf("03365: Founded @ line %d: %s", line_number, line);
			found= true;
			break;
		}
		line_number++;
	}

	fclose(file);
	return found;
}

struct TestCase {
    string filename;
    string expected_content;
    string description;
    /// a constructor, and not {...}: C++98 (gcc 3.4 of ESXi)
    TestCase(const string& i_f, const string& i_e, const string& i_d) : filename(i_f), expected_content(i_e), description(i_d) {}
};

int Jidac::checkautotest(string i_path, bool i_quick)
{
    if (i_path == "")
    {
        myprintf("03366! i_path empty\n");
        return 2;
    }
    if (!direxists(i_path))
    {
        myprintf("03367! autotest path does not exist %s\n", i_path.c_str());
        return 2;
    }
    /// the QUICK suite: exactly the operations of g_autotestquick, nothing more, nothing less
    if (i_quick)
    {
        i_path= includetrailingbackslash(wintolinuxpath(i_path));
        int errori= 0;
        vector<string> segni;
        if (fileexists(i_path + "quickops.txt"))
            readfiletoarray(i_path + "quickops.txt", segni);
        vector<string> fatti;
        for (unsigned int i= 0; i < segni.size(); i++)
        {
            string t= segni[i];
            while ((t.size() > 0) && ((t[t.size() - 1] == ' ') || (t[t.size() - 1] == '\r') || (t[t.size() - 1] == '\n')))
                t= t.substr(0, t.size() - 1);
            if (t != "")
                fatti.push_back(t);
        }
        myprintf("64015: Checking the QUICK suite (in %Z): %u operations planned, %u done\n", i_path.c_str(), g_autotestquickn, (unsigned int)fatti.size());
        std::set<string> previsti;
        for (unsigned int i= 0; i < g_autotestquickn; i++)
        {
            const bool fatta= (i < fatti.size()) && (fatti[i] == myto_string(i + 1));
            bool       buona= fatta;
            for (int j= 0; j < 2; j++)
                if (g_autotestquick[i].uscita[j] != NULL)
                {
                    previsti.insert(g_autotestquick[i].uscita[j]);
                    if (!grep(i_path + g_autotestquick[i].uscita[j], g_autotestquick[i].atteso[j]))
                        buona= false;
                }
            myprintf("64016: %u. (%s) :", i + 1, g_autotestquick[i].descrizione);
            if (buona)
            {
                color_green();
                myprintf(" OK\n");
            }
            else
            {
                color_red();
                myprintf(" ERROR (%s)\n", fatta ? "wrong result" : "NOT executed, or out of order");
                errori++;
            }
            color_restore();
        }
        /// nothing else: no other operation, no output of the full suite
        for (unsigned int i= g_autotestquickn; i < fatti.size(); i++)
        {
            myprintf("64017! operation NOT in the quick suite: %s\n", fatti[i].c_str());
            errori++;
        }
        for (int i= 1; i <= 99; i++)
        {
            const string altro= "quick" + myto_string(i) + ".txt";
            if (fileexists(i_path + altro) && (previsti.find(altro) == previsti.end()))
            {
                myprintf("64018! output NOT of the quick suite: %s\n", altro.c_str());
                errori++;
            }
            const string pieno= "out" + itos(i, 2) + ".txt";
            if (fileexists(i_path + pieno))
            {
                myprintf("64019! output of the FULL suite in a quick run: %s\n", pieno.c_str());
                errori++;
            }
        }
        if (errori > 0)
        {
            myprintf("64020! QUICK suite: ERRORS %s (exactly %u operations expected)\n", migliaia(errori), g_autotestquickn);
            return 2;
        }
        myprintf("64021: QUICK suite: the %u operations, and nothing else, all OK\n", g_autotestquickn);
        return 0;
    }
    
    vector<TestCase> test_cases;
    
    // Test base sempre presenti
    test_cases.push_back(TestCase("out01.txt", "NOT renamed files  256", "Extracting pre-computed data"));
    test_cases.push_back(TestCase("out02.txt", "67708591460BCE3BC45AE086A342F9F390AD2913A22639EC7AF3646B7D2AEA78", "Adding and/or extracting data"));
    test_cases.push_back(TestCase("out03.txt", "(all OK)", "Testing with -verify"));
    test_cases.push_back(TestCase("out04.txt", "(all OK)", "Verify"));
    test_cases.push_back(TestCase("out05.txt", "(all OK)", "w (chunked test)"));
    test_cases.push_back(TestCase("out06.txt", "SURE    :       42.727 of       42.727 (stored=decompressed=file on disk)", "p (paranoid test)"));
    test_cases.push_back(TestCase("out07.txt", "GLOBAL SHA256: 7B32DB3F6F0180062773C5A046A2C99D17BE7668202379BA136E7A4D134FFC26", "Extract with different hashes)"));
    test_cases.push_back(TestCase("out08.txt", "GLOBAL SHA256: 5088D26FE31EEE0E04F1569CD4851B6DE4A1CBC00EC56BAC7F390A123A8C1111", "Fixed encrypted -chunk multipart creating/extracting"));
    test_cases.push_back(TestCase("out09.txt", "Files deleted                       42.735", "Fixed -chunk multipart testing"));
    test_cases.push_back(TestCase("out10.txt", "10000.dat", "Fixed -chunk multipart verify"));
    test_cases.push_back(TestCase("out11.txt", "10000.dat", "Folder comparing"));
    test_cases.push_back(TestCase("out12.txt", "(all OK)", "Testbackup for multipart"));
    test_cases.push_back(TestCase("out13.txt", "OK      XXHASH64B : 00000256 of 00000256", "Standard multipart with backup command"));
    test_cases.push_back(TestCase("out14.txt", "== very same bytes 9.472.000", "Extracting/testing single version from multipart"));
    test_cases.push_back(TestCase("out15.txt", "===", "Creating/extracting different hashes"));
    test_cases.push_back(TestCase("out16.txt", "All OK (paranoid test with check against filesystem)", "Paranoid test of different hashes"));
    test_cases.push_back(TestCase("out17.txt", "+              1", "Robocopy of folder"));
    test_cases.push_back(TestCase("out18.txt", "GLOBAL SHA256: 9C443D84B87B678E4506AD5F6A2FC89B83546E286F19998899DC4461BB9F97D0", "Extract multihash"));
    test_cases.push_back(TestCase("out19.txt", "GLOBAL SHA256: 9C443D84B87B678E4506AD5F6A2FC89B83546E286F19998899DC4461BB9F97D0", "Testing that extract is OK (a)"));
    test_cases.push_back(TestCase("out20.txt", "GLOBAL SHA256: 9C443D84B87B678E4506AD5F6A2FC89B83546E286F19998899DC4461BB9F97D0", "Testing that extract is OK (b)"));
    test_cases.push_back(TestCase("out21.txt", "GLOBAL SHA256: EEBFFD8399E88CE05BCFD1AAE65C4A118E57638511AF18255C5A295A6378F437", "Creating & extracting big file"));
    test_cases.push_back(TestCase("out22.txt", "(all OK)", "Testing with sequential algo"));
    
    // Test aggiuntivi Franzen
    if (g_franzen != "")
    {
        // AES + Franzen Creation
        test_cases.push_back(TestCase("out23.txt", "(all OK)", "Creating archive 2"));
        test_cases.push_back(TestCase("out24.txt", "(all OK)", "Updating archive 2"));
        test_cases.push_back(TestCase("out25.txt", "(all OK)", "Updating archive 2"));
        test_cases.push_back(TestCase("out26.txt", "(all OK)", "Discarded update 2"));
        
        // AES + Franzen Verify & Decode
        test_cases.push_back(TestCase("out27.txt", "(all OK)", "PP test 2"));
        test_cases.push_back(TestCase("out28.txt", "(all OK)", "Franzen test 2"));
        test_cases.push_back(TestCase("out29.txt", "(all OK)", "Decoding 2"));
        test_cases.push_back(TestCase("out30.txt", "(all OK)", "t of the decoded .franzen 2"));
        
        // Only Franzen Creation
        test_cases.push_back(TestCase("out31.txt", "(all OK)", "Creating archive 1"));
        test_cases.push_back(TestCase("out32.txt", "(all OK)", "Updating archive 1"));
        test_cases.push_back(TestCase("out33.txt", "(all OK)", "Updating archive 1"));
        test_cases.push_back(TestCase("out34.txt", "(all OK)", "Discarded update 1"));
        
        // Only Franzen Verify & Decode
        test_cases.push_back(TestCase("out35.txt", "(all OK)", "PP test 1"));
        test_cases.push_back(TestCase("out36.txt", "(all OK)", "Franzen test 1"));
        test_cases.push_back(TestCase("out37.txt", "(all OK)", "Decoding 1"));
        test_cases.push_back(TestCase("out38.txt", "(all OK)", "t of the decoded .franzen 1"));
        
        // Extraction
        test_cases.push_back(TestCase("out39.txt", "(all OK)", "extract big1 2"));
        test_cases.push_back(TestCase("out40.txt", "(all OK)", "extract big3 2"));
        test_cases.push_back(TestCase("out41.txt", "(all OK)", "extract big3 2"));
        test_cases.push_back(TestCase("out42.txt", "(all OK)", "extract big1 1"));
        test_cases.push_back(TestCase("out43.txt", "(all OK)", "extract big2 1"));
        test_cases.push_back(TestCase("out44.txt", "(all OK)", "extract big3 1"));
        
        // Final multi-file compare
        test_cases.push_back(TestCase("out45.txt", "Binary ==", "fc big1 2"));
        test_cases.push_back(TestCase("out46.txt", "Binary ==", "fc big2 2"));
        test_cases.push_back(TestCase("out47.txt", "Binary ==", "fc big3 2"));
        test_cases.push_back(TestCase("out48.txt", "Binary ==", "fc big1 1"));
        test_cases.push_back(TestCase("out49.txt", "Binary ==", "fc big2 1"));
        test_cases.push_back(TestCase("out50.txt", "Binary ==", "fc big3 1"));
    }
    
    i_path = wintolinuxpath(i_path);
    i_path = includetrailingbackslash(i_path);

    // Hash healing: always there
    test_cases.push_back(TestCase("out51.txt", "(all OK)", "Attribute-only change, hash read again"));
    test_cases.push_back(TestCase("out52.txt", "(all OK)", "Verify after attribute-only change"));
    test_cases.push_back(TestCase("out53.txt", "(all OK)", "-touch on a 7.15 archive"));
    test_cases.push_back(TestCase("out54.txt", "SHA-3 : 00000003 of 00000003", "Verify after -touch"));
    test_cases.push_back(TestCase("out55.txt", "0 +added, 0 -removed", "-touch again: nothing to do"));
    test_cases.push_back(TestCase("out64.txt", "(all OK)", "UTF-8, emoji, % and spaces in names"));
    // -m6: the "m4.5" (-m4 with sparse contexts)
    test_cases.push_back(TestCase("out68.txt", "(all OK)", "-m6 (m4.5) names, big files, one .exe"));
    test_cases.push_back(TestCase("out69.txt", "(all OK)", "-m6 testing"));
    test_cases.push_back(TestCase("out70.txt", "All OK (paranoid test with check against filesystem)", "-m6 paranoid (unzpaq)"));
#ifdef ZPAQZSTD
    // -m8: zstd stored + ZPAQL decoder
    test_cases.push_back(TestCase("out87.txt", "(all OK)", "-m8 (zstd) creating, 1.75 GB with dedup"));
    test_cases.push_back(TestCase("out88.txt", "(all OK)", "-m8 testing (native zstd decoder)"));
    test_cases.push_back(TestCase("out89.txt", "All OK (paranoid test with check against filesystem)", "-m8 paranoid (unzpaq runs the ZPAQL decoder)"));
    test_cases.push_back(TestCase("out90.txt", "(all OK)", "-m8h19 (zstd 19) names and big files"));
    test_cases.push_back(TestCase("out91.txt", "All OK (paranoid test with check against filesystem)", "-m8h19 paranoid (ZPAQL decoder)"));
    test_cases.push_back(TestCase("out92.txt", "(all OK)", "-m86a3 (zstd fast) 64 MB blocks"));
    test_cases.push_back(TestCase("out93.txt", "All OK (paranoid test with check against filesystem)", "-m86a3 paranoid (ZPAQL decoder)"));
#endif
    // -turbo: the same archive, to the byte
    test_cases.push_back(TestCase("out83.txt", "(all OK)", "-turbo add (parallel fragmenter)"));
    test_cases.push_back(TestCase("out84.txt", "Binary ==", "-turbo archive == plain archive (2 versions)"));
    test_cases.push_back(TestCase("out85.txt", "(all OK)", "-turbo archive testing"));
#ifdef ZPAQZSTD
    test_cases.push_back(TestCase("out86.txt", "Binary ==", "-turbo -m8 archive == plain -m8 archive"));
#endif

///NOSFTPSTART
    // Mount: only if the script has them (autotest found a working mount)
    if (fileexists(i_path + "mounttest.txt"))
    {
        test_cases.push_back(TestCase("out56.txt", "Mount test: OK", "Mount last version"));
        test_cases.push_back(TestCase("out57.txt", "Mount test: OK", "Mount every version (-all)"));
        test_cases.push_back(TestCase("out58.txt", "Mount test: OK", "Mount version 3 (-until)"));
        test_cases.push_back(TestCase("out59.txt", "Mount test: OK", "Mount encrypted -chunk multipart"));
        test_cases.push_back(TestCase("out60.txt", "Mount test: OK", "Mount encrypted backup multipart"));
        test_cases.push_back(TestCase("out61.txt", "Mount test: OK", "Mount the healed archive"));
        test_cases.push_back(TestCase("out65.txt", "Mount test: OK", "Mount UTF-8, emoji, % and spaces in names"));
        test_cases.push_back(TestCase("out66.txt", "0 hash OK, 3 size and date only", "Mount a zpaq 7.15 version (no hash)"));
        test_cases.push_back(TestCase("out67.txt", "Mount test: OK", "Mount big files"));
        test_cases.push_back(TestCase("out76.txt", "Mount test: OK", "Mount -m6 (m4.5) archive"));
#ifdef ZPAQZSTD
        test_cases.push_back(TestCase("out94.txt", "Mount test: OK", "Mount -m8 (zstd) archive"));
#endif
        if (g_franzen != "")
        {
            test_cases.push_back(TestCase("out62.txt", "Mount test: OK", "Mount AES + Franzen"));
            test_cases.push_back(TestCase("out63.txt", "Mount test: OK", "Mount Franzen"));
        }
    }
    else
        myprintf("56475: No mount tests in this run (no mounttest.txt)\n");
///NOSFTPEND

    myprintf("03368: Checking results (in %Z)\n", i_path.c_str());
    
    int errori = 0;
    for (size_t i = 0; i < test_cases.size(); i++)
    {
        const TestCase& tc = test_cases[i];
        myprintf("03370: %03d (%s) :", (int)i, tc.filename.c_str());
        
        bool trovato = grep(i_path + tc.filename, tc.expected_content);
        if (trovato)
        {
            color_green();
            myprintf(" OK (%s)\n", tc.description.c_str());
        }
        else
        {
            color_red();
            myprintf(" ERROR (%s) cannot find %s\n", tc.description.c_str(), tc.expected_content.c_str());
            errori++;
        }
        color_restore();
    }
    
    if (errori > 0)
    {
        myprintf("03371! ERRORS %s\n", migliaia(errori));
        return 2;
    }
    else
    {
        myprintf("03372: Everything is OK (this is good)\n");
        myprintf("03373: It is now safe to remove the test folder\n");
    }
    return 0;
}
