bool isvhdheader(const std::string &filename)
{
	return filename.length() == 14 &&
		   filename.rfind("image_", 0) == 0 &&
		   (filename[6] >= 'A' && filename[6] <= 'Z') &&
		   filename.rfind(".header") == 7;
}
bool isvhdfooter(const std::string &filename)
{
	return filename.length() == 14 &&
		   filename.rfind("image_", 0) == 0 &&
		   (filename[6] >= 'A' && filename[6] <= 'Z') &&
		   filename.rfind(".footer") == 7;
}

bool isvhdmeta(const std::string &filename)
{
	return filename.length() == 12 &&
		   filename.rfind("image_", 0) == 0 &&
		   (filename[6] >= 'A' && filename[6] <= 'Z') &&
		   filename.rfind(".meta") == 7;
}

bool isvhdimage(const std::string &filename)
{
	return filename.length() == 11 &&
		   filename.rfind("image_", 0) == 0 &&
		   (filename[6] >= 'A' && filename[6] <= 'Z') &&
		   filename.rfind(".fhd") == 7;
}

char get_lettera(const std::string &filename)
{
    if (isvhdimage(filename)) 
	    return filename[6];
    if (isvhdmeta(filename))
        return filename[6];
    return '\0';  // Non valido
}

