{
	return filename.length() == 11 &&
		   filename.rfind("image_", 0) == 0 &&
		   (filename[6] >= 'A' && filename[6] <= 'Z') &&
		   filename.rfind(".raw") == 7;
}

char get_lettera_raw(const std::string &filename)
{
    if (israwimage(filename)) 
	    return filename[6];
    return '\0';  // Non valido
}

