long long get_device_size_ioctl(int fd)
{
#ifdef __linux__
	// Linux: prova prima BLKGETSIZE64, poi BLKGETSIZE come fallback
	unsigned long long size64;
	if (ioctl(fd, BLKGETSIZE64, &size64) == 0)
	{
		if (flagdebug)
			myprintf("04375: Using Linux BLKGETSIZE64\n");
		return (long long)size64;
	}

	unsigned long sectors;
	if (ioctl(fd, BLKGETSIZE, &sectors) == 0)
	{
		if (flagdebug)
			myprintf("04382: Using Linux BLKGETSIZE (sectors * 512)\n");
		return (long long)sectors * 512;
	}

#elif defined(__FreeBSD__) || defined(__DragonFly__)
	// FreeBSD e DragonFly BSD
	off_t size;
	if (ioctl(fd, DIOCGMEDIASIZE, &size) == 0)
	{
		if (flagdebug)
			myprintf("04391: Using BSD DIOCGMEDIASIZE\n");
		return (long long)size;
	}

#elif defined(__NetBSD__)
	// NetBSD
	/*
	struct disklabel dl;
	if (ioctl(fd, DIOCGDINFO, &dl) == 0)
	{
		if (flagdebug)
			myprintf("04400: Using BSD DIOCGDINFO (disklabel)\n");
		return (long long)dl.d_secsize * dl.d_secperunit;
	}
	*/
	return -1;
#elif defined(__OpenBSD__)
	if (flagdebug)
		if (fd != -200)
			myprintf("04410: OpenBSD: not good\n");
	return -1;

#elif defined(__APPLE__)
	// macOS
	uint64_t blocksize;
	uint64_t blockcount;

	if (ioctl(fd, DKIOCGETBLOCKSIZE, &blocksize) == 0 &&
		ioctl(fd, DKIOCGETBLOCKCOUNT, &blockcount) == 0)
	{
		if (flagdebug)
			myprintf("04411: Using macOS DKIOCGET* (blocksize=%s, blockcount=%s)\n", migliaia(blocksize), migliaia2(blockcount));
		return (long long)(blocksize * blockcount);
	}

#elif defined(__sun) || defined(__SVR4)
	// Solaris
	/*
	struct dk_minfo dkmp;
	if (ioctl(fd, DKIOCGMEDIAINFO, &dkmp) == 0)
	{
		if (flagdebug)
			myprintf("04422: Using Solaris DKIOCGMEDIAINFO\n");
		return (long long)(dkmp.dki_lbsize * dkmp.dki_capacity);
	}

	// Fallback for old Solaris
	struct vtoc vtoc;
	if (ioctl(fd, DKIOCGVTOC, &vtoc) == 0)
	{
		if (flagdebug)
			myprintf("04430: Using Solaris DKIOCGVTOC (fallback)\n");
		return (long long)vtoc.v_capacity * 512;
	}
	*/
	return -1;

#elif defined(_AIX)
	// AIX
	struct devinfo devinfo;
	if (ioctl(fd, IOCINFO, &devinfo) == 0)
		if (devinfo.devtype == DD_DISK)
		{
			if (flagdebug)
				myprintf("04440: Using AIX IOCINFO\n");
			return (long long)devinfo.un.dk.bytpsec * devinfo.un.dk.numblks;
		}

#elif defined(__hpux)
	// HP-UX
	struct capacity cap;
	if (ioctl(fd, SIOC_CAPACITY, &cap) == 0)
	{
		if (flagdebug)
			myprintf("04450: Using HP-UX SIOC_CAPACITY\n");
		return (long long)cap.lba * 512;
	}
#endif

	if (flagdebug)
		myprintf("04456: No ioctl method available for this platform\n");
	return -1; // No ioctl method available or error
}
/**
 * Ottiene la dimensione usando lseek (metodo universale ma meno affidabile per dispositivi)
 */
long long get_device_size_lseek(int fd)
{
	if (flagdebug)
		myprintf("04466: Trying lseek method\n");

	off_t current_pos= lseek(fd, 0, SEEK_CUR);
	if (current_pos == -1)
	{
		if (flagdebug)
			myprintf("04471: lseek SEEK_CUR failed: %s\n", strerror(errno));
		return -1;
	}

	off_t size= lseek(fd, 0, SEEK_END);
	if (size == -1)
	{
		if (flagdebug)
			myprintf("04480: lseek SEEK_END failed: %s\n", strerror(errno));
		// Restore original position also in case of error
		lseek(fd, current_pos, SEEK_SET);
		return -1;
	}

	if (lseek(fd, current_pos, SEEK_SET) == -1)
	{
		if (flagdebug)
			myprintf("04488: lseek SEEK_SET failed: %s\n", strerror(errno));
		return -1;
	}

	if (flagdebug)
		myprintf("04494: method successful, size=%s\n", migliaia(size));
	return (long long)size;
}

long long get_device_size(int fd)
{
	long long size;

	if (flagdebug)
		myprintf("04506: Attempting to get device size for fd=%d\n", fd);

	// First try the platform-specific ioctl method
	size= get_device_size_ioctl(fd);
	if (size > 0)
	{
		if (flagdebug)
			myprintf("04513: ioctl method successful, size=%s bytes\n", migliaia(size));
		return size;
	}

	if (flagdebug)
		myprintf("04518: ioctl method failed, trying lseek\n");

	// Fallback on lseek
	size= get_device_size_lseek(fd);
	if (size > 0)
	{
		if (flagdebug)
			myprintf("04525: lseek method successful, size=%s bytes\n", migliaia(size));
		return size;
	}

	if (flagdebug)
		myprintf("04530: All methods failed\n");
	return -1; // All methods failed
}
#endif

#if !defined(_WIN32) && !defined(ESX)
/// images, *nix: the errors that mean the source is gone, not a bad sector
static bool img_sparitounix(int i_errore)
{
	return (i_errore == ENODEV) || (i_errore == ENXIO) || (i_errore == EBADF);
}
/// all of it or an error (-1, o_errore) or the end (less)
static ssize_t img_preadunix(int i_fd, char *o_buffer, size_t i_bytes, int64_t i_offset, int &o_errore)
{
	o_errore	= 0;
	size_t fatti= 0;
	while (fatti < i_bytes)
	{
		ssize_t letti= pread(i_fd, o_buffer + fatti, i_bytes - fatti, (off_t)(i_offset + (int64_t)fatti));
		if (letti < 0)
		{
			if (errno == EINTR)
				continue;
			o_errore= errno;
			return -1;
		}
		if (letti == 0)
			break;
		fatti+= (size_t)letti;
	}
	return (ssize_t)fatti;
}
/*
	Images, *nix (dd): a read that goes on, as img_leggi on Windows. All at once;
	if it fails 64 KB at a time, then sector by sector the 64 KB that fail. What
	cannot be read stays zeros, counted; a dead zone (1 MB in a row) not sector
	by sector; a source gone: zeros to the end, without reading.
	Returns the bytes given: all of them, less only at the end of the source
*/
static size_t img_leggiunix(int i_fd, int64_t i_offset, char *o_buffer, size_t i_bytes, uint32_t i_settore)
{
	if ((i_settore < 512) || (i_settore > 65536))
		i_settore= 512;
	int errore= 0;
	if (!g_imgmorto)
	{
		ssize_t letti= img_preadunix(i_fd, o_buffer, i_bytes, i_offset, errore);
		if (letti >= 0)
		{
			g_imgbuio= 0;
			return (size_t)letti;
		}
		if (img_sparitounix(errore))
			g_imgmorto= true;
	}
	const size_t pezzo= 65536;
	for (size_t fatti= 0; fatti < i_bytes; fatti+= pezzo)
	{
		const size_t quanto= (i_bytes - fatti < pezzo) ? (i_bytes - fatti) : pezzo;
		if (!g_imgmorto)
		{
			ssize_t letti= img_preadunix(i_fd, o_buffer + fatti, quanto, i_offset + (int64_t)fatti, errore);
			if (letti >= 0)
			{
				if ((size_t)letti < quanto) /// the end of the source
					return fatti + (size_t)letti;
				g_imgbuio= 0;
				continue;
			}
			if (img_sparitounix(errore))
				g_imgmorto= true;
		}
		if (g_imgmorto || (g_imgbuio >= 16))
		{
			memset(o_buffer + fatti, 0, quanto);
			img_errore(i_offset + (int64_t)fatti, (int64_t)quanto, i_settore);
			continue;
		}
		bool qualcosa= false;
		for (size_t s= 0; s < quanto; s+= i_settore)
		{
			const size_t q= (quanto - s < i_settore) ? (quanto - s) : i_settore;
			if (!g_imgmorto)
			{
				ssize_t letti= img_preadunix(i_fd, o_buffer + fatti + s, q, i_offset + (int64_t)(fatti + s), errore);
				if ((letti >= 0) && ((size_t)letti == q))
				{
					qualcosa= true;
					continue;
				}
				if ((letti < 0) && img_sparitounix(errore))
					g_imgmorto= true;
			}
			memset(o_buffer + fatti + s, 0, q);
			img_errore(i_offset + (int64_t)(fatti + s), (int64_t)q, i_settore);
		}
		g_imgbuio= qualcosa ? 0 : g_imgbuio + 1;
	}
	return i_bytes;
}
#endif

bool Jidac::preparadump(const std::string &image_path)
{
#ifdef ESX
	(void)image_path;
#else
	if (image_path == "")
	{
		myprintf("04276: image_path empty\n");
		return false;
	}

	// Close any previous file descriptor
	if (g_device_fd != -1)
	{
		close(g_device_fd);
		g_device_fd= -1;
	}

	// Open the device in read-only mode
	g_device_fd= open(image_path.c_str(), O_RDONLY);

	if (g_device_fd == -1)
	{
		myprintf("04291: Error opening device %s: %s\n", image_path.c_str(), strerror(errno));
		return false;
	}

	g_device_offset = 0;
	g_device_settore= 512;
#if defined(BLKSSZGET)
	int settore= 0;
	if ((ioctl(g_device_fd, BLKSSZGET, &settore) == 0) && (settore >= 512) && (settore <= 65536))
		g_device_settore= (uint32_t)settore;
#endif
	// Get the device size
	int64_t device_size= get_device_size(g_device_fd);

	if (device_size == -1)
		myprintf("04300$ Warning: Cannot determine device size\n");
	else
		g_device_size= device_size;

	if (flagverbose)
		myprintf("04296: Device %s open\n", image_path.c_str());
#endif
	return true;
}

// Function to read data from the device
int Jidac::elaboradump(char *buffer, size_t buffer_size)
{
#ifdef ESX
	(void)buffer;
	(void)buffer_size;
	return 0;
#else
	if (g_device_fd == -1)
	{
		myprintf("04298! Error, device not open\n");
		seppuku();
		return -1;
	}

	if ((buffer == NULL) || (buffer_size == 0))
	{
		myprintf("04305: Error, buffer kaputt\n");
		seppuku();
		return -1;
	}

	/// the position every time; what cannot be read stays zeros, counted (a giant READ ERROR at the end)
	size_t quanto= buffer_size;
	if (g_device_size > 0)
	{
		if (g_device_offset >= g_device_size)
			return 0;
		if (g_device_offset + (int64_t)quanto > g_device_size)
			quanto= (size_t)(g_device_size - g_device_offset);
	}
	const size_t letti= img_leggiunix(g_device_fd, g_device_offset, buffer, quanto, g_device_settore);
	g_device_offset+= (int64_t)letti;
	// Returns the number of bytes read (0 if EOF)
	return (int)letti;
#endif
}

// Function to close the device
bool Jidac::chiudidump()
{
#ifndef ESX
	if (g_device_fd != -1)
	{
		if (close(g_device_fd) == -1)
		{
			myprintf("0423: Error closing: %s\n", strerror(errno));
			g_device_fd= -1;
			return false;
		}
		g_device_fd= -1;
		myprintf("04238: Device closed (this is good)\n");
		return true;
	}
#endif
	return true;
}
#endif

