void testStress(franzVSS &vss)
{
	myprintf("\n");
	printbar('=');
	myprintf("   STRESS TEST\n");
	printbar('=');

	int cycles;
	myprintf("Enter number of create/delete cycles: ");
	if (scanf("%d", &cycles) != 1 || cycles <= 0)
	{
		myprintf("Invalid input\n");
		return;
	}

	int successCount= 0;
	int failCount	= 0;

	for (int i= 0; i < cycles; i++)
	{
		myprintf("\n*** Cycle %d/%d ***\n", i + 1, cycles);

		// Create
		myprintf("Creating snapshot (of C)...");
		if (vss.create('C'))
		{
			myprintf(" OK\n");
			Sleep(500);

			// Delete
			myprintf("Deleting snapshot...");
			if (vss.deleteSnapshot())
			{
				color_green();
				printf(" OK\n");
				color_restore();
				successCount++;
			}
			else
			{
				color_red();
				myprintf(" FAILED\n");
				color_restore();
				failCount++;
			}
		}
		else
		{
			color_red();
			myprintf(" FAILED\n");
			color_restore();
			failCount++;
		}

		Sleep(200);
	}

	myprintf("\n");
	printbar('=');
	myprintf("   STRESS TEST RESULTS\n");
	printbar('=');
	myprintf("Total Cycles:    %d\n", cycles);
	myprintf("Successful:      %d\n", successCount);
	myprintf("Failed:          %d\n", failCount);
	myprintf("Success Rate:    %.1f%%\n", (successCount * 100.0) / cycles);
	printbar('=');
}


void Jidac::vssmenu()
{
	if (!isadmin())
	{
		myprintf("\n");
		myprintf("06451! you need admin rights, quit\n");
		return;
	}

	franzVSS vss;

	int	 choice;
	bool running= true;

	while (running)
	{
		printMenu();

		if (scanf("%d", &choice) != 1)
		{
			// Clear input buffer
			int c;
			while ((c= getchar()) != '\n' && c != EOF)
				;
			myprintf("\nInvalid input! Please enter a number.\n");
			continue;
		}

		switch (choice)
		{
		case 1:
			testCreate(vss);
			break;

		case 2:
			testDelete(vss);
			break;

		case 3:
			testList(vss);
			break;

		case 4:
			testDeleteAll(vss);
			break;

		case 5:
			testMklink(vss);
			break;

		case 6:
			showCurrentInfo(vss);
			break;

		case 7:
			testFull(vss);
			break;

		case 8:
			testStress(vss);
			break;
		case 9:
			testCreateLockedFile();
			break;

		case 0:
			myprintf("\nExiting...\n");
			running= false;
			break;

		default:
			myprintf("\nInvalid choice! Please try again.\n");
		}
	}

	myprintf("\nCleaning up...\n");
}
