int Jidac::extracttobuffer(const std::string &filename, std::vector<uint8_t> &out_buffer)
{
	if (flagdebug)
		myprintf("extracttobuffer %s disize %d\n", filename.c_str(), (int)dt.size());
	DTMap::iterator p= dt.find(filename);
	if (p == dt.end())
	{
		myprintf("08465! cannot find filename %Z\n", filename.c_str());
		return -2;
	}

	// Reference to file data
	DT &f_info= p->second;

	if (f_info.date == 0)
		return -2; // File marked as deleted o non valido

	// 2. Total size calculation and Pre-allocation
	uint64_t total_bytes= 0;
	for (unsigned i= 0; i < f_info.ptr.size(); ++i)
	{
		unsigned j= f_info.ptr[i];
		if (j > 0 && j < ht.size())
			total_bytes+= ht[j].usize;
	}

	try
	{
		out_buffer.resize(total_bytes);
	}
	catch (const std::bad_alloc &e)
	{
		myprintf("08670! cannot resize out_buffer\n");
		return -2; // Insufficient memory
	}

	// Mapping Fragments -> Blocks
	// È necessario sapere in quale blocco compresso si trova ogni frammento.
	f_info.block_for_ptr.resize(f_info.ptr.size());
	int cached_block_idx= 0;

	for (unsigned i= 0; i < f_info.ptr.size(); ++i)
	{
		unsigned j= f_info.ptr[i];
		if (j == 0 || j >= ht.size())
		{
			f_info.block_for_ptr[i]= -1;
			continue;
		}

		int block_idx= -1;
		// Local cache optimization
		if (cached_block_idx < (int)block.size() &&
			j >= block[cached_block_idx].start &&
			j < block[cached_block_idx].start + block[cached_block_idx].frags)
		{
			block_idx= cached_block_idx;
		}
		else
		{
			// Binary search
			unsigned lo= 0, hi= block.size() - 1;
			while (lo <= hi)
			{
				unsigned mid= (lo + hi) / 2;
				if (j < block[mid].start)
				{
					hi= mid - 1;
				}
				else if (j >= block[mid].start + block[mid].frags)
				{
					lo= mid + 1;
				}
				else
				{
					block_idx= mid;
					break;
				}
			}
			// Fallback ricerca lineare
			if (block_idx == -1)
			{
				for (unsigned k= 0; k < block.size(); ++k)
				{
					unsigned next_start= (k + 1 < block.size()) ? block[k + 1].start : (unsigned)ht.size();
					if (j >= block[k].start && j < next_start)
					{
						block_idx= k;
						break;
					}
				}
			}
		}

		if (block_idx != -1)
		{
			f_info.block_for_ptr[i]= block_idx;
			cached_block_idx	   = block_idx;
		}
		else
		{
			f_info.block_for_ptr[i]= -1;
		}
	}

	InputArchive in(archive.c_str());

	// Local cache for decompressed blocks
	std::map<int, string>	   block_cache;
	std::map<unsigned, string> fragment_cache; // Cache per i singoli frammenti

	// Configurazione memoria cache (ridotta rispetto all'estrazione globale, o fissa)
	uint64_t MAX_BLOCK_CACHE_SIZE	= 100 * 1024 * 1024; // Esempio: 100MB limit
	int64_t	 current_block_cache_mem= 0;

	int		last_used_block_idx= -1;
	string *current_block_ptr  = NULL;
	string	temp_block_storage;

	uint64_t  current_buffer_offset= 0;
	const int LOOKAHEAD_WINDOW	   = 50; // Finestra di lookahead (puoi aggiustarla)

	// 5. Extraction loop
	for (unsigned i= 0; i < f_info.ptr.size(); ++i)
	{
		unsigned frag_id  = f_info.ptr[i];
		int		 block_idx= f_info.block_for_ptr[i];

		// Empty/invalid fragment management
		if (block_idx < 0 || frag_id >= ht.size())
		{
			// If fragment does not exist, avanziamo l'offset se previsto,
			// or we skip. Qui assumiamo che ht[frag_id].usize sia 0 o gestito.
			if (frag_id < ht.size())
				current_buffer_offset+= ht[frag_id].usize;
			continue;
		}

		// Frammento già in cache
		if (fragment_cache.count(frag_id))
		{
			string &data= fragment_cache[frag_id];
			// Copia nel buffer
			if (current_buffer_offset + data.size() <= out_buffer.size())
				memcpy(&out_buffer[current_buffer_offset], data.c_str(), data.size());
			current_buffer_offset+= data.size();
			fragment_cache.erase(frag_id);
			continue; // Go to next fragment
		}

		// BLOCK LOADING (if necessary)
		{
			bool block_available= false;
			if (block_idx == last_used_block_idx && current_block_ptr)
			{
				block_available= true;
			}
			else if (block_cache.count(block_idx))
			{
				current_block_ptr  = &block_cache[block_idx];
				last_used_block_idx= block_idx;
				block_available	   = true;
			}

			if (!block_available)
			{
				// Decompressione
				in.seek(block[block_idx].offset, SEEK_SET);
				libzpaq::Decompresser d;
				d.setInput(&in);
				StringBuffer out_sb;
				double		 mem= 0;
				try
				{
					d.findBlock(&mem);
					d.setOutput(&out_sb);
					while (d.findFilename())
					{
						d.readComment();
						d.decompress();
						d.readSegmentEnd();
					}
				}
				catch (...)
				{
					myprintf("08815! decompression error\n");
					// Decompression error handling
					return -1;
				}

				string decompressed_data(out_sb.c_str(), out_sb.size());

				// Block Cache Management (simplified LRU or total purge if full)
				if (int64_t(current_block_cache_mem + decompressed_data.size()) > int64_t(MAX_BLOCK_CACHE_SIZE))
				{
					block_cache.clear();
					current_block_cache_mem= 0;
				}

				// Memorizza
				block_cache[block_idx]= decompressed_data;
				current_block_cache_mem+= decompressed_data.size();
				current_block_ptr  = &block_cache[block_idx];
				last_used_block_idx= block_idx;
			}

			// Load future fragments from same block
			int look_limit= i + LOOKAHEAD_WINDOW;
			if (look_limit > (int)f_info.ptr.size())
				look_limit= f_info.ptr.size();

			for (int k= i; k < look_limit; ++k)
			{
				unsigned future_frag = f_info.ptr[k];
				int		 future_block= f_info.block_for_ptr[k];

				if (future_block == block_idx && fragment_cache.find(future_frag) == fragment_cache.end())
				{
					// Calculate offset within decompressed block
					int64_t	 off	= 0;
					unsigned start_f= block[block_idx].start;
					// Nota: questa somma interna può essere lenta se il blocco ha migliaia di frammenti.
					// ZPAQ usually has contiguous fragments.
					for (unsigned z= start_f; z < future_frag; ++z)
						if (ht[z].usize > 0)
							off+= ht[z].usize;
					int64_t len= ht[future_frag].usize;

					if (off + len <= (int64_t)current_block_ptr->size())
						fragment_cache[future_frag]= current_block_ptr->substr(off, len);
				}
			}
		} // Fine scope caricamento

		// SCRITTURA (Dopo aver caricato il blocco e popolato la cache)
		if (fragment_cache.count(frag_id))
		{
			string &data= fragment_cache[frag_id];
			if (current_buffer_offset + data.size() <= out_buffer.size())
				memcpy(&out_buffer[current_buffer_offset], data.c_str(), data.size());
			current_buffer_offset+= data.size();
			fragment_cache.erase(frag_id);
		}
		else
		{
			myprintf("08878: error, no fragment in cache\n");
			return -1;
		}
	}

	return 0;
}
#endif

#ifdef _WIN32

// Trova una lettera in un vettore di lettere disponibili
static char find_letter_in_vector(char source, const vector<char> &available)
{
	for (size_t i= 0; i < available.size(); ++i)
		if (source == available[i])
			return available[i];
	return 0;
}

// Print error when la lettera non è trovata
static void print_letter_not_found_error(char source, const char *type,
										 const char			*extension,
										 const vector<char> &available)
{
	color_yellow();
	myprintf("24342: Cannot find letter %c in the %s archive image (%s)\n",
			 source, type, extension);
	if (!available.empty())
	{
		myprintf("24432: Available -%s letter ", type);
		for (size_t i= 0; i < available.size(); ++i)
			myprintf("%c ", available[i]);
		myprintf("\n");
	}
	color_restore();
}

// Valida source e destination (char o stringa)
static bool validate_source_dest(char source, char dest, const char *func_name)
{
	if (source == 0 || dest == 0)
	{
		myprintf("23234: %s: invalid source/destination\n", func_name);
		return false;
	}
	return true;
}

static bool validate_source_dest(char source, const string &dest, const char *func_name)
{
	if (source == 0 || dest.empty())
	{
		myprintf("23234: %s: invalid source/destination\n", func_name);
		return false;
	}
	return true;
}

// Find and validate a letter sorgente nel tipo specificato
// Return letter if found, 0 otherwise
char Jidac::find_and_validate_source_letter(char source, ImageType type,
											vector<char> &avail_fhd,
											vector<char> &avail_raw)
{
	if (get_images_filenames(avail_fhd, avail_raw) != 0)
		return 0;

	const vector<char> &available= (type == ImageType::NTFS) ? avail_fhd : avail_raw;
	const char		   *type_str = (type == ImageType::NTFS) ? "ntfs" : "raw";
	const char		   *ext_str	 = (type == ImageType::NTFS) ? ".fhd" : ".raw";

	char found= find_letter_in_vector(source, available);
	if (found == 0)
		print_letter_not_found_error(source, type_str, ext_str, available);

	return found;
}

// Extracts the .meta file for NTFS images
bool Jidac::extract_ntfs_meta(char source)
{
	string imager_image= "image_" + string(1, source) + ".fhd";
	string imager_meta = "image_" + string(1, source) + ".meta";

	if (flagverbose)
	{
		color_cyan();
		myprintf("00005: Source filename %s + meta %s\n",
				 imager_image.c_str(), imager_meta.c_str());
		color_restore();
	}

	int result= extracttobuffer(imager_meta, imager_themetafile);
	if (result != 0)
	{
		myprintf("10433: cannot extract meta!\n");
		return false;
	}

	if (flagverbose)
		myprintf("17441: The meta size is %s\n", migliaia(imager_themetafile.size()));
	imager_excludedarray.clear();
	
	string imager_excluded	 	= "image_" + std::string(1, source) + ".exclud";
	if (flagverbose)
		myprintf("13767: Looking for exclusions %s\n",imager_excluded.c_str());
	
	int howmanyexcluded= extracttobuffer(imager_excluded, imager_excludedarray);
	if (howmanyexcluded != 0)
		myprintf("10432: No excluded founded\n");
	else
	{
		if (flagverbose)
		{
			color_cyan();
			myprintf("13776: Founded an exclusion list of   %21s bytes\n",migliaia(imager_excludedarray.size()));
			color_restore();
		}
	}
	
	
	imager_zeroedarray.clear();
	
	string imager_zeroed	 	= "image_" + std::string(1, source) + ".zeroed";
	if (flagverbose)
		myprintf("13764: Looking for zeroed %s\n",imager_zeroed.c_str());
	
	int howmanyzeroed= extracttobuffer(imager_zeroed, imager_zeroedarray);
	if (howmanyzeroed != 0)
		myprintf("10433: No zeroed founded\n");
	else
	{	
		if (flagverbose)
		{
			color_cyan();
			myprintf("13771: Founded a zero cluster list of %21s bytes\n",migliaia(imager_zeroedarray.size()));
			color_restore();
		}
		if (!imager.setExcludedClustersFromBytes(imager_zeroedarray))
		{
			myprintf("13445: GURU LOADING zeroed array!\n");
		}
		
		
		if (flagdebug2)
		{
			myprintf("DEBUG LOAD: imager_zeroedarray.size() = %zu\n", imager_zeroedarray.size());
			if (imager_zeroedarray.size() >= 4) {
				uint32_t count;
				memcpy(&count, imager_zeroedarray.data(), 4);
				myprintf("DEBUG LOAD: first 4 bytes as uint32 = %u\n", count);
				myprintf("DEBUG LOAD: first 16 bytes hex: ");
				for (size_t i = 0; i < 16 && i < imager_zeroedarray.size(); i++)
					myprintf("%02X ", imager_zeroedarray[i]);
				myprintf("\n");
			}
		}
		
	}
	return true;
}

// Prepare for extraction to disk/stdout
void Jidac::prepare_extract_to_disk(const string &image_filename)
{
	tofiles.clear();
	files.clear();
	files.push_back(image_filename);

	// do NOT invert those two lines! or an "all in" commit limit will be enforced
	g_ramsize  = getramdisksize();
	flagramsize= true;
}

// Print "ready to restore" message
static void print_ready_to_restore(const char *type, char source,
								   const char *dest_type, const char *dest)
{
	color_cyan();
	myprintf("22329: Ready to restore source %s %c to %s %s\n",
			 type, source, dest_type, dest);
	color_restore();
}

static void print_ready_to_restore(const char *type, char source,
								   const char *dest_type, char dest)
{
	color_cyan();
	myprintf("22329: Ready to restore source %s %c to %s %c\n",
			 type, source, dest_type, dest);
	color_restore();
}

int Jidac::get_images_filenames(vector<char> &i_avail_fhd, vector<char> &i_avail_raw)
{
	files.clear();
	archive		  = getbackupnameifany(archive);
	int		errors= 0;
	int64_t sz	  = read_archive(NULL, archive.c_str(), &errors, 0, 0);
	if (sz < 1)
	{
		error("Archive (3) not found");
		return 2;
	}

	if (!get_letters_from_dt(i_avail_fhd, i_avail_raw))
	{
		myprintf("21244: Cannot find zpaqfranz images in the archive\n");
		return 2;
	}

	return 0;
}

int Jidac::restore_ntfs_to_disk(char i_source, char i_destination)
{
	if (!validate_source_dest(i_source, i_destination, "restore_ntfs_to_disk"))
		return 2;

	vector<char> avail_fhd, avail_raw;
	char		 letter= find_and_validate_source_letter(i_source, ImageType::NTFS,
														 avail_fhd, avail_raw);
	if (letter == 0)
		return 2;

	print_ready_to_restore("ntfs", i_source, "physical", i_destination);

	if (!extract_ntfs_meta(i_source))
		return 2;

	string imager_image= "image_" + string(1, i_source) + ".fhd";
	prepare_extract_to_disk(imager_image);

	int estrazione=extractstdout(i_destination, "");
	if (estrazione!=0)
	{
		myprintf("13860: Do not check exclusion due to error\n");
		return estrazione;
	}

	if (imager_zeroedarray.size()>0)
	{
		myprintf("13383: Clearing excluded space on %c\n",i_destination);
		if (!imager.zeroExcludedClusters(i_destination))
		{
			color_red();
			myprintf("44321: Error zeroing!\n");
			color_restore();
			estrazione=2;
		}
		
	}
	
	if (flagzero)
	{
		myprintf("15306: Do not delete excluded files due to -zero\n");
		return estrazione;
	}
	
	if (imager_excludedarray.size()>0)
	{
		myprintf("13386: Deleting excluded %c\n",i_destination);
		if (!imager.deleteExcludedFiles(imager_excludedarray, i_destination))
		{
			myprintf("11388: WARNING cannot delete %s files (%s in total)\n",
			migliaia(imager.getExcludedCannotDelete()),migliaia2(imager.getExcludedExpectedDeleted()));
			estrazione=1;
		}
		else
			myprintf("13888: Excluded delete done!\n");
	}
	return estrazione;

}

int Jidac::restore_raw_to_disk(char i_source, char i_destination)
{
	if (!validate_source_dest(i_source, i_destination, "restore_raw_to_disk"))
		return 2;

	vector<char> avail_fhd, avail_raw;
	char		 letter= find_and_validate_source_letter(i_source, ImageType::RAW,
														 avail_fhd, avail_raw);
	if (letter == 0)
		return 2;

	print_ready_to_restore("raw", i_source, "physical", i_destination);

	string raw_image= "image_" + string(1, i_source) + ".raw";
	prepare_extract_to_disk(raw_image);
	flagraw= true;

	return extractstdout(i_destination, "");
}

int Jidac::restore_ntfs_to_rawfile(char i_source, string i_destfile)
{
	if (!validate_source_dest(i_source, i_destfile, "restore_ntfs_to_rawfile"))
		return 2;

	vector<char> avail_fhd, avail_raw;
	char		 letter= find_and_validate_source_letter(i_source, ImageType::NTFS,
														 avail_fhd, avail_raw);
	if (letter == 0)
		return 2;

	print_ready_to_restore("ntfs", i_source, "file", i_destfile.c_str());

	if (!extract_ntfs_meta(i_source))
		return 2;

	string imager_image= "image_" + string(1, i_source) + ".fhd";
	prepare_extract_to_disk(imager_image);

	return extractstdout(0, i_destfile);
}

int Jidac::restore_raw_to_rawfile(char i_source, string i_destfile)
{
	if (!validate_source_dest(i_source, i_destfile, "restore_raw_to_rawfile"))
		return 2;

	vector<char> avail_fhd, avail_raw;
	char		 letter= find_and_validate_source_letter(i_source, ImageType::RAW,
														 avail_fhd, avail_raw);
	if (letter == 0)
		return 2;

	print_ready_to_restore("raw", i_source, "file", i_destfile.c_str());

	string imager_raw= "image_" + string(1, i_source) + ".raw";

	jidacreset();
	files.clear();
	files.push_back(imager_raw);

	return extract();
}

int Jidac::restore_ntfs_to_vhd(char i_source, string i_destfile)
{
	if (!validate_source_dest(i_source, i_destfile, "restore_ntfs_to_vhd"))
		return 2;

	files.clear();
	return extract();
}

// Partition check result
enum PartitionContentStatus
{
	PARTITION_EMPTY		   = 0, // Empty (or only ignorable system files)
	PARTITION_HAS_FILES	   = 1, // Contains user files
	PARTITION_NOT_READY	   = 2, // Drive not ready (USB/CD non inserito)
	PARTITION_NOT_FOUND	   = 3, // Drive letter does not exist
	PARTITION_ACCESS_DENIED= 4, // Insufficient permissions
	PARTITION_ERROR		   = 5	// Errore generico
};

// Case-insensitive compare helper
static bool str_iequals(const char *a, const char *b)
{
	return _stricmp(a, b) == 0;
}

// Controlla se un file/cartella è da ignorare (roba di sistema Windows)
static bool is_ignorable_system_entry(const WIN32_FIND_DATAA &fd)
{
	const char *name= fd.cFileName;

	// Always ignore . and ..
	if (name[0] == '.')
	{
		if (name[1] == '\0')
			return true;
		if (name[1] == '.' && name[2] == '\0')
			return true;
	}

	// Windows system folders (present on almost every NTFS)
	if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)
	{
		if (str_iequals(name, "System Volume Information"))
			return true;
		if (str_iequals(name, "$RECYCLE.BIN"))
			return true;
		if (str_iequals(name, "RECYCLER")) // XP
			return true;
		if (str_iequals(name, "RECYCLED")) // Win9x
			return true;
		if (str_iequals(name, "$WinREAgent")) // Recovery
			return true;
		if (str_iequals(name, "Recovery"))
			return true;
		if (str_iequals(name, "Boot")) // EFI/Boot partition stuff
			return true;
	}

	// Common system files to ignore
	if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY))
	{
		if (str_iequals(name, "Thumbs.db"))
			return true;
		if (str_iequals(name, "desktop.ini"))
			return true;
		if (str_iequals(name, "Desktop.ini"))
			return true;
		if (str_iequals(name, "AUTORUN.INF"))
			return true;
		if (str_iequals(name, "autorun.inf"))
			return true;
		if (str_iequals(name, "pagefile.sys"))
			return true;
		if (str_iequals(name, "hiberfil.sys"))
			return true;
		if (str_iequals(name, "swapfile.sys"))
			return true;
		if (str_iequals(name, "bootmgr"))
			return true;
		if (str_iequals(name, "BOOTNXT"))
			return true;
		if (str_iequals(name, "BOOTSECT.BAK"))
			return true;

		// Special NTFS files (iniziano con $)
		if (name[0] == '$')
			return true;
	}

	return false;
}

PartitionContentStatus check_partition_content(char drive_letter)
{
	if (drive_letter == 0)
		return PARTITION_ERROR;

	// Normalize to uppercase
	if (drive_letter >= 'a' && drive_letter <= 'z')
		drive_letter= drive_letter - 'a' + 'A';

	if (drive_letter < 'A' || drive_letter > 'Z')
		return PARTITION_ERROR;

	char root_path[4]= {drive_letter, ':', '\\', '\0'};

	// 1. Verify drive exists
	UINT drive_type= GetDriveTypeA(root_path);
	if (drive_type == DRIVE_UNKNOWN || drive_type == DRIVE_NO_ROOT_DIR)
		return PARTITION_NOT_FOUND;

	// 2. Disable error popups for removable drives
	UINT old_error_mode= SetErrorMode(SEM_FAILCRITICALERRORS);

	// 3. Verifica accessibilità
	DWORD spc, bps, fc, tc;
	if (!GetDiskFreeSpaceA(root_path, &spc, &bps, &fc, &tc))
	{
		DWORD err= GetLastError();
		SetErrorMode(old_error_mode);

		if (err == ERROR_NOT_READY)
			return PARTITION_NOT_READY;
		if (err == ERROR_ACCESS_DENIED)
			return PARTITION_ACCESS_DENIED;
		return PARTITION_ERROR;
	}

	// 4. Enumerate root content
	char search_path[8]= {drive_letter, ':', '\\', '*', '\0'};

	WIN32_FIND_DATAA fd;
	HANDLE			 hFind= FindFirstFileA(search_path, &fd);

	SetErrorMode(old_error_mode);

	if (hFind == INVALID_HANDLE_VALUE)
	{
		DWORD err= GetLastError();
		if (err == ERROR_FILE_NOT_FOUND || err == ERROR_NO_MORE_FILES)
			return PARTITION_EMPTY;
		if (err == ERROR_ACCESS_DENIED)
			return PARTITION_ACCESS_DENIED;
		return PARTITION_ERROR;
	}

	PartitionContentStatus result= PARTITION_EMPTY;

	do
	{
		// Ignore Windows system files
		if (is_ignorable_system_entry(fd))
			continue;

		// Any other file/folder (nascosto o no) => non vuota
		// Hidden files ARE considered user content
		result= PARTITION_HAS_FILES;
		break;

	} while (FindNextFileA(hFind, &fd));

	FindClose(hFind);
	return result;
}
bool Jidac::image_risky_continue(char i_source, char i_destination)
{
	if ((i_source == 0) || (i_destination == 0))
	{
		myprintf("22442: Guru in image_risky\n");
		return false;
	}

	if (flagspace)
	{
		color_yellow();
		myprintf("09282: -space flag set, skipping safety check\n");
		color_restore();
		return true;
	}

	PartitionContentStatus status= check_partition_content(i_destination);

	switch (status)
	{
	case PARTITION_EMPTY:
		if (flagverbose)
		{
			color_cyan();
			myprintf("09283: Partition %c:\\ is empty, proceeding\n", i_destination);
			color_restore();
		}
		return true;

	case PARTITION_HAS_FILES:
	{
		color_yellow();
		printDigitalString("RISKY");
		myprintf("\n");
		myprintf("09281: WARNING this command can overwrite data without mercy!\n");
		myprintf("03213: IT IS NOT MEANT FOR UNSKILLED USER!\n");
		color_restore();

		color_cyan();
		myprintf("32441: Source partition letter %c => destination %c NOT EMPTY\n",
				 i_source, i_destination);
		color_restore();

		char temp[80];
		snprintf(temp, sizeof(temp),
				 "Do you really want to OVERWRITE %c: ?", i_destination);

		char yes[10];
		snprintf(yes, sizeof(yes), "YES%c", i_destination);

		return getcaptcha(yes, temp);
	} // <-- closing block

	case PARTITION_NOT_READY:
		color_red();
		myprintf("09284: Drive %c:\\ is not ready (no media?)\n", i_destination);
		color_restore();
		return false;

	case PARTITION_NOT_FOUND:
		color_red();
		myprintf("09285: Drive %c:\\ does not exist\n", i_destination);
		color_restore();
		return false;

	case PARTITION_ACCESS_DENIED:
		color_red();
		myprintf("09286: Access denied to %c:\\ (run as Administrator?)\n", i_destination);
		color_restore();
		return false;

	case PARTITION_ERROR:
	default:
		color_red();
		myprintf("09287: Cannot check partition %c:\\ status\n", i_destination);
		color_restore();
		return false;
	}

	return false; // Mai raggiunto, ma evita warning
}

int Jidac::restoreimage()
{
	if (!iszpaq(archive) && (!isfranzen(archive)))
	{
		myprintf("17385: You need a .zpaq\n");
		return 2;
	}

	if (files.size() != 1)
	{
		myprintf("09377: exactly one parameter needed (for example c:)!\n");
		return 2;
	}

	if (tofiles.size() != 1)
	{
		myprintf("73321: You neeed a single -to\n");
		return 2;
	}

	if (flagimage)
		if((flagntfs+flagraw)==0)
		{
			myprintf("56433: with -image you must use -ntfs or -raw\n");
			return 1;
		}

	if ((flagimage+flagntfs+flagraw)==0)
	{
		myprintf("15643: Nothing to do: no -image, -ntfs or -raw\n");
		return 1;
	}
		
	lettera= getwindowsdriveletter(files[0]);

	// Helper lambda per validare destinazione fisica
	auto validate_physical_dest= [this](char dest_letter) -> int
	{
		franzdriveinfo mydrive;
		int			   partizione= cercapartizione(dest_letter, mydrive);
		if (partizione < 0)
		{
			color_red();
			myprintf("22321: Cannot find the destination drive for letter %c "
					 "(bypass with -force)\n",
					 dest_letter);
			color_restore();
			if (!flagforce)
				return -1;
		}
		else
		{
			color_cyan();
			myprintf("32442: Selected destination\n");
			color_restore();
			printdriveinfo(partizione, mydrive);
		}
		return 0;
	};

	// -image -ntfs => write a thin .ntfs to physical
	if (flagimage && flagntfs)
	{
		if (lettera == 0)
		{
			myprintf("09410: you need a drive letter!\n");
			return 2;
		}
		char dest= getwindowsdriveletter(tofiles[0]);
		if (validate_physical_dest(dest) < 0)
			return 2;
		if (!image_risky_continue(lettera, dest))
			return 2;
		return restore_ntfs_to_disk(lettera, dest);
	}

	// -image -raw => write a raw image to physical
	if (flagimage && flagraw)
	{
		if (lettera == 0)
		{
			myprintf("09410: you need a drive letter!\n");
			return 2;
		}
		char dest= getwindowsdriveletter(tofiles[0]);
		if (validate_physical_dest(dest) < 0)
			return 2;
		if (!image_risky_continue(lettera, dest))
			return 2;
		return restore_raw_to_disk(lettera, dest);
	}

	// -ntfs -raw => write a thin .ntfs to A FILE
	if (flagntfs && flagraw)
	{
		if (lettera == 0)
		{
			myprintf("09410: you need a drive letter!\n");
			return 2;
		}
		if (getwindowsdriveletter(tofiles[0]) != 0)
		{
			myprintf("32334: -ntfs -raw means 'write a ntfs image to a RAW file' "
					 "-to must be a file\n");
			return 2;
		}
		return restore_ntfs_to_rawfile(lettera, tofiles[0]);
	}

	// -raw => write a raw to A FILE
	if (!flagimage && !flagntfs && flagraw)
	{
		if (lettera == 0)
		{
			myprintf("09410: you need a drive letter!\n");
			return 2;
		}
		if (getwindowsdriveletter(tofiles[0]) != 0)
		{
			myprintf("32334: -raw 'write a raw image to a RAW file' "
					 "-to must be a file\n");
			return 2;
		}
		return restore_raw_to_rawfile(lettera, tofiles[0]);
	}

	// -ntfs => extract a .ntfs to a vhd
	if (!flagimage && flagntfs && !flagraw)
	{
		if (lettera == 0)
		{
			myprintf("09410: you need a drive letter!\n");
			return 2;
		}
		if (getwindowsdriveletter(tofiles[0]) != 0)
		{
			myprintf("32334: -ntfs 'extract ntfs image to .VHD' "
					 "-to must be a folder\n");
			return 2;
		}
		return restore_ntfs_to_vhd(lettera, tofiles[0]);
	}

	return 0;
}
#endif


